INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1a5002d-2a82-4ed7-961a-45dac460e13c', '越女詞五首 二', '越女词五首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吳兒多白皙，好爲蕩舟劇。","賣眼擲春心，折花調行客。"]', '["吳兒多白皙，好爲蕩舟劇。","賣眼擲春心，折花調行客。"]', '诗', 'shi', '', NULL, '越女詞五首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91b5f91-553d-4cff-946c-86a75aa9641a', '越女詞五首 三', '越女词五首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["耶溪採蓮女，見客櫂歌迴。","笑入荷花去，佯羞不出來。"]', '["耶溪採蓮女，见客櫂歌迴。","笑入荷花去，佯羞不出来。"]', '诗', 'shi', '', NULL, '越女詞五首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bbaacd-ff02-4272-9c8e-e6a1637c7cc3', '越女詞五首 四', '越女词五首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東陽素足女，會稽素舸郎。","相看月未墮，白地斷肝腸。"]', '["东陽素足女，會稽素舸郎。","相看月未墮，白地斷肝腸。"]', '诗', 'shi', '', NULL, '越女詞五首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f6ea6b-fc90-4fe8-a886-d0249f47ca1e', '越女詞五首 五', '越女词五首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鏡湖水如月，耶溪女似雪。","新妝蕩新波，光景兩奇絕。"]', '["镜湖水如月，耶溪女似雪。","新妝蕩新波，光景兩奇絕。"]', '诗', 'shi', '', NULL, '越女詞五首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179a1c8b-2f36-4e45-8d8f-10c606e5bd5b', '浣紗石上女', '浣紗石上女', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉面耶溪女，青娥紅粉妝。","一雙金齒屐，兩足白如霜。"]', '["玉面耶溪女，青娥紅粉妝。","一雙金齒屐，兩足白如霜。"]', '诗', 'shi', '', NULL, '浣紗石上女 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a36d01-71af-4596-8eb5-6814ea2a5a01', '示金陵子', '示金陵子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金陵城東誰家子，竊聽琴聲碧窗裏。","落花一片天上來，隨人直渡西江水。","楚歌吳語嬌不成，似能未能最有情。","謝公正要東山妓，攜手林泉處處行。"]', '["金陵城东誰家子，竊听琴声碧窗裏。","落花一片天上来，隨人直渡西江水。","楚歌吳語嬌不成，似能未能最有情。","謝公正要东山妓，携手林泉处处行。"]', '诗', 'shi', '', NULL, '示金陵子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e9ca496-b39f-4656-95fa-d3172f410596', '出妓金陵子呈盧六四首 一', '出妓金陵子呈盧六四首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["安石東山三十春，傲然攜妓出風塵。","樓中見我金陵子，何似陽臺雲雨人。"]', '["安石东山三十春，傲然携妓出风塵。","楼中见我金陵子，何似陽台云雨人。"]', '诗', 'shi', '', NULL, '出妓金陵子呈盧六四首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06f4fd03-e1f2-46b0-aa65-ba633506827a', '出妓金陵子呈盧六四首 二', '出妓金陵子呈盧六四首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南國新豐酒，東山小妓歌。","對君君不樂，花月奈愁何。"]', '["南国新豐酒，东山小妓歌。","对君君不乐，花月奈愁何。"]', '诗', 'shi', '', NULL, '出妓金陵子呈盧六四首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c72a47b-053b-4b11-9f15-5062ab4ae138', '出妓金陵子呈盧六四首 三', '出妓金陵子呈盧六四首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東道煙霞主，西江詩酒筵。","相逢不覺醉，日墮歷陽川。"]', '["东道煙霞主，西江诗酒筵。","相逢不覺醉，日墮歷陽川。"]', '诗', 'shi', '', NULL, '出妓金陵子呈盧六四首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4efb1951-8c97-460d-94c3-3228d0e6474f', '出妓金陵子呈盧六四首 四', '出妓金陵子呈盧六四首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小妓金陵歌楚聲，家僮丹砂學鳳鳴。","我亦爲君飲清酒，君心不肯向人傾。"]', '["小妓金陵歌楚声，家僮丹砂学鳳鳴。","我亦爲君饮清酒，君心不肯向人傾。"]', '诗', 'shi', '', NULL, '出妓金陵子呈盧六四首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec2ee4c-87cb-4015-a26b-be3a6d3854d1', '巴女詞', '巴女词', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["巴水急如箭，巴船去若飛。","十月三千里，郎行幾歲歸。"]', '["巴水急如箭，巴船去若飞。","十月三千里，郎行幾歲归。"]', '诗', 'shi', '', NULL, '巴女詞 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ff7ee81-66a3-4390-aadb-0e58801625b9', '哭晁卿衡', '哭晁卿衡', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日本晁卿辭帝都，征帆一片繞蓬壺。","明月不歸沈碧海，白雲愁色滿蒼梧。"]', '["日本晁卿辞帝都，征帆一片繞蓬壺。","明月不归沈碧海，白云愁色满蒼梧。"]', '诗', 'shi', '', NULL, '哭晁卿衡 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b020b1d-0654-4a76-a4e1-b9dbe3ce0820', '自溧水道哭王炎三首 一', '自溧水道哭王炎三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白楊雙行行，白馬悲路傍。","晨興見曉月，更似發雲陽。","溧水通吳關，逝川去未央。","故人萬化盡，閉骨茅山岡。","天上墜玉棺，泉中掩龍章。","名飛日月上，義與風雲翔。","逸氣竟莫展，英圖俄夭傷。","楚國一老人，來嗟龔勝亡。","有言不可道，雪泣憶蘭芳。"]', '["白楊雙行行，白马悲路傍。","晨兴见晓月，更似發云陽。","溧水通吳关，逝川去未央。","故人万化尽，閉骨茅山岡。","天上墜玉棺，泉中掩龙章。","名飞日月上，義與风云翔。","逸氣竟莫展，英圖俄夭傷。","楚国一老人，来嗟龔勝亡。","有言不可道，雪泣憶蘭芳。"]', '诗', 'shi', '', NULL, '自溧水道哭王炎三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1381eb21-aa70-4450-acb8-43cb35e2946e', '自溧水道哭王炎三首 二', '自溧水道哭王炎三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["王公希代寶，棄世一何早。","弔死不及哀，殯宮已秋草。","悲來欲脫劒，挂向何枝好。","哭向茅山雖未摧，一生淚盡丹陽道。"]', '["王公希代寶，棄世一何早。","弔死不及哀，殯宮已秋草。","悲来欲脫劒，挂向何枝好。","哭向茅山雖未摧，一生泪尽丹陽道。"]', '诗', 'shi', '', NULL, '自溧水道哭王炎三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ada597-12de-452d-9396-720dc2506292', '自溧水道哭王炎三首 三', '自溧水道哭王炎三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["王家碧瑤樹，一樹忽先摧。","海內故人泣，天涯弔鶴來。","未成霖雨用，先失濟川材。","一罷廣陵散，鳴琴更不開。"]', '["王家碧瑤樹，一樹忽先摧。","海內故人泣，天涯弔鹤来。","未成霖雨用，先失濟川材。","一罷廣陵散，鳴琴更不开。"]', '诗', 'shi', '', NULL, '自溧水道哭王炎三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d4fe2e9-a528-4997-8877-0621c3689a78', '哭宣城善釀紀叟', '哭宣城善釀紀叟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紀叟黃泉裏，還應釀老春。","夜臺無曉日，沽酒與何人。"]', '["紀叟黄泉裏，還應釀老春。","夜台無晓日，沽酒與何人。"]', '诗', 'shi', '', NULL, '哭宣城善釀紀叟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccb929e1-428b-4f20-80bc-931a506701c4', '宣城哭蔣徵君華', '宣城哭蔣徵君华', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["敬亭埋玉樹，知是蔣徵君。","安得相如草，空餘封禪文。","池臺空有月，詞賦舊凌雲。","獨挂延陵劒，千秋在古墳。"]', '["敬亭埋玉樹，知是蔣徵君。","安得相如草，空餘封禪文。","池台空有月，词賦旧凌云。","独挂延陵劒，千秋在古墳。"]', '诗', 'shi', '', NULL, '宣城哭蔣徵君華 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da2d0f8-74e1-4d1d-bbff-613b43a4bfd6', '鞠歌行', '鞠歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["麗莫似漢宮妃，謙莫似黃家女。","黃女持謙齒髮高，漢妃恃麗天庭去。","人生容德不自保，聖人安用推天道。","君不見蔡澤嵌枯詭怪之形狀，大言直取秦丞相。","又不見田千秋才智不出人，一朝富貴如有神。","二侯行事在方冊，泣麟老人終困厄。","夜光抱恨良歎悲，日月逝矣吾何之。"]', '["丽莫似漢宮妃，謙莫似黄家女。","黄女持謙齒髮高，漢妃恃丽天庭去。","人生容德不自保，聖人安用推天道。","君不见蔡澤嵌枯詭怪之形狀，大言直取秦丞相。","又不见田千秋才智不出人，一朝富貴如有神。","二侯行事在方冊，泣麟老人終困厄。","夜光抱恨良歎悲，日月逝矣吾何之。"]', '诗', 'shi', '', NULL, '鞠歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c630be6b-327d-43c0-9b05-ce3eb2163a14', '胡無人', '胡無人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["十萬羽林兒，臨洮破郅支。","殺添胡地骨，降足漢營旗。","塞闊牛羊散，兵休帳幕移。","空餘隴頭水，嗚咽向人悲。"]', '["十万羽林兒，臨洮破郅支。","殺添胡地骨，降足漢營旗。","塞闊牛羊散，兵休帳幕移。","空餘隴头水，嗚咽向人悲。"]', '诗', 'shi', '', NULL, '胡無人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324dc103-79a2-41b5-9d25-6f34edf86542', '月夜金陵懷古', '月夜金陵懷古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蒼蒼金陵月，空懸帝王州。","天文列宿在，霸業大江流。","綠水絕馳道，青松摧古丘。","臺傾鳷鵲觀，宮沒鳳凰樓。","別殿悲清暑，芳園罷樂遊。","一聞歌玉樹，蕭瑟後庭秋。"]', '["蒼蒼金陵月，空懸帝王州。","天文列宿在，霸業大江流。","綠水絕驰道，青松摧古丘。","台傾鳷鵲观，宮沒鳳凰楼。","別殿悲清暑，芳园罷乐游。","一闻歌玉樹，蕭瑟後庭秋。"]', '诗', 'shi', '', NULL, '月夜金陵懷古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('883a745a-9d91-45b6-b9b1-db4b55f61eae', '冬日歸舊山', '冬日归旧山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["未洗染塵纓，歸來芳草平。","一條藤徑綠，萬點雪峰晴。","地冷葉先盡，谷寒雲不行。","嫩篁侵舍密，古樹倒江橫。","白犬離村吠，蒼苔壁上生。","穿廚孤雉過，臨屋舊猨鳴。","木落禽巢在，籬疎獸路成。","拂牀蒼鼠走，倒篋素魚驚。","洗硯修良策，敲松擬素貞。","此時重一去，去合到三清。"]', '["未洗染塵纓，归来芳草平。","一條藤徑綠，万点雪峰晴。","地冷葉先尽，谷寒云不行。","嫩篁侵舍密，古樹倒江橫。","白犬離村吠，蒼苔壁上生。","穿廚孤雉過，臨屋旧猨鳴。","木落禽巢在，籬疎獸路成。","拂牀蒼鼠走，倒篋素鱼驚。","洗硯修良策，敲松擬素貞。","此时重一去，去合到三清。"]', '诗', 'shi', '', NULL, '冬日歸舊山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c14fb62-852a-49a1-bfa6-2d3baefd45af', '望夫石', '望夫石', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["髣髴古容儀，含愁帶曙輝。","露如今日淚，苔似昔年衣。","有恨同湘女，無言類楚妃。","寂然芳靄內，猶若待夫歸。"]', '["髣髴古容儀，含愁带曙輝。","露如今日泪，苔似昔年衣。","有恨同湘女，無言類楚妃。","寂然芳靄內，猶若待夫归。"]', '诗', 'shi', '', NULL, '望夫石 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7d06a9-3582-4a7a-b6c1-75688af2150b', '對雨', '对雨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["卷簾聊舉目，露濕草綿芊。","古岫藏雲毳，空庭織碎烟。","水紋愁不起，風線重難牽。","盡日扶犂叟，往來江樹前。"]', '["卷簾聊舉目，露濕草綿芊。","古岫藏云毳，空庭织碎烟。","水紋愁不起，风線重难牽。","尽日扶犂叟，往来江樹前。"]', '诗', 'shi', '', NULL, '對雨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3967be5-99ef-4c0e-b3e9-0b967443e22d', '曉晴', '晓晴', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["野涼疎雨歇，春色徧萋萋。","魚躍青池滿，鶯吟綠樹低。","野花妝面濕，山草紐斜齊。","零落殘雪片，風吹挂竹谿。"]', '["野涼疎雨歇，春色徧萋萋。","鱼躍青池满，鶯吟綠樹低。","野花妝面濕，山草紐斜齊。","零落殘雪片，风吹挂竹谿。"]', '诗', 'shi', '', NULL, '曉晴 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f43b04-0c69-4e8c-9726-fc61ba49ee7c', '初月', '初月', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉蟾離海上，白露濕花時。","雲畔風生爪，沙頭水浸眉。","樂哉弦管客，愁殺戰征兒。","因絕西園賞，臨風一詠詩。"]', '["玉蟾離海上，白露濕花时。","云畔风生爪，沙头水浸眉。","乐哉弦管客，愁殺戰征兒。","因絕西园賞，臨风一詠诗。"]', '诗', 'shi', '', NULL, '初月 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfb19e4d-76d0-483e-8a9c-c662467ef043', '雨後望月', '雨後望月', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["四郊陰靄散，開戶半蟾生。","萬里舒霜合，一條江練橫。","出時山眼白，高後海心明。","爲惜如團扇，長吟到五更。"]', '["四郊陰靄散，开戶半蟾生。","万里舒霜合，一條江練橫。","出时山眼白，高後海心明。","爲惜如團扇，长吟到五更。"]', '诗', 'shi', '', NULL, '雨後望月 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c25f0c-49a5-49ee-b42f-5ae627a64f63', '賦得鶴送史司馬赴崔相公幕', '賦得鹤送史司马赴崔相公幕', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["崢嶸丞相府，清切鳳凰池。","羨爾瑤臺鶴，高棲瓊樹枝。","歸飛晴日好，吟弄惠風吹。","正有乘軒樂，初當學舞時。","珍禽在羅網，微命若游絲。","願托周周羽，相銜漢水湄。"]', '["崢嶸丞相府，清切鳳凰池。","羨爾瑤台鹤，高棲瓊樹枝。","归飞晴日好，吟弄惠风吹。","正有乘軒乐，初當学舞时。","珍禽在羅網，微命若游絲。","願托周周羽，相銜漢水湄。"]', '诗', 'shi', '', NULL, '賦得鶴送史司馬赴崔相公幕 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1552ccde-4052-4faa-84d2-272223ed5ec5', '送客歸吳', '送客归吳', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["江村秋雨歇，酒盡一帆飛。","路歷波濤去，家惟坐臥歸。","島花開灼灼，汀柳細依依。","別後無餘事，還應埽釣磯。"]', '["江村秋雨歇，酒尽一帆飞。","路歷波濤去，家惟坐臥归。","島花开灼灼，汀柳細依依。","別後無餘事，還應埽釣磯。"]', '诗', 'shi', '', NULL, '送客歸吳 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b167df-21c5-4e24-9ac8-443735ce164f', '送友生遊峽中', '送友生游峽中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["風靜楊柳垂，看花又別離。","幾年同在此，今日各驅馳。","峽裏聞猨呌，山頭見月時。","殷勤一杯酒，珍重歲寒姿。"]', '["风静楊柳垂，看花又別離。","幾年同在此，今日各驱驰。","峽裏闻猨呌，山头见月时。","殷勤一杯酒，珍重歲寒姿。"]', '诗', 'shi', '', NULL, '送友生遊峽中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7bacfad-487a-4c51-b382-bb9a4d87332b', '送袁明府任長沙', '送袁明府任长沙', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["別離楊柳青，樽酒表丹誠。","古道攜琴去，深山見峽迎。","暖風花繞樹，秋雨草沿城。","自此長江內，無因夜犬驚。"]', '["別離楊柳青，樽酒表丹誠。","古道携琴去，深山见峽迎。","暖风花繞樹，秋雨草沿城。","自此长江內，無因夜犬驚。"]', '诗', 'shi', '', NULL, '送袁明府任長沙 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc213f6-5c78-4785-a051-bfd8e7fa63e7', '鄒衍谷', '鄒衍谷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["燕谷無煖氣，窮巖閉嚴陰。","鄒子一吹律，能迴天地心。"]', '["燕谷無煖氣，窮巖閉嚴陰。","鄒子一吹律，能迴天地心。"]', '诗', 'shi', '', NULL, '鄒衍谷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3d51e7-0092-4575-83be-77f207edd9a3', '雜言用投丹陽知己兼奉宣慰判官', '杂言用投丹陽知己兼奉宣慰判官', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["客從崑崙來，遺我雙玉璞。","云是古之得道者西王母食之餘，食之可以凌太虛。","受之頗謂絕今昔，求識江淮人猶乎比石。","如今雖在卞和手，□□正憔悴。","了了知之亦何益，恭聞士有調相如。","始從鎬京還，復欲鎬京去。","能上秦王殿，何時迴光一相眄。","欲投君，保君年，幸君持取無棄捐。","無棄捐，服之與君俱神仙。"]', '["客從崑崙来，遺我雙玉璞。","云是古之得道者西王母食之餘，食之可以凌太虛。","受之頗謂絕今昔，求識江淮人猶乎比石。","如今雖在卞和手，□□正憔悴。","了了知之亦何益，恭闻士有調相如。","始從鎬京還，复欲鎬京去。","能上秦王殿，何时迴光一相眄。","欲投君，保君年，幸君持取無棄捐。","無棄捐，服之與君俱神仙。"]', '诗', 'shi', '', NULL, '雜言用投丹陽知己兼奉宣慰判官 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938a1650-678a-4b9f-b554-7adba5ad4f21', '觀魚潭', '观鱼潭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["觀魚碧潭上，木落潭水清。","日暮紫鱗躍，圓波處處生。","涼煙浮竹盡，秋月照沙明。","何必滄浪去，茲焉可濯纓。"]', '["观鱼碧潭上，木落潭水清。","日暮紫鱗躍，圓波处处生。","涼煙浮竹尽，秋月照沙明。","何必滄浪去，茲焉可濯纓。"]', '诗', 'shi', '', NULL, '觀魚潭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca361a7-ec8f-4356-8059-0269d49c2157', '自廣平乘醉走馬六十里至邯鄲登城樓覽古書懷', '自廣平乘醉走马六十里至邯鄲登城楼覽古书懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["醉騎白花馬，西走邯鄲城。","揚鞭動柳色，寫鞚春風生。","入郭登高樓，山川與雲平。","深宮翳綠草，萬事傷人情。","相如章華巔，猛氣折秦嬴。","兩虎不可鬬，廉公終負荆。","提攜袴中兒，杵臼及程嬰。","立孤就白刃，必死耀丹誠。","平原三千客，談笑盡豪英。","毛君能頴脫，二國且同盟。","皆爲黃泉土，使我涕縱橫。","磊磊石子岡，蕭蕭白楊聲。","諸賢沒此地，碑版有殘銘。","太古共今時，由來互哀榮。","傷哉何足道，感激仰空名。","趙俗愛長劒，文儒少逢迎。","閑從博陵遊，暢飲雪朝酲。","歌酣易水動，鼓震叢臺傾。","日落把燭歸，凌晨向燕京。","方陳五餌策，一使胡塵清。"]', '["醉騎白花马，西走邯鄲城。","揚鞭动柳色，寫鞚春风生。","入郭登高楼，山川與云平。","深宮翳綠草，万事傷人情。","相如章华巔，猛氣折秦嬴。","兩虎不可鬬，廉公終負荆。","提携袴中兒，杵臼及程嬰。","立孤就白刃，必死耀丹誠。","平原三千客，談笑尽豪英。","毛君能頴脫，二国且同盟。","皆爲黄泉土，使我涕縱橫。","磊磊石子岡，蕭蕭白楊声。","諸賢沒此地，碑版有殘銘。","太古共今时，由来互哀榮。","傷哉何足道，感激仰空名。","趙俗愛长劒，文儒少逢迎。","闲從博陵游，暢饮雪朝酲。","歌酣易水动，鼓震叢台傾。","日落把燭归，凌晨向燕京。","方陳五餌策，一使胡塵清。"]', '诗', 'shi', '', NULL, '自廣平乘醉走馬六十里至邯鄲登城樓覽古書懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a309224f-e137-429e-b4ec-5bba8d73f0ad', '宣州長史弟昭贈余琴谿中雙舞鶴詩以見志', '宣州长史弟昭贈余琴谿中雙舞鹤诗以见志', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["令弟佐宣城，贈余琴谿鶴。","謂言天涯雪，忽向窗前落。","白玉爲毛衣，黃金不肯博。","背風振六翮，對舞臨山閣。","顧我如有情，長鳴似相託。","何當駕此物，與爾騰寥廓。"]', '["令弟佐宣城，贈余琴谿鹤。","謂言天涯雪，忽向窗前落。","白玉爲毛衣，黄金不肯博。","背风振六翮，对舞臨山閣。","顧我如有情，长鳴似相託。","何當駕此物，與爾腾寥廓。"]', '诗', 'shi', '', NULL, '宣州長史弟昭贈余琴谿中雙舞鶴詩以見志 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4968d09f-33f5-46e2-981c-6bcb3be2d9d8', '題舒州司空山瀑布', '題舒州司空山瀑布', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["斷崖如削瓜，嵐光破崖綠。","天河從中來，白雲漲川谷。","玉案赤文字，世眼不可讀。","攝身凌青霄，松風拂我足。"]', '["斷崖如削瓜，嵐光破崖綠。","天河從中来，白云漲川谷。","玉案赤文字，世眼不可读。","攝身凌青霄，松风拂我足。"]', '诗', 'shi', '', NULL, '題舒州司空山瀑布 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91af95d-c3ed-4932-b907-1a638e0a8afe', '金陵新亭', '金陵新亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金陵風景好，豪士集新亭。","舉目山河異，偏傷周顗情。","四坐楚囚悲，不憂社稷傾。","王公何慷慨，千載仰雄名。"]', '["金陵风景好，豪士集新亭。","舉目山河異，偏傷周顗情。","四坐楚囚悲，不憂社稷傾。","王公何慷慨，千載仰雄名。"]', '诗', 'shi', '', NULL, '金陵新亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22159e97-251c-440a-83b4-b6b6387f56c9', '上清寶鼎詩 一', '上清寶鼎诗 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我居清空表，君處紅埃中。","仙人持玉尺，廢君多少才。","玉尺不可盡，君才無時休。"]', '["我居清空表，君处紅埃中。","仙人持玉尺，廢君多少才。","玉尺不可尽，君才無时休。"]', '诗', 'shi', '', NULL, '上清寶鼎詩 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bfa34ff-3532-4774-8bda-8f5e88637854', '上清寶鼎詩 二', '上清寶鼎诗 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嚥服十二環，奄有仙人房。","暮騎紫麟去，海氣侵肌涼。","贈我纍纍珠，靡靡明月光。"]', '["嚥服十二环，奄有仙人房。","暮騎紫麟去，海氣侵肌涼。","贈我纍纍珠，靡靡明月光。"]', '诗', 'shi', '', NULL, '上清寶鼎詩 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1aa65f7-c533-48c5-a405-ae46a3a6e137', '題許宣平菴壁', '題許宣平菴壁', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我吟傳舍詠，來訪真人居。","煙嶺迷高跡，雲林隔太虛。","窺庭但蕭瑟，倚杖空躊躇。","應化遼天鶴，歸當千歲餘。"]', '["我吟傳舍詠，来訪真人居。","煙嶺迷高跡，云林隔太虛。","窺庭但蕭瑟，倚杖空躊躇。","應化遼天鹤，归當千歲餘。"]', '诗', 'shi', '', NULL, '題許宣平菴壁 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d50cb2-d2f6-48bf-b4bf-2226429a2bca', '戲贈杜甫', '戲贈杜甫', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["飯顆山頭逢杜甫，頂戴笠子日卓午。","借問別來太瘦生，總爲從前作詩苦。"]', '["飯顆山头逢杜甫，頂戴笠子日卓午。","借问別来太瘦生，總爲從前作诗苦。"]', '诗', 'shi', '', NULL, '戲贈杜甫 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0011ec-102c-4d51-b204-d5909a1f63eb', '春感詩', '春感诗', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["茫茫南與北，道直事難諧。","榆莢錢生樹，楊花玉糝街。","塵縈遊子面，蝶弄美人釵。","却憶青山上，雲門掩竹齋。"]', '["茫茫南與北，道直事难諧。","榆莢錢生樹，楊花玉糝街。","塵縈游子面，蝶弄美人釵。","却憶青山上，云门掩竹斋。"]', '诗', 'shi', '', NULL, '春感詩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8938db72-4784-4d3e-ba8c-f9fe6174dc58', '白微時募縣小吏入令臥內嘗驅牛經堂下令妻怒將加詰責白亟以詩謝云', '白微时募縣小吏入令臥內嘗驱牛經堂下令妻怒將加詰責白亟以诗謝云', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["素面倚欄鉤，嬌聲出外頭。","若非是織女，何得問牽牛。"]', '["素面倚欄鉤，嬌声出外头。","若非是织女，何得问牽牛。"]', '诗', 'shi', '', NULL, '白微時募縣小吏入令臥內嘗驅牛經堂下令妻怒將加詰責白亟以詩謝云 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2b38c6-e869-4ce3-b8c6-0bbce1d30892', '句', '句', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["焰隨紅日去，煙逐暮雲飛。","綠鬢隨波散，紅顏逐浪無。","因何逢伍相，應是想秋胡。","舉袖露條脫，招我飯胡麻。"]', '["焰隨紅日去，煙逐暮云飞。","綠鬢隨波散，紅顏逐浪無。","因何逢伍相，應是想秋胡。","舉袖露條脫，招我飯胡麻。"]', '诗', 'shi', '', NULL, '句 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81879f9-92ef-4102-85fc-9262132b1bea', '擬古詩十二首 一', '擬古诗十二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["辭君遠行邁，飲此長恨端。","已謂道里遠，如何中險艱。","流水赴大壑，孤雲還暮山。","無情尚有歸，行子何獨難。","驅車背鄉園，朔風卷行迹。","嚴冬霜斷肌，日入不遑息。","憂歡容髮變，寒暑人事易。","中心君詎知，冰玉徒貞白。"]', '["辞君远行邁，饮此长恨端。","已謂道里远，如何中險艱。","流水赴大壑，孤云還暮山。","無情尚有归，行子何独难。","驱车背乡园，朔风卷行迹。","嚴冬霜斷肌，日入不遑息。","憂歡容髮变，寒暑人事易。","中心君詎知，冰玉徒貞白。"]', '诗', 'shi', '', NULL, '擬古詩十二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c22f5d58-f0de-4f54-872a-3373e0f6bb58', '擬古詩十二首 二', '擬古诗十二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["黃鳥何關關，幽蘭亦靡靡。","此時深閨婦，日照紗窗裏。","娟娟雙青娥，微微啓玉齒。","自惜桃李年，誤身遊俠子。","無事久離別，不知今生死。"]', '["黄鸟何关关，幽蘭亦靡靡。","此时深閨婦，日照紗窗裏。","娟娟雙青娥，微微啓玉齒。","自惜桃李年，誤身游俠子。","無事久離別，不知今生死。"]', '诗', 'shi', '', NULL, '擬古詩十二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5174ca76-0016-4f4f-ba75-34bc3de872b2', '擬古詩十二首 三', '擬古诗十二首 三', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["峨峨高山巔，浼浼青川流。","世人不自悟，馳謝如驚飍。","百金非所重，厚意良難得。","旨酒親與朋，芳年樂京國。","京城繁華地，軒蓋凌晨出。","垂楊十二衢，隱暎金張室。","漢宮南北對，飛觀齊白日。","游泳屬芳時，平生自云畢。"]', '["峨峨高山巔，浼浼青川流。","世人不自悟，驰謝如驚飍。","百金非所重，厚意良难得。","旨酒親與朋，芳年乐京国。","京城繁华地，軒蓋凌晨出。","垂楊十二衢，隐暎金張室。","漢宮南北对，飞观齊白日。","游泳屬芳时，平生自云畢。"]', '诗', 'shi', '', NULL, '擬古詩十二首 三 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0c9861-665b-4e00-9ec5-eb4b017bf664', '擬古詩十二首 四', '擬古诗十二首 四', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["綺樓何氛氳，朝日正杲杲。","四壁含清風，丹霞射其牖。","玉顏上哀囀，絕耳非世有。","但感離恨情，不知誰家婦。","孤雲忽無色，邊馬爲回首。","曲絕碧天高，餘聲散秋草。","徘徊帷中意，獨夜不堪守。","思逐朔風翔，一去千里道。"]', '["綺楼何氛氳，朝日正杲杲。","四壁含清风，丹霞射其牖。","玉顏上哀囀，絕耳非世有。","但感離恨情，不知誰家婦。","孤云忽無色，邊马爲回首。","曲絕碧天高，餘声散秋草。","徘徊帷中意，独夜不堪守。","思逐朔风翔，一去千里道。"]', '诗', 'shi', '', NULL, '擬古詩十二首 四 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f84e421e-25b4-4b12-81d5-2dda8638e7dc', '擬古詩十二首 五', '擬古诗十二首 五', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["嘉樹藹初綠，靡蕪吐幽芳。","君子不在賞，寄之雲路長。","路長信難越，惜此芳時歇。","孤鳥去不還，緘情向天末。"]', '["嘉樹藹初綠，靡蕪吐幽芳。","君子不在賞，寄之云路长。","路长信难越，惜此芳时歇。","孤鸟去不還，緘情向天末。"]', '诗', 'shi', '', NULL, '擬古詩十二首 五 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('907d645d-c71a-47d3-9839-d533267777cc', '擬古詩十二首 六', '擬古诗十二首 六', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["月滿秋夜長，驚烏號北林。","天河橫未落，斗柄當西南。","寒蛩悲洞房，好鳥無遺音。","商飆一夕至，獨宿懷重衾。","舊交日千里，隔我浮與沈。","人生豈草木，寒暑移此心。"]', '["月满秋夜长，驚烏號北林。","天河橫未落，斗柄當西南。","寒蛩悲洞房，好鸟無遺音。","商飆一夕至，独宿懷重衾。","旧交日千里，隔我浮與沈。","人生豈草木，寒暑移此心。"]', '诗', 'shi', '', NULL, '擬古詩十二首 六 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51190e9d-a05d-40e7-929f-b1f9ae5dacbd', '擬古詩十二首 七', '擬古诗十二首 七', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["酒星非所酌，月桂不爲食。","虛薄空有名，爲君長歎息。","蘭蕙雖可懷，芳香與時息。","豈如凌霜葉，歲暮藹顏色。","折柔將有贈，延意千里客。","草木知賤微，所貴寒不易。"]', '["酒星非所酌，月桂不爲食。","虛薄空有名，爲君长歎息。","蘭蕙雖可懷，芳香與时息。","豈如凌霜葉，歲暮藹顏色。","折柔將有贈，延意千里客。","草木知賤微，所貴寒不易。"]', '诗', 'shi', '', NULL, '擬古詩十二首 七 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fff406b3-57a8-42dc-85cf-65824402eec4', '擬古詩十二首 八', '擬古诗十二首 八', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["神州高爽地，遐瞰靡不通。","寒月野無綠，寥寥天宇空。","陰陽不停馭，貞脆各有終。","汾沮何鄙儉，考槃何退窮。","反志解牽跼，無爲尚勞躬。","美人奪南國，一笑開芙蓉。","清鏡理容髮，褰簾出深重。","豔曲呈皓齒，舞羅不堪風。","慊慊情有待，贈芳爲我容。","可嗟青樓月，流影君帷中。"]', '["神州高爽地，遐瞰靡不通。","寒月野無綠，寥寥天宇空。","陰陽不停馭，貞脆各有終。","汾沮何鄙儉，考槃何退窮。","反志解牽跼，無爲尚勞躬。","美人奪南国，一笑开芙蓉。","清镜理容髮，褰簾出深重。","豔曲呈皓齒，舞羅不堪风。","慊慊情有待，贈芳爲我容。","可嗟青楼月，流影君帷中。"]', '诗', 'shi', '', NULL, '擬古詩十二首 八 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580567df-30f6-453f-aa5b-d0a0d274f99b', '擬古詩十二首 九', '擬古诗十二首 九', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["春至林木變，洞房夕含清。","單居誰能裁，好鳥對我鳴。","良人久燕趙，新愛移平生。","別時雙鴛綺，留此千恨情。","碧草生舊迹，綠琴歇芳聲。","思將魂夢歡，反側寐不成。","攬衣迷所次，起望空前庭。","孤影中自惻，不知雙涕零。"]', '["春至林木变，洞房夕含清。","單居誰能裁，好鸟对我鳴。","良人久燕趙，新愛移平生。","別时雙鴛綺，留此千恨情。","碧草生旧迹，綠琴歇芳声。","思將魂梦歡，反側寐不成。","攬衣迷所次，起望空前庭。","孤影中自惻，不知雙涕零。"]', '诗', 'shi', '', NULL, '擬古詩十二首 九 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a9cf3f6-e425-4854-9623-1815fc769f97', '擬古詩十二首 十', '擬古诗十二首 十', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秋天無留景，萬物藏光輝。","落葉隨風起，愁人獨何依。","華月屢圓缺，君還浩無期。","如何雨絕天，一去音問違。"]', '["秋天無留景，万物藏光輝。","落葉隨风起，愁人独何依。","华月屢圓缺，君還浩無期。","如何雨絕天，一去音问違。"]', '诗', 'shi', '', NULL, '擬古詩十二首 十 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb39fc22-c738-4644-b7d2-068403c6e047', '擬古詩十二首 十一', '擬古诗十二首 十一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["有客天一方，寄我孤桐琴。","迢迢萬里隔，託此傳幽音。","冰霜中自結，龍鳳相與吟。","絃以明直道，漆以固交深。"]', '["有客天一方，寄我孤桐琴。","迢迢万里隔，託此傳幽音。","冰霜中自結，龙鳳相與吟。","絃以明直道，漆以固交深。"]', '诗', 'shi', '', NULL, '擬古詩十二首 十一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f05bfa6a-aed8-4bf9-9c53-caa640e22c6b', '擬古詩十二首 十二', '擬古诗十二首 十二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["白日淇上沒，空閨生遠愁。","寸心不可限，淇水長悠悠。","芳樹自妍芳，春禽自相求。","徘徊東西廂，孤妾誰與儔。","年華逐絲淚，一落俱不收。"]', '["白日淇上沒，空閨生远愁。","寸心不可限，淇水长悠悠。","芳樹自妍芳，春禽自相求。","徘徊东西廂，孤妾誰與儔。","年华逐絲泪，一落俱不收。"]', '诗', 'shi', '', NULL, '擬古詩十二首 十二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8607ee04-dce7-4d86-8b41-5844798ce148', '雜體五首 一', '杂體五首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["沈沈匣中鏡，爲此塵垢蝕。","輝光何所如，月在雲中黑。","南金既雕錯，鞶帶共輝飾。","空存鑒物名，坐使妍蚩惑。","美人竭肝膽，思照冰玉色。","自非磨瑩工，日日空嘆息。"]', '["沈沈匣中镜，爲此塵垢蝕。","輝光何所如，月在云中黑。","南金既雕錯，鞶带共輝飾。","空存鑒物名，坐使妍蚩惑。","美人竭肝膽，思照冰玉色。","自非磨瑩工，日日空嘆息。"]', '诗', 'shi', '', NULL, '雜體五首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f63d03-a042-4097-a55c-f7ea652657a2', '雜體五首 二', '杂體五首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["古宅集祆鳥，羣號枯樹枝。","黃昏窺人室，鬼物相與期。","居人不安寢，搏擊思此時。","豈無鷹與鸇，飽肉不肯飛。","既乖逐鳥節，空養凌雲姿。","孤負肉食恩，何異城上鴟。"]', '["古宅集祆鸟，羣號枯樹枝。","黄昏窺人室，鬼物相與期。","居人不安寢，搏擊思此时。","豈無鷹與鸇，飽肉不肯飞。","既乖逐鸟節，空養凌云姿。","孤負肉食恩，何異城上鴟。"]', '诗', 'shi', '', NULL, '雜體五首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffbd3115-d22a-4e51-9fe1-2887fe021bbb', '雜體五首 三', '杂體五首 三', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["春羅雙鴛鴦，出自寒夜女。","心精煙霧色，指歷千萬緒。","長安貴豪家，妖豔不可數。","裁此百日功，唯將一朝舞。","舞罷復裁新，豈思勞者苦。"]', '["春羅雙鴛鴦，出自寒夜女。","心精煙霧色，指歷千万緒。","长安貴豪家，妖豔不可數。","裁此百日功，唯將一朝舞。","舞罷复裁新，豈思勞者苦。"]', '诗', 'shi', '', NULL, '雜體五首 三 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99f718cc-d4e8-4c98-9694-0f0b46ec29cb', '雜體五首 四', '杂體五首 四', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["同聲自相應，體質不必齊。","誰知賈人鐸，能使大樂諧。","鏗鏘發宮徵，和樂變其哀。","人神既昭享，鳳鳥亦下來。","豈非至賤物，一奏升天階。","物情苟有合，莫問玉與泥。"]', '["同声自相應，體質不必齊。","誰知賈人鐸，能使大乐諧。","鏗鏘發宮徵，和乐变其哀。","人神既昭享，鳳鸟亦下来。","豈非至賤物，一奏升天階。","物情苟有合，莫问玉與泥。"]', '诗', 'shi', '', NULL, '雜體五首 四 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b0ce27-8e7b-4a57-aa95-948a6f4e7416', '雜體五首 五', '杂體五首 五', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["碌碌荆山璞，卞和獻君門。","荆璞非有求，和氏非有恩。","所獻知國寶，至公不待言。","是非吾欲默，此道今豈存。"]', '["碌碌荆山璞，卞和獻君门。","荆璞非有求，和氏非有恩。","所獻知国寶，至公不待言。","是非吾欲默，此道今豈存。"]', '诗', 'shi', '', NULL, '雜體五首 五 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4474e54f-e79a-4d01-8a8c-2e0ce79fc86b', '與友生野飲效陶體', '與友生野饮效陶體', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["攜酒花林下，前有千載墳。","於時不共酌，奈此泉下人。","始自翫芳物，行當念徂春。","聊舒遠世蹤，坐望還山雲。","且遂一歡笑，焉知賤與貧。"]', '["携酒花林下，前有千載墳。","於时不共酌，奈此泉下人。","始自翫芳物，行當念徂春。","聊舒远世蹤，坐望還山云。","且遂一歡笑，焉知賤與貧。"]', '诗', 'shi', '', NULL, '與友生野飲效陶體 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bec7dde-19d2-4417-853a-cdf536bdb908', '效何水部二首 一', '效何水部二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["玉宇含清露，香籠散輕煙。","應當結沈抱，難從茲夕眠。"]', '["玉宇含清露，香籠散轻煙。","應當結沈抱，难從茲夕眠。"]', '诗', 'shi', '', NULL, '效何水部二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3ed695-4ade-4738-85fd-69d006e8c7e4', '效何水部二首 二', '效何水部二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夕漏起遙恨，蟲響亂秋陰。","反覆相思字，中有故人心。"]', '["夕漏起遙恨，蟲响亂秋陰。","反覆相思字，中有故人心。"]', '诗', 'shi', '', NULL, '效何水部二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd32e1c1-aef1-45b1-a97d-18b710aa4c21', '效陶彭澤', '效陶彭澤', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["霜露悴百草，時菊獨妍華。","物性有如此，寒暑其奈何。","掇英泛濁醪，日入會田家。","盡醉茅簷下，一生豈在多。"]', '["霜露悴百草，时菊独妍华。","物性有如此，寒暑其奈何。","掇英泛濁醪，日入會田家。","尽醉茅簷下，一生豈在多。"]', '诗', 'shi', '', NULL, '效陶彭澤 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08f12ae-400b-4d0c-98fb-382020e3534a', '大梁亭會李四栖梧作', '大梁亭會李四栖梧作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["梁王昔愛才，千古化不泯。","至今蓬池上，遠集八方賓。","車馬平明合，城郭滿埃塵。","逢君一相許，豈要平生親。","入仕三十載，如何獨未伸。","英聲久籍籍，臺閣多故人。","置酒發清彈，相與樂佳辰。","孤亭得長望，白日下廣津。","富貴良可取，朅來西入秦。","秋風旦夕起，安得客梁陳。"]', '["梁王昔愛才，千古化不泯。","至今蓬池上，远集八方賓。","车马平明合，城郭满埃塵。","逢君一相許，豈要平生親。","入仕三十載，如何独未伸。","英声久籍籍，台閣多故人。","置酒發清彈，相與乐佳辰。","孤亭得长望，白日下廣津。","富貴良可取，朅来西入秦。","秋风旦夕起，安得客梁陳。"]', '诗', 'shi', '', NULL, '大梁亭會李四栖梧作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c03c2b-a954-4666-b1fa-46f0164a8205', '燕李錄事', '燕李錄事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["與君十五侍皇闈，曉拂爐煙上赤墀。","花開漢苑經過處，雪下驪山沐浴時。","近臣零落今猶在，仙駕飄颻不可期。","此日相逢思舊日，一杯成喜亦成悲。"]', '["與君十五侍皇闈，晓拂爐煙上赤墀。","花开漢苑經過处，雪下驪山沐浴时。","近臣零落今猶在，仙駕飄颻不可期。","此日相逢思旧日，一杯成喜亦成悲。"]', '诗', 'shi', '', NULL, '燕李錄事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a68013c8-4630-41c6-a5ee-a658b57f58fe', '淮上喜會梁川故人', '淮上喜會梁川故人', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["江漢曾爲客，相逢每醉還。","浮雲一別後，流水十年間。","歡笑情如舊，蕭疎鬢已斑。","何因北歸去，淮上對秋山。"]', '["江漢曾爲客，相逢每醉還。","浮云一別後，流水十年间。","歡笑情如旧，蕭疎鬢已斑。","何因北归去，淮上对秋山。"]', '诗', 'shi', '', NULL, '淮上喜會梁川故人 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53682af7-3c97-4fde-8f14-973c6efb436e', '揚州偶會前洛陽盧耿主簿', '揚州偶會前洛陽盧耿主簿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["楚塞故人稀，相逢本不期。","猶存袖裏字，忽怪鬢中絲。","客舍盈樽酒，江行滿篋詩。","更能連騎出，還似洛橋時。"]', '["楚塞故人稀，相逢本不期。","猶存袖裏字，忽怪鬢中絲。","客舍盈樽酒，江行满篋诗。","更能連騎出，還似洛橋时。"]', '诗', 'shi', '', NULL, '揚州偶會前洛陽盧耿主簿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041d8e9d-5906-4ee2-ad1b-8b81a8ea8612', '賈常侍林亭燕集', '賈常侍林亭燕集', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高賢侍天陛，跡顯心獨幽。","朱軒騖關右，池館在東周。","繚繞接都城，氤氳望嵩丘。","羣公盡詞客，方駕永日遊。","朝旦氣候佳，逍遙寫煩憂。","綠林藹已布，華沼澹不流。","沒露摘幽草，涉煙翫輕舟。","圓荷既出水，廣廈可淹留。","放神遺所拘，觥罰屢見酬。","樂燕良未極，安知有沈浮。","醉罷各云散，何當復相求。"]', '["高賢侍天陛，跡显心独幽。","朱軒騖关右，池館在东周。","繚繞接都城，氤氳望嵩丘。","羣公尽词客，方駕永日游。","朝旦氣候佳，逍遙寫煩憂。","綠林藹已布，华沼澹不流。","沒露摘幽草，涉煙翫轻舟。","圓荷既出水，廣廈可淹留。","放神遺所拘，觥罰屢见酬。","乐燕良未極，安知有沈浮。","醉罷各云散，何當复相求。"]', '诗', 'shi', '', NULL, '賈常侍林亭燕集 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a4f746-8aca-47d8-8284-10d4232c2cf3', '月下會徐十一草堂', '月下會徐十一草堂', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["空齋無一事，岸幘故人期。","暫輟觀書夜，還題翫月詩。","遠鐘高枕後，清露捲簾時。","暗覺新秋近，殘河欲曙遲。"]', '["空斋無一事，岸幘故人期。","暫輟观书夜，還題翫月诗。","远鐘高枕後，清露捲簾时。","暗覺新秋近，殘河欲曙遲。"]', '诗', 'shi', '', NULL, '月下會徐十一草堂 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75a4757e-314f-46c5-a0ab-62231748b2a2', '移疾會詩客元生與釋子法朗因貽諸祠曹', '移疾會诗客元生與釋子法朗因貽諸祠曹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["對此嘉樹林，獨有戚戚顏。","抱瘵知曠職，淹旬非樂閑。","釋子來問訊，詩人亦扣關。","道同意暫遣，客散疾徐還。","園徑自幽靜，玄蟬噪其間。","高牕瞰遠郊，暮色起秋山。","英曹幸休暇，悢悢心所攀。"]', '["对此嘉樹林，独有戚戚顏。","抱瘵知曠職，淹旬非乐闲。","釋子来问訊，诗人亦扣关。","道同意暫遣，客散疾徐還。","园徑自幽静，玄蟬噪其间。","高牕瞰远郊，暮色起秋山。","英曹幸休暇，悢悢心所攀。"]', '诗', 'shi', '', NULL, '移疾會詩客元生與釋子法朗因貽諸祠曹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4ea207f-f164-4ca6-8901-823d810415a4', '慈恩伽藍清會', '慈恩伽藍清會', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["素友俱薄世，屢招清景賞。","鳴鐘悟音聞，宿昔心已往。","重門相洞達，高宇亦遐朗。","嵐嶺曉城分，清陰夏條長。","氳氛芳臺馥，蕭散竹池廣。","平荷隨波泛，廻飆激林響。","蔬食遵道侶，泊懷遺滯想。","何彼塵昏人，區區在天壤。"]', '["素友俱薄世，屢招清景賞。","鳴鐘悟音闻，宿昔心已往。","重门相洞達，高宇亦遐朗。","嵐嶺晓城分，清陰夏條长。","氳氛芳台馥，蕭散竹池廣。","平荷隨波泛，廻飆激林响。","蔬食遵道侶，泊懷遺滯想。","何彼塵昏人，區區在天壤。"]', '诗', 'shi', '', NULL, '慈恩伽藍清會 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc18fdb-04fc-482f-b298-835d6f82c2de', '夜偶詩客操公作', '夜偶诗客操公作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["塵襟一瀟灑，清夜得禪公。","遠自鶴林寺，了知人世空。","驚禽翻暗葉，流水注幽叢。","多謝非玄度，聊將詩興同。"]', '["塵襟一瀟灑，清夜得禪公。","远自鹤林寺，了知人世空。","驚禽翻暗葉，流水注幽叢。","多謝非玄度，聊將诗兴同。"]', '诗', 'shi', '', NULL, '夜偶詩客操公作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3d71d7-b2e1-4dda-803c-42208f327175', '與韓庫部會王祠曹宅作', '與韓庫部會王祠曹宅作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["閑門蔭堤柳，秋渠含夕清。","微風送荷氣，坐客散塵纓。","守默共無恡，抱沖俱寡營。","良時頗高會，琴酌共開情。"]', '["闲门蔭堤柳，秋渠含夕清。","微风送荷氣，坐客散塵纓。","守默共無恡，抱沖俱寡營。","良时頗高會，琴酌共开情。"]', '诗', 'shi', '', NULL, '與韓庫部會王祠曹宅作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b963cc-4793-49f5-a117-4fb409b1a6bd', '晦日處士叔園林燕集', '晦日处士叔园林燕集', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遽看蓂葉盡，坐闕芳年賞。","賴此林下期，清風滌煩想。","始萌動新煦，佳禽發幽響。","嵐嶺對高齋，春流灌蔬壤。","罇酒遺形迹，道言屢開獎。","幸蒙終夕懽，聊用稅歸鞅。"]', '["遽看蓂葉尽，坐闕芳年賞。","賴此林下期，清风滌煩想。","始萌动新煦，佳禽發幽响。","嵐嶺对高斋，春流灌蔬壤。","罇酒遺形迹，道言屢开獎。","幸蒙終夕懽，聊用稅归鞅。"]', '诗', 'shi', '', NULL, '晦日處士叔園林燕集 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09302e16-18a6-4af9-9188-4f2932512a02', '扈亭西陂燕賞', '扈亭西陂燕賞', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["杲杲朝陽時，悠悠清陂望。","嘉樹始氤氳，春遊方浩蕩。","況逢文翰侶，愛此孤舟漾。","綠野際遙波，橫雲分疊嶂。","公堂日爲倦，幽襟自茲曠。","有酒今滿盈，願君盡弘量。"]', '["杲杲朝陽时，悠悠清陂望。","嘉樹始氤氳，春游方浩蕩。","況逢文翰侶，愛此孤舟漾。","綠野際遙波，橫云分叠嶂。","公堂日爲倦，幽襟自茲曠。","有酒今满盈，願君尽弘量。"]', '诗', 'shi', '', NULL, '扈亭西陂燕賞 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97bf03c6-59e1-4c4e-8662-2a10b6ed9e3a', '西郊燕集', '西郊燕集', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["濟濟衆君子，高宴及時光。","羣山靄遐矚，綠野布熙陽。","列坐遵曲岸，披襟襲蘭芳。","野庖薦嘉魚，激澗泛羽觴。","衆鳥鳴茂林，綠草延高岡。","盛時易徂謝，浩思坐飄颺。","眷言同心友，茲遊安可忘。"]', '["濟濟衆君子，高宴及时光。","羣山靄遐矚，綠野布熙陽。","列坐遵曲岸，披襟襲蘭芳。","野庖薦嘉鱼，激澗泛羽觴。","衆鸟鳴茂林，綠草延高岡。","盛时易徂謝，浩思坐飄颺。","眷言同心友，茲游安可忘。"]', '诗', 'shi', '', NULL, '西郊燕集 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2a3be1-a81d-4e0a-84ac-e59153eabd63', '春宵燕萬年吉少府中孚南館', '春宵燕万年吉少府中孚南館', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["始見斗柄廻，復茲霜月霽。","河漢上縱橫，春城夜迢遞。","賓筵接時彥，樂燕凌芳歲。","稍愛清觴滿，仰歎高文麗。","欲去返郊扉，端爲一歡滯。"]', '["始见斗柄廻，复茲霜月霽。","河漢上縱橫，春城夜迢遞。","賓筵接时彥，乐燕凌芳歲。","稍愛清觴满，仰歎高文丽。","欲去返郊扉，端爲一歡滯。"]', '诗', 'shi', '', NULL, '春宵燕萬年吉少府中孚南館 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e981288b-2b04-44af-bd84-6ab0328d5947', '滁州園池燕元氏親屬', '滁州园池燕元氏親屬', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["日暮遊清池，疎林羅高天。","餘綠飄霜露，夕氣變風煙。","水門架危閣，竹亭列廣筵。","一展私姻禮，屢歎芳樽前。","感往在茲會，傷離屬頽年。","明晨復云去，且願此流連。"]', '["日暮游清池，疎林羅高天。","餘綠飄霜露，夕氣变风煙。","水门架危閣，竹亭列廣筵。","一展私姻禮，屢歎芳樽前。","感往在茲會，傷離屬頽年。","明晨复云去，且願此流連。"]', '诗', 'shi', '', NULL, '滁州園池燕元氏親屬 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60683818-e720-49ee-9441-c70d097687cd', '郡樓春燕', '郡楼春燕', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["衆樂雜軍鞞，高樓邀上客。","思逐花光亂，賞餘山景夕。","爲郡訪彫瘵，守程難損益。","聊假一杯歡，暫忘終日迫。"]', '["衆乐杂軍鞞，高楼邀上客。","思逐花光亂，賞餘山景夕。","爲郡訪彫瘵，守程难損益。","聊假一杯歡，暫忘終日迫。"]', '诗', 'shi', '', NULL, '郡樓春燕 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982d08cf-9bb3-46d7-b116-f1db398b1c1f', '南塘泛舟會元六昆季', '南塘泛舟會元六昆季', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["端居倦時燠，輕舟泛廻塘。","微風飄襟散，橫吹繞林長。","雲澹水容夕，雨微荷氣涼。","一寫悁勤意，寧用訴華觴。"]', '["端居倦时燠，轻舟泛廻塘。","微风飄襟散，橫吹繞林长。","云澹水容夕，雨微荷氣涼。","一寫悁勤意，寧用訴华觴。"]', '诗', 'shi', '', NULL, '南塘泛舟會元六昆季 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f5ded08-4f6f-4641-878e-897904483479', '郡齋雨中與諸文士燕集', '郡斋雨中與諸文士燕集', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["兵衛森畫戟，宴寢凝清香。","海上風雨至，逍遙池閣涼。","煩疴近消散，嘉賓復滿堂。","自慙居處崇，未覩斯民康。","理會是非遣，性達形迹忘。","鮮肥屬時禁，蔬果幸見嘗。","俯飲一杯酒，仰聆金玉章。","神歡體自輕，意欲凌風翔。","吳中盛文史，羣彥今汪洋。","方知大藩地，豈曰財賦疆。"]', '["兵衛森畫戟，宴寢凝清香。","海上风雨至，逍遙池閣涼。","煩疴近消散，嘉賓复满堂。","自慙居处崇，未覩斯民康。","理會是非遣，性達形迹忘。","鲜肥屬时禁，蔬果幸见嘗。","俯饮一杯酒，仰聆金玉章。","神歡體自轻，意欲凌风翔。","吳中盛文史，羣彥今汪洋。","方知大藩地，豈曰財賦疆。"]', '诗', 'shi', '', NULL, '郡齋雨中與諸文士燕集 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5bd232b-a644-4320-acc1-8944ef3287c9', '軍中冬燕', '軍中冬燕', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["滄海已云晏，皇恩猶念勤。","式燕徧恆秩，柔遠及斯人。","茲邦實大藩，伐鼓軍樂陳。","是時冬服成，戎士氣益振。","虎竹謬朝寄，英賢降上賓。","旋罄周旋禮，媿無海陸珍。","庭中九劍闌，堂上歌吹新。","光景不知晚，觥酌豈言頻。","單醪昔所感，大醵況同忻。","顧謂軍中士，仰答何由申。"]', '["滄海已云晏，皇恩猶念勤。","式燕徧恆秩，柔远及斯人。","茲邦實大藩，伐鼓軍乐陳。","是时冬服成，戎士氣益振。","虎竹謬朝寄，英賢降上賓。","旋罄周旋禮，媿無海陸珍。","庭中九劍闌，堂上歌吹新。","光景不知晚，觥酌豈言頻。","單醪昔所感，大醵況同忻。","顧謂軍中士，仰答何由申。"]', '诗', 'shi', '', NULL, '軍中冬燕 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81be33a1-4c5c-448d-b228-f9abac3cac39', '司空主簿琴席', '司空主簿琴席', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["煙華方散薄，蕙氣猶含露。","澹景發清琴，幽期默玄悟。","流連白雪意，斷續廻風度。","掩抑雖已終，忡忡在幽素。"]', '["煙华方散薄，蕙氣猶含露。","澹景發清琴，幽期默玄悟。","流連白雪意，斷續廻风度。","掩抑雖已終，忡忡在幽素。"]', '诗', 'shi', '', NULL, '司空主簿琴席 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128f48cc-c7a3-41bd-8127-263564a9aa36', '與村老對飲', '與村老对饮', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鬢眉雪色猶嗜酒，言辭淳朴古人風。","鄉村年少生離亂，見話先朝如夢中。"]', '["鬢眉雪色猶嗜酒，言辞淳朴古人风。","乡村年少生離亂，见話先朝如梦中。"]', '诗', 'shi', '', NULL, '與村老對飲 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84d911a9-697b-4728-b824-fb707428e03a', '城中臥疾知閻薛二子屢從邑令飲因以贈之', '城中臥疾知閻薛二子屢從邑令饮因以贈之', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["車馬日蕭蕭，胡不枉我廬。","方來從令飲，臥病獨何如。","秋風起漢臯，開戶望平蕪。","即此恡音素，焉知中密疎。","渴者不思火，寒者不求水。","人生羈寓時，去就當如此。","猶希心異跡，眷眷存終始。"]', '["车马日蕭蕭，胡不枉我廬。","方来從令饮，臥病独何如。","秋风起漢臯，开戶望平蕪。","即此恡音素，焉知中密疎。","渴者不思火，寒者不求水。","人生羈寓时，去就當如此。","猶希心異跡，眷眷存終始。"]', '诗', 'shi', '', NULL, '城中臥疾知閻薛二子屢從邑令飲因以贈之 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a24028-d0b4-4bb6-8822-5cdde7c21452', '聽嘉陵江水聲寄深上人', '听嘉陵江水声寄深上人', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鑿崖泄奔湍，稱古神禹跡。","夜喧山門店，獨宿不安席。","水性自云靜，石中本無聲。","如何兩相激，雷轉空山驚。","貽之道門舊，了此物我情。"]', '["鑿崖泄奔湍，稱古神禹跡。","夜喧山门店，独宿不安席。","水性自云静，石中本無声。","如何兩相激，雷轉空山驚。","貽之道门旧，了此物我情。"]', '诗', 'shi', '', NULL, '聽嘉陵江水聲寄深上人 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3469293b-e10f-43e6-b8de-f178267573df', '高陵書情寄三原盧少府', '高陵书情寄三原盧少府', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["直方難爲進，守此微賤班。","開卷不及顧，沈埋案牘間。","兵凶久相踐，徭賦豈得閑。","促戚下可哀，寬政身致患。","日夕思自退，出門望故山。","君心儻如此，攜手相與還。"]', '["直方难爲進，守此微賤班。","开卷不及顧，沈埋案牘间。","兵凶久相踐，徭賦豈得闲。","促戚下可哀，寬政身致患。","日夕思自退，出门望故山。","君心儻如此，携手相與還。"]', '诗', 'shi', '', NULL, '高陵書情寄三原盧少府 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('511e6810-5192-4cae-86a0-ba35f3a08bed', '假中對雨呈縣中僚友', '假中对雨呈縣中僚友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["卻足甘爲笑，閑居夢杜陵。","殘鶯知夏淺，社雨報年登。","流麥非關忘，收書獨不能。","自然憂曠職，緘此謝良朋。"]', '["卻足甘爲笑，闲居梦杜陵。","殘鶯知夏淺，社雨報年登。","流麦非关忘，收书独不能。","自然憂曠職，緘此謝良朋。"]', '诗', 'shi', '', NULL, '假中對雨呈縣中僚友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc7d44e-53fe-475f-b9a7-a0925821df1f', '贈蕭河南', '贈蕭河南', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["厭劇辭京縣，褒賢待詔書。","酇侯方繼業，潘令且閑居。","霽後三川冷，秋深萬木疎。","對琴無一事，新興復何如。"]', '["厭劇辞京縣，褒賢待詔书。","酇侯方繼業，潘令且闲居。","霽後三川冷，秋深万木疎。","对琴無一事，新兴复何如。"]', '诗', 'shi', '', NULL, '贈蕭河南 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51060b19-f87f-4c53-9c6b-6015eb4aae1f', '示從子河南尉班', '示從子河南尉班', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["拙直余恆守，公方爾所存。","同占朱鳥剋，俱起小人言。","立政思懸棒，謀身類觸藩。","不能林下去，祗戀府廷恩。"]', '["拙直余恆守，公方爾所存。","同占朱鸟剋，俱起小人言。","立政思懸棒，謀身類觸藩。","不能林下去，祗戀府廷恩。"]', '诗', 'shi', '', NULL, '示從子河南尉班 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14534ea6-ff68-4d27-a2c8-7d19f158ddf3', '趨府候曉呈兩縣僚友', '趨府候晓呈兩縣僚友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["趨府不遑安，中宵出戶看。","滿天星尚在，近壁燭仍殘。","立馬頻驚曙，垂簾却避寒。","可憐同宦者，應悟下流難。"]', '["趨府不遑安，中宵出戶看。","满天星尚在，近壁燭仍殘。","立马頻驚曙，垂簾却避寒。","可怜同宦者，應悟下流难。"]', '诗', 'shi', '', NULL, '趨府候曉呈兩縣僚友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc986d8-cf6d-4a12-8b28-a583a9607144', '贈李儋', '贈李儋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["絲桐本異質，音響合自然。","吾觀造化意，二物相因緣。","誤觸龍鳳嘯，靜聞寒夜泉。","心神自安宅，煩慮頓可捐。","何因知久要，絲白漆亦堅。"]', '["絲桐本異質，音响合自然。","吾观造化意，二物相因緣。","誤觸龙鳳嘯，静闻寒夜泉。","心神自安宅，煩慮頓可捐。","何因知久要，絲白漆亦堅。"]', '诗', 'shi', '', NULL, '贈李儋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26701df-5d43-4394-9402-2ced1822df0c', '贈盧嵩', '贈盧嵩', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["百川注東海，東海無虛盈。","泥滓不能濁，澄波非益清。","恬然自安流，日照萬里晴。","雲物不隱象，三山共分明。","奈何疾風怒，忽若砥柱傾。","海水雖無心，洪濤亦相驚。","怒號在倏忽，誰識變化情。"]', '["百川注东海，东海無虛盈。","泥滓不能濁，澄波非益清。","恬然自安流，日照万里晴。","云物不隐象，三山共分明。","奈何疾风怒，忽若砥柱傾。","海水雖無心，洪濤亦相驚。","怒號在倏忽，誰識变化情。"]', '诗', 'shi', '', NULL, '贈盧嵩 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38db14c8-8909-4764-b768-37500d13ca6c', '寄馮著', '寄馮著', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["春雷起萌蟄，土壤日已疎。","胡能遭盛明，才俊伏里閭。","偃仰遂真性，所求惟斗儲。","披衣出茅屋，盥漱臨清渠。","吾道亦自適，退身保玄虛。","幸無職事牽，且覽案上書。","親友各馳騖，誰當訪敝廬。","思君在何夕，明月照廣除。"]', '["春雷起萌蟄，土壤日已疎。","胡能遭盛明，才俊伏里閭。","偃仰遂真性，所求惟斗儲。","披衣出茅屋，盥漱臨清渠。","吾道亦自適，退身保玄虛。","幸無職事牽，且覽案上书。","親友各驰騖，誰當訪敝廬。","思君在何夕，明月照廣除。"]', '诗', 'shi', '', NULL, '寄馮著 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1152d7e-75af-4611-8d90-420ac2c3b01a', '早春對雪寄前殿中元侍御', '早春对雪寄前殿中元侍御', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["掃雪開幽徑，端居望故人。","猶殘臘月酒，更值早梅春。","幾日東城陌，何時曲水濱。","聞閑且共賞，莫待繡衣新。"]', '["掃雪开幽徑，端居望故人。","猶殘臘月酒，更值早梅春。","幾日东城陌，何时曲水濱。","闻闲且共賞，莫待繡衣新。"]', '诗', 'shi', '', NULL, '早春對雪寄前殿中元侍御 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecafcfe1-2f57-4c28-aef2-13e92857a524', '贈王侍御', '贈王侍御', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["心同野鶴與塵遠，詩似冰壺見底清。","府縣同趨昨日事，升沈不改故人情。","上陽秋晚蕭蕭雨，洛水寒來夜夜聲。","自歎猶爲折腰吏，可憐驄馬路傍行。"]', '["心同野鹤與塵远，诗似冰壺见底清。","府縣同趨昨日事，升沈不改故人情。","上陽秋晚蕭蕭雨，洛水寒来夜夜声。","自歎猶爲折腰吏，可怜驄马路傍行。"]', '诗', 'shi', '', NULL, '贈王侍御 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b08c0f6-ab25-41d6-afa2-e308faa52342', '將往江淮寄李十九儋', '將往江淮寄李十九儋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["燕燕東向來，文鵷亦西飛。","如何不相見，羽翼有高卑。","徘徊到河洛，華屋未及窺。","秋風飄我行，遠與淮海期。","廻首隔煙霧，遙遙兩相思。","陽春自當返，短翮欲追隨。"]', '["燕燕东向来，文鵷亦西飞。","如何不相见，羽翼有高卑。","徘徊到河洛，华屋未及窺。","秋风飄我行，远與淮海期。","廻首隔煙霧，遙遙兩相思。","陽春自當返，短翮欲追隨。"]', '诗', 'shi', '', NULL, '將往江淮寄李十九儋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a042d5-c2ef-42b1-8413-b7321440466d', '自鞏洛舟行入黃河即事寄府縣僚友', '自鞏洛舟行入黄河即事寄府縣僚友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夾水蒼山路向東，東南山豁大河通。","寒樹依微遠天外，夕陽明滅亂流中。","孤村幾歲臨伊岸，一鴈初晴下朔風。","爲報洛橋遊宦侶，扁舟不繫與心同。"]', '["夾水蒼山路向东，东南山豁大河通。","寒樹依微远天外，夕陽明滅亂流中。","孤村幾歲臨伊岸，一鴈初晴下朔风。","爲報洛橋游宦侶，扁舟不繫與心同。"]', '诗', 'shi', '', NULL, '自鞏洛舟行入黃河即事寄府縣僚友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0746182f-5825-41be-95b8-8e218ca6ae32', '寄盧庾', '寄盧庾', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["悠悠遠離別，分此歡會難。","如何兩相近，反使心不安。","亂髮思一櫛，垢衣思一浣。","豈如望友生，對酒起長嘆。","時節異京洛，孟冬天未寒。","廣陵多車馬，日夕自遊盤。","獨我何耿耿，非君誰爲歡。"]', '["悠悠远離別，分此歡會难。","如何兩相近，反使心不安。","亂髮思一櫛，垢衣思一浣。","豈如望友生，对酒起长嘆。","时節異京洛，孟冬天未寒。","廣陵多车马，日夕自游盤。","独我何耿耿，非君誰爲歡。"]', '诗', 'shi', '', NULL, '寄盧庾 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b2bab2-19eb-46e8-8d1a-fca253be333a', '發廣陵留上家兄兼寄上長沙', '發廣陵留上家兄兼寄上长沙', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["將違安可懷，宿戀復一方。","家貧無舊業，薄宦各飄颺。","執板身有屬，淹時心恐惶。","拜言不得留，聲結淚滿裳。","漾漾動行舫，亭亭遠相望。","離晨苦須臾，獨往道路長。","蕭條風雨過，得此海氣涼。","感秋意已違，況自結中腸。","推道固當遣，及情豈所忘。","何時共還歸，舉翼鳴春陽。"]', '["將違安可懷，宿戀复一方。","家貧無旧業，薄宦各飄颺。","執板身有屬，淹时心恐惶。","拜言不得留，声結泪满裳。","漾漾动行舫，亭亭远相望。","離晨苦須臾，独往道路长。","蕭條风雨過，得此海氣涼。","感秋意已違，況自結中腸。","推道固當遣，及情豈所忘。","何时共還归，舉翼鳴春陽。"]', '诗', 'shi', '', NULL, '發廣陵留上家兄兼寄上長沙 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b3a5651-2a80-4fb1-b1bf-c9fb5ec38905', '初發揚子寄元大校書', '初發揚子寄元大校书', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["悽悽去親愛，泛泛入煙霧。","歸棹洛陽人，殘鐘廣陵樹。","今朝此爲別，何處還相遇。","世事波上舟，沿洄安得住。"]', '["悽悽去親愛，泛泛入煙霧。","归棹洛陽人，殘鐘廣陵樹。","今朝此爲別，何处還相遇。","世事波上舟，沿洄安得住。"]', '诗', 'shi', '', NULL, '初發揚子寄元大校書 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b72e4b62-fc1c-4866-a964-6651f05cca64', '淮上即事寄廣陵親故', '淮上即事寄廣陵親故', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["前舟已眇眇，欲渡誰相持。","秋山起暮鐘，楚雨連滄海。","風波離思滿，宿昔容鬢改。","獨鳥下東南，廣陵何處在。"]', '["前舟已眇眇，欲渡誰相持。","秋山起暮鐘，楚雨連滄海。","风波離思满，宿昔容鬢改。","独鸟下东南，廣陵何处在。"]', '诗', 'shi', '', NULL, '淮上即事寄廣陵親故 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff430d2-bacf-41c1-97f0-19fa2f66b620', '寄洪州幕府二十一侍御', '寄洪州幕府二十一侍御', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["忽報南昌令，乘驄入郡城。","同時趨府客，此日望塵迎。","文苑臺中妙，冰壺幕下清。","洛陽相去遠，猶使故林榮。"]', '["忽報南昌令，乘驄入郡城。","同时趨府客，此日望塵迎。","文苑台中妙，冰壺幕下清。","洛陽相去远，猶使故林榮。"]', '诗', 'shi', '', NULL, '寄洪州幕府二十一侍御 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1e3be40-892a-4867-bf55-f68fac532fad', '經少林精舍寄都邑親友', '經少林精舍寄都邑親友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["息駕依松嶺，高閣一攀緣。","前瞻路已窮，既詣喜更延。","出巘聽萬籟，入林濯幽泉。","鳴鐘生道心，暮磬空雲煙。","獨往雖暫適，多累終見牽。","方思結茅地，歸息期暮年。"]', '["息駕依松嶺，高閣一攀緣。","前瞻路已窮，既詣喜更延。","出巘听万籟，入林濯幽泉。","鳴鐘生道心，暮磬空云煙。","独往雖暫適，多累終见牽。","方思結茅地，归息期暮年。"]', '诗', 'shi', '', NULL, '經少林精舍寄都邑親友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c7b9466-bb57-4aa1-9144-b474fb38ecef', '同長源歸南徐寄子西子烈有道', '同长源归南徐寄子西子烈有道', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["東洛何蕭條，相思邈遐路。","策駕復誰遊，入門無與晤。","還因送歸客，達此緘中素。","屢暌心所歡，豈得顏如故。","所歡不可暌，嚴霜晨淒淒。","如彼萬里行，孤妾守空閨。","臨觴一長嘆，素欲何時諧。"]', '["东洛何蕭條，相思邈遐路。","策駕复誰游，入门無與晤。","還因送归客，達此緘中素。","屢暌心所歡，豈得顏如故。","所歡不可暌，嚴霜晨淒淒。","如彼万里行，孤妾守空閨。","臨觴一长嘆，素欲何时諧。"]', '诗', 'shi', '', NULL, '同長源歸南徐寄子西子烈有道 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df2abdf-1b4f-43d5-9bf4-bab1d9debb04', '雪中聞李儋過門不訪聊以寄贈', '雪中闻李儋過门不訪聊以寄贈', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["度門能不訪，冒雪屢西東。","已想人如玉，遙憐馬似驄。","乍迷金谷路，稍變上陽宮。","還比相思意，紛紛正滿空。"]', '["度门能不訪，冒雪屢西东。","已想人如玉，遙怜马似驄。","乍迷金谷路，稍变上陽宮。","還比相思意，紛紛正满空。"]', '诗', 'shi', '', NULL, '雪中聞李儋過門不訪聊以寄贈 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7ee19b-eada-416a-8932-66779e0a79f2', '同德精舍養疾寄河南兵曹東廳掾', '同德精舍養疾寄河南兵曹东廳掾', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["逍遙東城隅，雙樹寒葱蒨。","廣庭流華月，高閣凝餘霰。","杜門非養素，抱疾阻良讌。","孰謂無他人，思君歲云變。","官曹亮先忝，陳躅慙俊彥。","豈知晨與夜，相代不相見。","緘書問所如，詶藻當芬絢。"]', '["逍遙东城隅，雙樹寒葱蒨。","廣庭流华月，高閣凝餘霰。","杜门非養素，抱疾阻良讌。","孰謂無他人，思君歲云变。","官曹亮先忝，陳躅慙俊彥。","豈知晨與夜，相代不相见。","緘书问所如，詶藻當芬絢。"]', '诗', 'shi', '', NULL, '同德精舍養疾寄河南兵曹東廳掾 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6200028-1512-4eaa-86d6-dcff74906953', '同德寺雨後寄元侍御李博士', '同德寺雨後寄元侍御李博士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["川上風雨來，須臾滿城闕。","岧嶢青蓮界，蕭條孤興發。","前山遽已淨，陰靄夜來歇。","喬木生夏涼，流雲吐華月。","嚴城自有限，一水非難越。","相望曙河遠，高齋坐超忽。"]', '["川上风雨来，須臾满城闕。","岧嶢青蓮界，蕭條孤兴發。","前山遽已淨，陰靄夜来歇。","喬木生夏涼，流云吐华月。","嚴城自有限，一水非难越。","相望曙河远，高斋坐超忽。"]', '诗', 'shi', '', NULL, '同德寺雨後寄元侍御李博士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c80b8f0-8478-4174-a49a-19d975ef7dc0', '同德閣期元侍御李博士不至各投贈二首 一', '同德閣期元侍御李博士不至各投贈二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["庭樹忽已暗，故人那不來。","祗因厭煩暑，永日坐霜臺。"]', '["庭樹忽已暗，故人那不来。","祗因厭煩暑，永日坐霜台。"]', '诗', 'shi', '', NULL, '同德閣期元侍御李博士不至各投贈二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7432ef1-43f0-49b4-b4ef-541c15db749e', '同德閣期元侍御李博士不至各投贈二首 二', '同德閣期元侍御李博士不至各投贈二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["官榮多所繫，閑居亦愆期。","高閣猶相望，青山欲暮時。"]', '["官榮多所繫，闲居亦愆期。","高閣猶相望，青山欲暮时。"]', '诗', 'shi', '', NULL, '同德閣期元侍御李博士不至各投贈二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18c3b7c-c1ea-429d-9b11-7071275e9eb9', '使雲陽寄府曹', '使云陽寄府曹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夙駕祗府命，冒炎不遑息。","百里次雲陽，閭閻問漂溺。","上天屢愆氣，胡不均寸澤。","仰瞻喬樹巔，見此洪流跡。","良苗免湮沒，蔓草生宿昔。","頹墉滿故墟，喜返將安宅。","周旋涉塗潦，側峭緣溝脉。","仁賢憂斯民，賤子甘所役。","公堂衆君子，言笑思與覿。"]', '["夙駕祗府命，冒炎不遑息。","百里次云陽，閭閻问漂溺。","上天屢愆氣，胡不均寸澤。","仰瞻喬樹巔，见此洪流跡。","良苗免湮沒，蔓草生宿昔。","頹墉满故墟，喜返將安宅。","周旋涉塗潦，側峭緣溝脉。","仁賢憂斯民，賤子甘所役。","公堂衆君子，言笑思與覿。"]', '诗', 'shi', '', NULL, '使雲陽寄府曹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3b2e00-f29e-456d-9de2-34fce2dfc1ba', '過扶風精舍舊居簡朝宗巨川兄弟', '過扶风精舍旧居簡朝宗巨川兄弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["佛剎出高樹，晨光閭井中。","年深念陳迹，迨此獨忡忡。","零落逢故老，寂寥悲草蟲。","舊宇多改構，幽篁延本叢。","栖止事如昨，芳時去已空。","佳人亦攜手，再往今不同。","新文聊感舊，想子意無窮。"]', '["佛剎出高樹，晨光閭井中。","年深念陳迹，迨此独忡忡。","零落逢故老，寂寥悲草蟲。","旧宇多改構，幽篁延本叢。","栖止事如昨，芳时去已空。","佳人亦携手，再往今不同。","新文聊感旧，想子意無窮。"]', '诗', 'shi', '', NULL, '過扶風精舍舊居簡朝宗巨川兄弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7fa583c-e983-4518-9005-bbc2b2fae23a', '贈令狐士曹', '贈令狐士曹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秋簷滴滴對牀寢，山路迢迢聯騎行。","到家俱及東籬菊，何事先歸半日程。"]', '["秋簷滴滴对牀寢，山路迢迢聯騎行。","到家俱及东籬菊，何事先归半日程。"]', '诗', 'shi', '', NULL, '贈令狐士曹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13754f15-8ec6-4d8d-b697-a65309992128', '贈馮著', '贈馮著', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["契闊仕兩京，念子亦飄蓬。","方來屬追往，十載事不同。","歲晏乃云至，微褐還未充。","慘悽遊子情，風雪自關東。","華觴發懽顏，嘉藻播清風。","始此盈抱恨，曠然一夕中。","善蘊豈輕售，懷才希國工。","誰當念素士，零落歲華空。"]', '["契闊仕兩京，念子亦飄蓬。","方来屬追往，十載事不同。","歲晏乃云至，微褐還未充。","慘悽游子情，风雪自关东。","华觴發懽顏，嘉藻播清风。","始此盈抱恨，曠然一夕中。","善蘊豈轻售，懷才希国工。","誰當念素士，零落歲华空。"]', '诗', 'shi', '', NULL, '贈馮著 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4ba324-7f45-4a75-ac89-d335d8ef0ff9', '對雨寄韓庫部協', '对雨寄韓庫部協', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["颯至池館涼，靄然和曉霧。","蕭條集新荷，氤氳散高樹。","閑居興方澹，默想心已屢。","暫出仍濕衣，況君東城住。"]', '["颯至池館涼，靄然和晓霧。","蕭條集新荷，氤氳散高樹。","闲居兴方澹，默想心已屢。","暫出仍濕衣，況君东城住。"]', '诗', 'shi', '', NULL, '對雨寄韓庫部協 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44eb280-078e-47e6-95b1-91f9b8b4980b', '寄子西', '寄子西', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夏景已難度，懷賢思方續。","喬樹落疎陰，微風散煩燠。","傷離枉芳札，忻遂見心曲。","藍上舍已成，田家雨新足。","託鄰素多欲，殘帙猶見束。","日夕上高齋，但望東原綠。"]', '["夏景已难度，懷賢思方續。","喬樹落疎陰，微风散煩燠。","傷離枉芳札，忻遂见心曲。","藍上舍已成，田家雨新足。","託鄰素多欲，殘帙猶见束。","日夕上高斋，但望东原綠。"]', '诗', 'shi', '', NULL, '寄子西 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb29b0f-72d8-437e-b798-9b2da4411355', '縣內閑居贈溫公', '縣內闲居贈溫公', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["滿郭春[風]嵐已昏，鴉栖散吏掩重門。","雖居世網常清淨，夜對高僧無一言。"]', '["满郭春[风]嵐已昏，鴉栖散吏掩重门。","雖居世網常清淨，夜对高僧無一言。"]', '诗', 'shi', '', NULL, '縣內閑居贈溫公 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc01356f-bc55-4736-aa6f-cefb16557b61', '對雪贈徐秀才', '对雪贈徐秀才', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["靡靡寒欲收，靄靄陰還結。","晨起望南端，千林散春雪。","妍光屬瑤階，亂緒陵新節。","無爲掩扉臥，獨守袁生轍。"]', '["靡靡寒欲收，靄靄陰還結。","晨起望南端，千林散春雪。","妍光屬瑤階，亂緒陵新節。","無爲掩扉臥，独守袁生轍。"]', '诗', 'shi', '', NULL, '對雪贈徐秀才 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf23e05-60e2-4b35-b5a1-b1b78fe8a1ad', '西郊遊宴寄贈邑僚李巽', '西郊游宴寄贈邑僚李巽', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["升陽曖春物，置酒臨芳席。","高宴闕英僚，衆賓寡懽懌。","是時尚多壘，板築興頹壁。","羇旅念越疆，領徒方祗役。","如何嘉會日，當子憂勤夕。","西郊鬱已茂，春嵐重如積。","何當返徂雨，雜英紛可惜。"]', '["升陽曖春物，置酒臨芳席。","高宴闕英僚，衆賓寡懽懌。","是时尚多壘，板築兴頹壁。","羇旅念越疆，領徒方祗役。","如何嘉會日，當子憂勤夕。","西郊鬱已茂，春嵐重如積。","何當返徂雨，杂英紛可惜。"]', '诗', 'shi', '', NULL, '西郊遊宴寄贈邑僚李巽 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200d19a9-28c9-42b1-b4b0-f60a5ac9d376', '對雨贈李主簿高秀才', '对雨贈李主簿高秀才', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["邐迤曙雲薄，散漫東風來。","青山滿春野，微雨灑輕埃。","吏局勞佳士，賓筵得上才。","終朝狎文墨，高興共徘徊。"]', '["邐迤曙云薄，散漫东风来。","青山满春野，微雨灑轻埃。","吏局勞佳士，賓筵得上才。","終朝狎文墨，高兴共徘徊。"]', '诗', 'shi', '', NULL, '對雨贈李主簿高秀才 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fab1420-150e-4d48-be58-818481e5b345', '休沐東還胄貴里示端', '休沐东還胄貴里示端', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["宦遊三十載，田野久已疎。","休沐遂茲日，一來還故墟。","山明宿雨霽，風煖百卉舒。","泓泓野泉潔，熠熠林光初。","竹木稍摧翳，園場亦荒蕪。","俯驚鬢已衰，周覽昔所娛。","存沒惻私懷，遷變傷里閭。","欲言少留心，中復畏簡書。","世道良自退，榮名亦空虛。","與子終攜手，歲晏當來居。"]', '["宦游三十載，田野久已疎。","休沐遂茲日，一来還故墟。","山明宿雨霽，风煖百卉舒。","泓泓野泉潔，熠熠林光初。","竹木稍摧翳，园場亦荒蕪。","俯驚鬢已衰，周覽昔所娛。","存沒惻私懷，遷变傷里閭。","欲言少留心，中复畏簡书。","世道良自退，榮名亦空虛。","與子終携手，歲晏當来居。"]', '诗', 'shi', '', NULL, '休沐東還胄貴里示端 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b4bf381-68b3-41e8-a79e-07d8b6de6693', '朝請後還邑寄諸友生', '朝請後還邑寄諸友生', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["宰邑分甸服，夙駕朝上京。","是時當暮春，休沐集友生。","抗志青雲表，俱踐高世名。","樽酒且歡樂，文翰亦縱橫。","良遊昔所希，累讌夜復明。","晨露含瑤琴，夕風殞素英。","一旦遵歸路，伏軾出京城。","誰言再念別，忽若千里行。","閑閤寡喧訟，端居結幽情。","況茲晝方永，展轉何由平。"]', '["宰邑分甸服，夙駕朝上京。","是时當暮春，休沐集友生。","抗志青云表，俱踐高世名。","樽酒且歡乐，文翰亦縱橫。","良游昔所希，累讌夜复明。","晨露含瑤琴，夕风殞素英。","一旦遵归路，伏軾出京城。","誰言再念別，忽若千里行。","闲閤寡喧訟，端居結幽情。","況茲晝方永，展轉何由平。"]', '诗', 'shi', '', NULL, '朝請後還邑寄諸友生 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d5d75b0-00ae-4cf7-b363-c93a09094a79', '灃上西齋寄諸友', '灃上西斋寄諸友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["絕岸臨西野，曠然塵事遙。","清川下邐迤，茅棟上岧嶢。","翫月愛佳夕，望山屬清朝。","俯砌視歸翼，開襟納遠飆。","等陶辭小秩，效朱方負樵。","閑遊忽無累，心跡隨景超。","明世重才彥，雨露降丹霄。","羣公正雲集，獨予忻寂寥。"]', '["絕岸臨西野，曠然塵事遙。","清川下邐迤，茅棟上岧嶢。","翫月愛佳夕，望山屬清朝。","俯砌視归翼，开襟納远飆。","等陶辞小秩，效朱方負樵。","闲游忽無累，心跡隨景超。","明世重才彥，雨露降丹霄。","羣公正云集，独予忻寂寥。"]', '诗', 'shi', '', NULL, '灃上西齋寄諸友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69b265f8-bbee-4c80-9cd3-c98960c9cef4', '獨遊西齋寄崔主簿', '独游西斋寄崔主簿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["同心忽已別，昨事方成昔。","幽徑還獨尋，綠苔見行跡。","秋齋正蕭散，烟水易昏夕。","憂來結幾重，非君不可釋。"]', '["同心忽已別，昨事方成昔。","幽徑還独尋，綠苔见行跡。","秋斋正蕭散，烟水易昏夕。","憂来結幾重，非君不可釋。"]', '诗', 'shi', '', NULL, '獨遊西齋寄崔主簿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612ef8d1-e061-4e42-99ca-e73986831570', '紫閣東林居士叔緘賜松英丸捧對忻喜蓋非塵侶之所當服輙獻詩代啓', '紫閣东林居士叔緘賜松英丸捧对忻喜蓋非塵侶之所當服輙獻诗代啓', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["碧澗蒼松五粒稀，侵雲采去露沾衣。","夜啓羣僊合靈藥，朝思俗侶寄將歸。","道場齋戒今初服，人事葷羶已覺非。","一望嵐峰拜還使，腰間銅印與心違。"]', '["碧澗蒼松五粒稀，侵云采去露沾衣。","夜啓羣僊合靈藥，朝思俗侶寄將归。","道場斋戒今初服，人事葷羶已覺非。","一望嵐峰拜還使，腰间銅印與心違。"]', '诗', 'shi', '', NULL, '紫閣東林居士叔緘賜松英丸捧對忻喜蓋非塵侶之所當服輙獻詩代啓 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5edb07-51bb-4c8f-8eb8-19f18ab58f84', '秋集罷還途中作謹獻壽春公黎公', '秋集罷還途中作謹獻壽春公黎公', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["束帶自衡門，奉命宰王畿。","君侯枉高鑒，舉善掩瑕疵。","斯民本已安，工拙兩無施。","何以酬明德，歲晏不磷緇。","時節乃來集，欣懷方載馳。","平明大府開，一得拜光輝。","溫如春風至，肅若嚴霜威。","羣屬所載瞻，而忘倦與飢。","公堂燕華筵，禮罷復言辭。","將從平門道，憩車灃水湄。","山川降嘉歲，草木蒙潤滋。","孰云還本邑，懷戀獨遲遲。"]', '["束带自衡门，奉命宰王畿。","君侯枉高鑒，舉善掩瑕疵。","斯民本已安，工拙兩無施。","何以酬明德，歲晏不磷緇。","时節乃来集，欣懷方載驰。","平明大府开，一得拜光輝。","溫如春风至，肅若嚴霜威。","羣屬所載瞻，而忘倦與飢。","公堂燕华筵，禮罷复言辞。","將從平门道，憩车灃水湄。","山川降嘉歲，草木蒙潤滋。","孰云還本邑，懷戀独遲遲。"]', '诗', 'shi', '', NULL, '秋集罷還途中作謹獻壽春公黎公 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f287df2-96b4-4dff-b299-a4518ffc35f3', '閑居贈友', '闲居贈友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["補吏多下遷，罷歸聊自度。","園廬既蕪沒，煙景空澹泊。","閑居養疴瘵，守素甘葵藿。","顏鬢日衰耗，冠帶亦寥落。","青苔已生路，綠筠始分籜。","夕氣下遙陰，微風動疎薄。","草玄良見誚，杜門無請託。","非君好事者，誰來顧寂寞。"]', '["補吏多下遷，罷归聊自度。","园廬既蕪沒，煙景空澹泊。","闲居養疴瘵，守素甘葵藿。","顏鬢日衰耗，冠带亦寥落。","青苔已生路，綠筠始分籜。","夕氣下遙陰，微风动疎薄。","草玄良见誚，杜门無請託。","非君好事者，誰来顧寂寞。"]', '诗', 'shi', '', NULL, '閑居贈友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100f4e4a-9884-4c89-8b2d-9e3d3a9a4d42', '四禪精舍登覽悲舊寄朝宗巨川兄弟', '四禪精舍登覽悲旧寄朝宗巨川兄弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["蕭散人事憂，迢遰古原行。","春風日已暄，百草亦復生。","躋閣謁金像，攀雲造禪扃。","新景林際曙，雜花川上明。","徂歲方緬邈，陳事尚縱橫。","溫泉有佳氣，馳道指京城。","攜手思故日，山河留恨情。","存者邈難見，去者已冥冥。","臨風一長慟，誰畏行路驚。"]', '["蕭散人事憂，迢遰古原行。","春风日已暄，百草亦复生。","躋閣謁金像，攀云造禪扃。","新景林際曙，杂花川上明。","徂歲方緬邈，陳事尚縱橫。","溫泉有佳氣，驰道指京城。","携手思故日，山河留恨情。","存者邈难见，去者已冥冥。","臨风一长慟，誰畏行路驚。"]', '诗', 'shi', '', NULL, '四禪精舍登覽悲舊寄朝宗巨川兄弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22513478-2b2a-42d7-8fe8-b183545869c9', '善福閣對雨寄李儋幼遐', '善福閣对雨寄李儋幼遐', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["飛閣凌太虛，晨躋鬱崢嶸。","驚飆觸懸檻，白雲冒層甍。","太陰布其地，密雨垂八紘。","仰觀固不測，俯視但冥冥。","感此窮秋氣，沈鬱命友生。","及時未高步，羇旅遊帝京。","聖朝無隱才，品物俱昭形。","國士秉繩墨，何以表堅貞。","寸心東北馳，思與一會幷。","我車夙已駕，將逐晨風征。","郊塗住成淹，默默阻中情。"]', '["飞閣凌太虛，晨躋鬱崢嶸。","驚飆觸懸檻，白云冒層甍。","太陰布其地，密雨垂八紘。","仰观固不測，俯視但冥冥。","感此窮秋氣，沈鬱命友生。","及时未高步，羇旅游帝京。","聖朝無隐才，品物俱昭形。","国士秉繩墨，何以表堅貞。","寸心东北驰，思與一會幷。","我车夙已駕，將逐晨风征。","郊塗住成淹，默默阻中情。"]', '诗', 'shi', '', NULL, '善福閣對雨寄李儋幼遐 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cab08611-682e-4650-9b8a-365f7e46ee5e', '寺居獨夜寄崔主簿', '寺居独夜寄崔主簿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["幽人寂不寐，木葉紛紛落。","寒雨暗深更，流螢度高閣。","坐使青燈曉，還傷夏衣薄。","寧知歲方晏，離居更蕭索。"]', '["幽人寂不寐，木葉紛紛落。","寒雨暗深更，流螢度高閣。","坐使青灯晓，還傷夏衣薄。","寧知歲方晏，離居更蕭索。"]', '诗', 'shi', '', NULL, '寺居獨夜寄崔主簿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('829b6820-b69d-4ac5-b31c-434e9daf366b', '九日灃上作寄崔主簿倬二李端擊', '九日灃上作寄崔主簿倬二李端擊', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["淒淒感時節，望望臨灃涘。","翠嶺明華秋，高天澄遙滓。","川寒流愈迅，霜交物初委。","林葉索已空，晨禽迎飆起。","時菊乃盈泛，濁醪自爲美。","良遊雖可娛，殷念在之子。","人生不自省，營欲無終已。","孰能同一酌，陶然冥斯理。"]', '["淒淒感时節，望望臨灃涘。","翠嶺明华秋，高天澄遙滓。","川寒流愈迅，霜交物初委。","林葉索已空，晨禽迎飆起。","时菊乃盈泛，濁醪自爲美。","良游雖可娛，殷念在之子。","人生不自省，營欲無終已。","孰能同一酌，陶然冥斯理。"]', '诗', 'shi', '', NULL, '九日灃上作寄崔主簿倬二李端擊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ce42f9-c3de-4d4d-b33c-b4e8186dc226', '西郊養疾聞暢校書有新什見贈久佇不至先寄此詩', '西郊養疾闻暢校书有新什见贈久佇不至先寄此诗', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["養病愜清夏，郊園敷卉木。","牕夕含澗涼，雨餘愛筠綠。","披懷始高詠，對琴轉幽獨。","仰子遊羣英，吐詞如蘭馥。","還聞枉嘉藻，佇望延昏旭。","唯見草青青，閉戶灃水曲。"]', '["養病愜清夏，郊园敷卉木。","牕夕含澗涼，雨餘愛筠綠。","披懷始高詠，对琴轉幽独。","仰子游羣英，吐词如蘭馥。","還闻枉嘉藻，佇望延昏旭。","唯见草青青，閉戶灃水曲。"]', '诗', 'shi', '', NULL, '西郊養疾聞暢校書有新什見贈久佇不至先寄此詩 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623c10f7-3d51-41c4-88fc-2be143ef81a7', '灃上寄幼遐', '灃上寄幼遐', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["寂寞到城闕，惆悵返柴荆。","端居無所爲，念子遠徂征。","夏晝人已息，我懷獨未寧。","忽從東齋起，兀兀尋澗行。","罥罣叢榛密，披玩孤花明。","曠然西南望，一極山水情。","周覽同遊處，逾恨阻音形。","壯圖非旦夕，君子勤令名。","勿復久留燕，蹉跎在北京。"]', '["寂寞到城闕，惆悵返柴荆。","端居無所爲，念子远徂征。","夏晝人已息，我懷独未寧。","忽從东斋起，兀兀尋澗行。","罥罣叢榛密，披玩孤花明。","曠然西南望，一極山水情。","周覽同游处，逾恨阻音形。","壯圖非旦夕，君子勤令名。","勿复久留燕，蹉跎在北京。"]', '诗', 'shi', '', NULL, '灃上寄幼遐 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a71b9518-7c15-4726-939d-5a8d5b612911', '善福精舍示諸生', '善福精舍示諸生', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["湛湛嘉樹陰，清露夜景沈。","悄然羣物寂，高閣似陰岑。","方以玄默處，豈爲名跡侵。","法妙不知歸，獨此抱沖襟。","齋舍無餘物，陶器與單衾。","諸生時列坐，共愛風滿林。"]', '["湛湛嘉樹陰，清露夜景沈。","悄然羣物寂，高閣似陰岑。","方以玄默处，豈爲名跡侵。","法妙不知归，独此抱沖襟。","斋舍無餘物，陶器與單衾。","諸生时列坐，共愛风满林。"]', '诗', 'shi', '', NULL, '善福精舍示諸生 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e1c375-cf0d-45ee-be07-c4e577256eeb', '晚出灃上贈崔都水', '晚出灃上贈崔都水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["臨流一舒嘯，望山意轉延。","隔林分落景，餘霞明遠川。","首起趣東作，已看耘夏田。","一從民里居，歲月再徂遷。","昧質得全性，世名良自牽。","行忻攜手歸，聊復飲酒眠。"]', '["臨流一舒嘯，望山意轉延。","隔林分落景，餘霞明远川。","首起趣东作，已看耘夏田。","一從民里居，歲月再徂遷。","昧質得全性，世名良自牽。","行忻携手归，聊复饮酒眠。"]', '诗', 'shi', '', NULL, '晚出灃上贈崔都水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44453fa-d035-463a-b0c1-e496f413be10', '寓居灃上精舍于張二舍人', '寓居灃上精舍于張二舍人', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["萬木叢雲出香閣，西連碧澗竹林園。","高齋猶宿遠山曙，微霰下庭寒雀喧。","道心淡泊對流水，生事蕭疎空掩門。","時憶故交那得見，曉排閶闔奉明恩。"]', '["万木叢云出香閣，西連碧澗竹林园。","高斋猶宿远山曙，微霰下庭寒雀喧。","道心淡泊对流水，生事蕭疎空掩门。","时憶故交那得见，晓排閶闔奉明恩。"]', '诗', 'shi', '', NULL, '寓居灃上精舍于張二舍人 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c662609f-7fb0-459a-8ad2-68c6ae44b63c', '開元觀懷舊寄李二韓二裴四兼呈崔郎中嚴家令', '开元观懷旧寄李二韓二裴四兼呈崔郎中嚴家令', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["宿昔清都燕，分散各西東。","車馬行跡在，霜雪竹林空。","方軫故五念，誰復一樽同。","聊披道書暇，還此聽松風。"]', '["宿昔清都燕，分散各西东。","车马行跡在，霜雪竹林空。","方軫故五念，誰复一樽同。","聊披道书暇，還此听松风。"]', '诗', 'shi', '', NULL, '開元觀懷舊寄李二韓二裴四兼呈崔郎中嚴家令 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628f68ba-02c9-4663-9c34-55373fd59f31', '春日郊居寄萬年吉少府中孚三原少府偉夏侯校書審', '春日郊居寄万年吉少府中孚三原少府偉夏侯校书審', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["谷鳥時一囀，田園春雨餘。","光風動林早，高牕照日初。","獨飲澗中水，吟詠老氏書。","城闕應多事，誰憶此閑居。"]', '["谷鸟时一囀，田园春雨餘。","光风动林早，高牕照日初。","独饮澗中水，吟詠老氏书。","城闕應多事，誰憶此闲居。"]', '诗', 'shi', '', NULL, '春日郊居寄萬年吉少府中孚三原少府偉夏侯校書審 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09245ef2-abd7-4ca9-81bb-6fe56a6ca3f2', '灃上醉題寄滌武', '灃上醉題寄滌武', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["芳園知夕燕，西郊已獨還。","誰言不同賞，俱是醉花間。"]', '["芳园知夕燕，西郊已独還。","誰言不同賞，俱是醉花间。"]', '诗', 'shi', '', NULL, '灃上醉題寄滌武 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342047fb-4d9d-4f7f-857e-008fe5ff7c43', '西郊期滌武不至書示', '西郊期滌武不至书示', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山高鳴過雨，澗樹落殘花。","非關春不待，當由期自賒。"]', '["山高鳴過雨，澗樹落殘花。","非关春不待，當由期自賒。"]', '诗', 'shi', '', NULL, '西郊期滌武不至書示 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df5b6e1-6755-40bc-a67c-efc1213e5b5b', '灃上對月寄孔諫議', '灃上对月寄孔諫議', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["思懷在雲闕，泊素守中林。","出處雖殊跡，明月兩知心。"]', '["思懷在云闕，泊素守中林。","出处雖殊跡，明月兩知心。"]', '诗', 'shi', '', NULL, '灃上對月寄孔諫議 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7458ba-a75d-4dfc-89b9-54d9c9613d17', '將往滁城戀新竹簡崔都水示端', '將往滁城戀新竹簡崔都水示端', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["停車欲去繞叢竹，偏愛新筠十數竿。","莫遣兒童觸瓊粉，留待幽人廻日看。"]', '["停车欲去繞叢竹，偏愛新筠十數竿。","莫遣兒童觸瓊粉，留待幽人廻日看。"]', '诗', 'shi', '', NULL, '將往滁城戀新竹簡崔都水示端 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10fa8c7c-77ca-4602-915a-9e336a6e47b8', '還闕首途寄精舍親友', '還闕首途寄精舍親友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["休沐日云滿，沖然將罷觀。","嚴車候門側，晨起正朝冠。","山澤含餘雨，川澗注驚湍。","攬轡遵東路，廻首一長嘆。","居人已不見，高閣在林端。"]', '["休沐日云满，沖然將罷观。","嚴车候门側，晨起正朝冠。","山澤含餘雨，川澗注驚湍。","攬轡遵东路，廻首一长嘆。","居人已不见，高閣在林端。"]', '诗', 'shi', '', NULL, '還闕首途寄精舍親友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55940ba8-1a3a-4dc6-a56a-e7e24f8eb55d', '秋夜南宮寄灃上弟及諸生', '秋夜南宮寄灃上弟及諸生', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["暝色起煙閣，沈抱積離憂。","況茲風雨夜，蕭條梧葉秋。","空宇感涼至，頹顏驚歲周。","日夕遊闕下，山水憶同遊。"]', '["暝色起煙閣，沈抱積離憂。","況茲风雨夜，蕭條梧葉秋。","空宇感涼至，頹顏驚歲周。","日夕游闕下，山水憶同游。"]', '诗', 'shi', '', NULL, '秋夜南宮寄灃上弟及諸生 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3814497e-2add-45ca-8d72-5c63f5b02e52', '途中書情寄灃上兩弟因送二甥却還', '途中书情寄灃上兩弟因送二甥却還', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["華簪豈足戀，幽林徒自違。","遙知別後意，寂寞掩郊扉。","廻首昆池上，更羨爾同歸。"]', '["华簪豈足戀，幽林徒自違。","遙知別後意，寂寞掩郊扉。","廻首昆池上，更羨爾同归。"]', '诗', 'shi', '', NULL, '途中書情寄灃上兩弟因送二甥却還 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb7212c-1a89-4317-a4a2-50e3c769cfb7', '雪夜下朝呈省中一絕', '雪夜下朝呈省中一絕', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["南望青山滿禁闈，曉陪鴛鷺正差池。","共愛朝來何處雪，蓬萊宮裏拂松枝。"]', '["南望青山满禁闈，晓陪鴛鷺正差池。","共愛朝来何处雪，蓬萊宮裏拂松枝。"]', '诗', 'shi', '', NULL, '雪夜下朝呈省中一絕 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7fb6e7-251a-4727-af3a-d15ac65bf8b9', '寄柳州韓司戶郎中', '寄柳州韓司戶郎中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["達識與昧機，智殊迹同靜。","於焉得攜手，屢賞清夜景。","瀟灑陪高詠，從容羨華省。","一逐風波遷，南登桂陽嶺。","舊里門空掩，歡遊事皆屏。","悵望城闕遙，幽居時序永。","春風吹百卉，和煦變閭井。","獨悶終日眠，篇書不復省。","唯當望雨露，霑子荒遐境。"]', '["達識與昧機，智殊迹同静。","於焉得携手，屢賞清夜景。","瀟灑陪高詠，從容羨华省。","一逐风波遷，南登桂陽嶺。","旧里门空掩，歡游事皆屏。","悵望城闕遙，幽居时序永。","春风吹百卉，和煦变閭井。","独悶終日眠，篇书不复省。","唯當望雨露，霑子荒遐境。"]', '诗', 'shi', '', NULL, '寄柳州韓司戶郎中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f2e8a2-92a0-4313-affc-0c84adcdc54b', '寄令狐侍郎', '寄令狐侍郎', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["三山有瓊樹，霜雪色逾新。","始自風塵交，中結綢繆姻。","西掖方掌誥，南宮復司春。","夕燕華池月，朝奉玉階塵。","衆寶歸和氏，吹噓多俊人。","羣公共然諾，聲問邁時倫。","孤鴻既高舉，燕雀在荆榛。","翔集且不同，豈不欲殷勤。","一旦遷南郡，江湖渺無垠。","寵辱良未定，君子豈緇磷。","寒暑已推斥，別離生苦辛。","非將會面目，書札何由申。"]', '["三山有瓊樹，霜雪色逾新。","始自风塵交，中結綢繆姻。","西掖方掌誥，南宮复司春。","夕燕华池月，朝奉玉階塵。","衆寶归和氏，吹噓多俊人。","羣公共然諾，声问邁时倫。","孤鴻既高舉，燕雀在荆榛。","翔集且不同，豈不欲殷勤。","一旦遷南郡，江湖渺無垠。","寵辱良未定，君子豈緇磷。","寒暑已推斥，別離生苦辛。","非將會面目，书札何由申。"]', '诗', 'shi', '', NULL, '寄令狐侍郎 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba2371d-b993-4f0b-93bb-eb76292f108a', '閑居寄端及重陽', '闲居寄端及重陽', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山明野寺曙鐘微，雪滿幽林人跡稀。","閑居寥落生高興，無事風塵獨不歸。"]', '["山明野寺曙鐘微，雪满幽林人跡稀。","闲居寥落生高兴，無事风塵独不归。"]', '诗', 'shi', '', NULL, '閑居寄端及重陽 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab1f275-24c7-4cbc-a8c0-402573836d3c', '園林晏起寄昭應韓明府盧主簿', '园林晏起寄昭應韓明府盧主簿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["田家已耕作，井屋起晨煙。","園林鳴好鳥，閑居猶獨眠。","不覺朝已晏，起來望青天。","四體一舒散，情性亦忻然。","還復茅簷下，對酒思數賢。","束帶理官府，簡牘盈目前。","當念中林賞，覽物遍山川。","上非遇明世，庶以道自全。"]', '["田家已耕作，井屋起晨煙。","园林鳴好鸟，闲居猶独眠。","不覺朝已晏，起来望青天。","四體一舒散，情性亦忻然。","還复茅簷下，对酒思數賢。","束带理官府，簡牘盈目前。","當念中林賞，覽物遍山川。","上非遇明世，庶以道自全。"]', '诗', 'shi', '', NULL, '園林晏起寄昭應韓明府盧主簿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e292d6d-b50a-45d7-80e3-b612c2e87992', '寄大梁諸友', '寄大梁諸友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["分竹守南譙，弭節過梁池。","雄都衆君子，出餞擁河湄。","燕謔始云洽，方舟已解維。","一爲風水便，但見山川馳。","昨日次睢陽，今夕宿符離。","雲樹愴重疊，烟波念還期。","相敦在勤事，海內方勞師。"]', '["分竹守南譙，弭節過梁池。","雄都衆君子，出餞擁河湄。","燕謔始云洽，方舟已解維。","一爲风水便，但见山川驰。","昨日次睢陽，今夕宿符離。","云樹愴重叠，烟波念還期。","相敦在勤事，海內方勞師。"]', '诗', 'shi', '', NULL, '寄大梁諸友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cef91792-2815-4dce-8db8-b86912b9a6b7', '新秋夜寄諸弟', '新秋夜寄諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["兩地俱秋夕，相望共星河。","高梧一葉下，空齋歸思多。","方用憂人瘼，況自抱微痾。","無將別來近，顏鬢已蹉跎。"]', '["兩地俱秋夕，相望共星河。","高梧一葉下，空斋归思多。","方用憂人瘼，況自抱微痾。","無將別来近，顏鬢已蹉跎。"]', '诗', 'shi', '', NULL, '新秋夜寄諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3d902f-2207-47eb-bca7-c5ba1c9c8fdb', '郊園聞蟬寄諸弟', '郊园闻蟬寄諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["去歲郊園別，聞蟬在蘭省。","今歲臥南譙，蟬鳴歸路永。","夕響依山谷，餘悲散秋景。","緘書報此時，此心方耿耿。"]', '["去歲郊园別，闻蟬在蘭省。","今歲臥南譙，蟬鳴归路永。","夕响依山谷，餘悲散秋景。","緘书報此时，此心方耿耿。"]', '诗', 'shi', '', NULL, '郊園聞蟬寄諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6708c6-f6d7-488a-9784-a8f75ea8f5ad', '寄中書劉舍人', '寄中书劉舍人', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雲霄路竟別，中年跡暫同。","比翼趨丹陛，連騎下南宮。","佳詠邀清月，幽賞滯芳藂。","迨予一出守，與子限西東。","晨露方愴愴，離抱更忡忡。","忽睹九天詔，秉綸歸國工。","玉座浮香氣，秋禁散涼風。","應向橫門度，環珮杳玲瓏。","光輝恨未矚，歸思坐難通。","蒼蒼松桂姿，想在掖垣中。"]', '["云霄路竟別，中年跡暫同。","比翼趨丹陛，連騎下南宮。","佳詠邀清月，幽賞滯芳藂。","迨予一出守，與子限西东。","晨露方愴愴，離抱更忡忡。","忽睹九天詔，秉綸归国工。","玉座浮香氣，秋禁散涼风。","應向橫门度，环珮杳玲瓏。","光輝恨未矚，归思坐难通。","蒼蒼松桂姿，想在掖垣中。"]', '诗', 'shi', '', NULL, '寄中書劉舍人 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be54a9d9-f2b3-415a-90ec-0ed7708e64f2', '郡齋感秋寄諸弟', '郡斋感秋寄諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["首夏辭舊國，窮秋臥滁城。","方如昨日別，忽覺徂歲驚。","高閣收煙霧，池水晚澄清。","戶牖已淒爽，晨夜感深情。","昔遊郎署間，是月天氣晴。","授衣還西郊，曉露田中行。","采菊投酒中，昆弟自同傾。","簪組聊掛壁，焉知有世榮。","一旦居遠郡，山川間音形。","大道庶無累，及茲念已盈。"]', '["首夏辞旧国，窮秋臥滁城。","方如昨日別，忽覺徂歲驚。","高閣收煙霧，池水晚澄清。","戶牖已淒爽，晨夜感深情。","昔游郎署间，是月天氣晴。","授衣還西郊，晓露田中行。","采菊投酒中，昆弟自同傾。","簪組聊掛壁，焉知有世榮。","一旦居远郡，山川间音形。","大道庶無累，及茲念已盈。"]', '诗', 'shi', '', NULL, '郡齋感秋寄諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a434d0-25eb-4103-ae98-299c0cc9beab', '郡中對雨贈元錫兼簡楊凌', '郡中对雨贈元錫兼簡楊凌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["宿雨冒空山，空城響秋葉。","沈沈暮色至，淒淒涼氣入。","蕭條林表散，的礫荷上集。","夜霧著衣重，新苔侵履濕。","遇茲端憂日，賴與嘉賓接。"]', '["宿雨冒空山，空城响秋葉。","沈沈暮色至，淒淒涼氣入。","蕭條林表散，的礫荷上集。","夜霧著衣重，新苔侵履濕。","遇茲端憂日，賴與嘉賓接。"]', '诗', 'shi', '', NULL, '郡中對雨贈元錫兼簡楊凌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('286f7688-8876-4264-8ce6-ecb451a38223', '冬至夜寄京師諸弟兼懷崔都水', '冬至夜寄京師諸弟兼懷崔都水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["理郡無異政，所憂在素飡。","徒令去京國，羈旅當歲寒。","子月生一氣，陽景極南端。","已懷時節感，更抱別離酸。","私燕席云罷，還齋夜方闌。","邃幕沈空宇，孤燈照牀單。","應同茲夕念，寧忘故歲歡。","川途恍悠邈，涕下一闌干。"]', '["理郡無異政，所憂在素飡。","徒令去京国，羈旅當歲寒。","子月生一氣，陽景極南端。","已懷时節感，更抱別離酸。","私燕席云罷，還斋夜方闌。","邃幕沈空宇，孤灯照牀單。","應同茲夕念，寧忘故歲歡。","川途恍悠邈，涕下一闌干。"]', '诗', 'shi', '', NULL, '冬至夜寄京師諸弟兼懷崔都水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7babe39c-9fe0-4a82-9b37-c1ab323f3f8b', '元日寄諸弟兼呈崔都水', '元日寄諸弟兼呈崔都水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一從守茲郡，兩鬢生素髮。","新正加我年，故歲去超忽。","淮濱益時候，了似仲秋月。","川谷風景溫，城池草木發。","高齋屬多暇，惆悵臨芳物。","日月昧還期，念君何時歇。"]', '["一從守茲郡，兩鬢生素髮。","新正加我年，故歲去超忽。","淮濱益时候，了似仲秋月。","川谷风景溫，城池草木發。","高斋屬多暇，惆悵臨芳物。","日月昧還期，念君何时歇。"]', '诗', 'shi', '', NULL, '元日寄諸弟兼呈崔都水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9f434df-6382-4255-9d63-9f4ca0a77d1c', '寄職方劉郎中', '寄職方劉郎中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["相聞二十載，不得展平生。","一夕南宮遇，聊用寫中情。","端服光朝次，羣烈慕英聲。","歸來坐粉闈，揮筆乃縱橫。","始陪文翰遊，歡燕難久幷。","予因謬忝出，君爲沈疾嬰。","別離寒暑過，荏苒春草生。","故園茲日隔，新禽池上鳴。","郡中永無事，歸思徒自盈。"]', '["相闻二十載，不得展平生。","一夕南宮遇，聊用寫中情。","端服光朝次，羣烈慕英声。","归来坐粉闈，揮笔乃縱橫。","始陪文翰游，歡燕难久幷。","予因謬忝出，君爲沈疾嬰。","別離寒暑過，荏苒春草生。","故园茲日隔，新禽池上鳴。","郡中永無事，归思徒自盈。"]', '诗', 'shi', '', NULL, '寄職方劉郎中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be4cbc5-1ccd-471f-8401-cdc83b732711', '社日寄崔都水及諸弟羣屬', '社日寄崔都水及諸弟羣屬', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山郡多暇日，社時放吏歸。","坐閣獨成悶，行塘閱清輝。","春風動高柳，芳園掩夕扉。","遙思里中會，心緒悵微微。"]', '["山郡多暇日，社时放吏归。","坐閣独成悶，行塘閱清輝。","春风动高柳，芳园掩夕扉。","遙思里中會，心緒悵微微。"]', '诗', 'shi', '', NULL, '社日寄崔都水及諸弟羣屬 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43410b8c-4207-4410-a9cb-773cede6157f', '寒食日寄諸弟', '寒食日寄諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["禁火曖佳辰，念離獨傷抱。","見此野田花，心思杜陵道。","聯騎定何時，予今顏已老。"]', '["禁火曖佳辰，念離独傷抱。","见此野田花，心思杜陵道。","聯騎定何时，予今顏已老。"]', '诗', 'shi', '', NULL, '寒食日寄諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a6fd0c-1cc3-4521-bde9-ac269438cfb3', '三月三日寄諸弟兼懷崔都水', '三月三日寄諸弟兼懷崔都水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["暮節看已謝，茲晨愈可惜。","風澹意傷春，池寒花斂夕。","對酒始依依，懷人還的的。","誰當曲水行，相思尋舊跡。"]', '["暮節看已謝，茲晨愈可惜。","风澹意傷春，池寒花斂夕。","对酒始依依，懷人還的的。","誰當曲水行，相思尋旧跡。"]', '诗', 'shi', '', NULL, '三月三日寄諸弟兼懷崔都水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('931fb508-1f2d-4295-b58b-953dbe2bd8fd', '贈李儋侍御', '贈李儋侍御', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["風光山郡少，來看廣陵春。","殘花猶待客，莫問意中人。"]', '["风光山郡少，来看廣陵春。","殘花猶待客，莫问意中人。"]', '诗', 'shi', '', NULL, '贈李儋侍御 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb0b51a-dcde-45fa-b505-3aea3fbe0076', '寄楊協律', '寄楊協律', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["吏散門閣掩，鳥鳴山郡中。","遠念長江別，俯覺座隅空。","舟泊南池雨，簟捲北樓風。","併罷芳樽燕，爲愴昨時同。"]', '["吏散门閣掩，鸟鳴山郡中。","远念长江別，俯覺座隅空。","舟泊南池雨，簟捲北楼风。","併罷芳樽燕，爲愴昨时同。"]', '诗', 'shi', '', NULL, '寄楊協律 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c6c56c-1773-423f-a2e7-26a7bae46cfd', '郡齋贈王卿', '郡斋贈王卿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["無術謬稱簡，素餐空自嗟。","秋齋雨成滯，山藥寒始華。","濩落人皆笑，幽獨歲逾賒。","唯君出塵意，賞愛似山家。"]', '["無術謬稱簡，素餐空自嗟。","秋斋雨成滯，山藥寒始华。","濩落人皆笑，幽独歲逾賒。","唯君出塵意，賞愛似山家。"]', '诗', 'shi', '', NULL, '郡齋贈王卿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c222a046-9a8c-4554-81e9-bee95fef8aa1', '簡恆璨', '簡恆璨', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["室虛多涼氣，天高屬秋時。","空庭夜風雨，草木曉離披。","簡書日云曠，文墨誰復持。","聊因遇澄靜，一與道人期。"]', '["室虛多涼氣，天高屬秋时。","空庭夜风雨，草木晓離披。","簡书日云曠，文墨誰复持。","聊因遇澄静，一與道人期。"]', '诗', 'shi', '', NULL, '簡恆璨 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa66e60-7ab6-4173-8533-d33ab02ac06d', '閑居寄諸弟', '闲居寄諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秋艸生庭白露時，故園諸弟益相思。","盡日高齋無一事，芭蕉葉上獨題詩。"]', '["秋艸生庭白露时，故园諸弟益相思。","尽日高斋無一事，芭蕉葉上独題诗。"]', '诗', 'shi', '', NULL, '閑居寄諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6669bbb2-5ef2-4c76-a95f-903042c6809b', '登樓寄王卿', '登楼寄王卿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["踏閣攀林恨不同，楚雲滄海思無窮。","數家砧杵秋山下，一郡荆榛寒雨中。"]', '["踏閣攀林恨不同，楚云滄海思無窮。","數家砧杵秋山下，一郡荆榛寒雨中。"]', '诗', 'shi', '', NULL, '登樓寄王卿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5344df84-20ec-41c5-9df0-939e5ab29644', '寄暢當', '寄暢當', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["寇賊起東山，英俊方未閑。","聞君新應募，籍籍動京關。","出身文翰場，高步不可攀。","青袍未及解，白羽插腰間。","昔爲瓊樹枝，今有風霜顏。","秋郊細柳道，走馬一夕還。","丈夫當爲國，破敵如摧山。","何必事州府，坐使鬢毛斑。"]', '["寇賊起东山，英俊方未闲。","闻君新應募，籍籍动京关。","出身文翰場，高步不可攀。","青袍未及解，白羽插腰间。","昔爲瓊樹枝，今有风霜顏。","秋郊細柳道，走马一夕還。","丈夫當爲国，破敵如摧山。","何必事州府，坐使鬢毛斑。"]', '诗', 'shi', '', NULL, '寄暢當 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f0c0d49-b384-4605-9fc2-607ad457e02f', '贈崔員外', '贈崔員外', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一別十年事，相逢淮海濱。","還思洛陽日，更話府中人。","且對清觴滿，寧知白髮新。","怱怱何處去，車馬冒風塵。"]', '["一別十年事，相逢淮海濱。","還思洛陽日，更話府中人。","且对清觴满，寧知白髮新。","怱怱何处去，车马冒风塵。"]', '诗', 'shi', '', NULL, '贈崔員外 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8435b46d-bbf1-49e5-af66-6f2d5681f1bf', '寄李儋元錫', '寄李儋元錫', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["去年花裏逢君別，今日花開已一年。","世事茫茫難自料，春愁黯黯獨成眠。","身多疾病思田里，邑有流亡愧俸錢。","聞道欲來相問訊，西樓望月幾廻圓。"]', '["去年花裏逢君別，今日花开已一年。","世事茫茫难自料，春愁黯黯独成眠。","身多疾病思田里，邑有流亡愧俸錢。","闻道欲来相问訊，西楼望月幾廻圓。"]', '诗', 'shi', '', NULL, '寄李儋元錫 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce9efeef-a809-480f-9049-1f886d695963', '京師叛亂寄諸弟', '京師叛亂寄諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["弱冠遭世難，二紀猶未平。","羇離官遠郡，虎豹滿西京。","上懷犬馬戀，下有骨肉情。","歸去在何時，流淚忽霑纓。","憂來上北樓，左右但軍營。","函谷行人絕，淮南春草生。","鳥鳴野田間，思憶故園行。","何當四海晏，甘與齊民耕。"]', '["弱冠遭世难，二紀猶未平。","羇離官远郡，虎豹满西京。","上懷犬马戀，下有骨肉情。","归去在何时，流泪忽霑纓。","憂来上北楼，左右但軍營。","函谷行人絕，淮南春草生。","鸟鳴野田间，思憶故园行。","何當四海晏，甘與齊民耕。"]', '诗', 'shi', '', NULL, '京師叛亂寄諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b923d1-65b0-4f3f-9d12-16a99b686a83', '贈琮公', '贈琮公', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山僧一相訪，吏案正盈前。","出處似殊致，喧靜兩皆禪。","暮春華池宴，清夜高齋眠。","此道本無得，寧復有忘筌。"]', '["山僧一相訪，吏案正盈前。","出处似殊致，喧静兩皆禪。","暮春华池宴，清夜高斋眠。","此道本無得，寧复有忘筌。"]', '诗', 'shi', '', NULL, '贈琮公 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e588a03-7f6b-4c83-bf35-8dcf48d28afd', '寄諸弟', '寄諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["歲暮兵戈亂京國，帛書間道訪存亡。","還信忽從天上落，唯知彼此淚千行。"]', '["歲暮兵戈亂京国，帛书间道訪存亡。","還信忽從天上落，唯知彼此泪千行。"]', '诗', 'shi', '', NULL, '寄諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5028501b-3683-4c89-9255-46f10bf27729', '寄恆璨', '寄恆璨', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["心絕去來緣，跡順人間事。","獨尋秋草徑，夜宿寒山寺。","今日郡齋閑，思問楞伽字。"]', '["心絕去来緣，跡順人间事。","独尋秋草徑，夜宿寒山寺。","今日郡斋闲，思问楞伽字。"]', '诗', 'shi', '', NULL, '寄恆璨 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba9d202-9c99-450b-84c8-23f51130df0e', '簡郡中諸生', '簡郡中諸生', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["守郡臥秋閣，四面盡荒山。","此時聽夜雨，孤燈照窗間。","藥園日蕪沒，書帷長自閑。","惟當上客至，論詩一解顏。"]', '["守郡臥秋閣，四面尽荒山。","此时听夜雨，孤灯照窗间。","藥园日蕪沒，书帷长自闲。","惟當上客至，論诗一解顏。"]', '诗', 'shi', '', NULL, '簡郡中諸生 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46503396-3bb3-449c-9c84-f2ff232f7949', '寄全椒山中道士', '寄全椒山中道士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["今朝郡齋冷，忽念山中客。","澗底束荆薪，歸來煮白石。","欲持一瓢酒，遠慰風雨夕。","落葉滿空山，何處尋行跡。"]', '["今朝郡斋冷，忽念山中客。","澗底束荆薪，归来煮白石。","欲持一瓢酒，远慰风雨夕。","落葉满空山，何处尋行跡。"]', '诗', 'shi', '', NULL, '寄全椒山中道士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5799af9-92b4-47f5-988d-9fc4edc8dbbd', '寄釋子良史酒', '寄釋子良史酒', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秋山僧冷病，聊寄三五杯。","應瀉山瓢裏，還寄此瓢來。"]', '["秋山僧冷病，聊寄三五杯。","應瀉山瓢裏，還寄此瓢来。"]', '诗', 'shi', '', NULL, '寄釋子良史酒 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e48d4c21-00ce-4f4f-b08c-9b29ac678af9', '重寄', '重寄', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["復寄滿瓢去，定見空瓢來。","若不打瓢破，終當費酒材。"]', '["复寄满瓢去，定见空瓢来。","若不打瓢破，終當費酒材。"]', '诗', 'shi', '', NULL, '重寄 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36309b08-b592-4143-acf6-a5424993fa1e', '答釋子良史送酒瓢', '答釋子良史送酒瓢', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["此瓢今已到，山瓢知已空。","且飲寒塘水，遙將回也同。"]', '["此瓢今已到，山瓢知已空。","且饮寒塘水，遙將回也同。"]', '诗', 'shi', '', NULL, '答釋子良史送酒瓢 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f57ecbec-fe77-4a74-889d-1b95dbc8ec07', '簡陟巡建三甥', '簡陟巡建三甥', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["忽羨後生連榻話，獨依寒燭一齋空。","時流歡笑事從別，把酒吟詩待爾同。"]', '["忽羨後生連榻話，独依寒燭一斋空。","时流歡笑事從別，把酒吟诗待爾同。"]', '诗', 'shi', '', NULL, '簡陟巡建三甥 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54eb6543-4506-426c-8761-f5963d8fc9af', '覽襃子臥病一絕聊以題示', '覽襃子臥病一絕聊以題示', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["念子抱沈疾，霜露變滁城。","獨此高窗下，自然無世情。"]', '["念子抱沈疾，霜露变滁城。","独此高窗下，自然無世情。"]', '诗', 'shi', '', NULL, '覽襃子臥病一絕聊以題示 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3100f6b2-4f4a-4fdf-bb2c-c53b2528e909', '寄璨師', '寄璨師', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["林院生夜色，西廊上紗燈。","時憶長松下，獨坐一山僧。"]', '["林院生夜色，西廊上紗灯。","时憶长松下，独坐一山僧。"]', '诗', 'shi', '', NULL, '寄璨師 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d6e1bcc-8bbc-4ad5-8458-d58a34fca568', '寄盧陟', '寄盧陟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["柳葉遍寒塘，曉霜凝高閣。","累日此流連，別來成寂寞。"]', '["柳葉遍寒塘，晓霜凝高閣。","累日此流連，別来成寂寞。"]', '诗', 'shi', '', NULL, '寄盧陟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a32f4101-0ba6-4409-bebe-7a3671d97a38', '途中寄楊邈裴緒示襃子', '途中寄楊邈裴緒示襃子', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["上宰領淮右，下國屬星馳。","霧野騰曉騎，霜竿裂凍旗。","蕭蕭陟連岡，莽莽望空陂。","風截鴈嘹淚，雲慘樹參差。","高齋明月夜，中庭松桂姿。","當暌一酌恨，況此兩旬期。"]', '["上宰領淮右，下国屬星驰。","霧野腾晓騎，霜竿裂凍旗。","蕭蕭陟連岡，莽莽望空陂。","风截鴈嘹泪，云慘樹參差。","高斋明月夜，中庭松桂姿。","當暌一酌恨，況此兩旬期。"]', '诗', 'shi', '', NULL, '途中寄楊邈裴緒示襃子 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d885ed0-5113-4495-9c72-5e6e6fa0b0e7', '宿永陽寄璨律師', '宿永陽寄璨律師', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遙知郡齋夜，凍雪封松竹。","時有山僧來，懸燈獨自宿。"]', '["遙知郡斋夜，凍雪封松竹。","时有山僧来，懸灯独自宿。"]', '诗', 'shi', '', NULL, '宿永陽寄璨律師 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c064e912-16a7-44ee-a19e-7f11cf5c676a', '雪行寄襃子', '雪行寄襃子', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["淅瀝覆寒騎，飄颻暗川容。","行子郡城曉，披雲看杉松。"]', '["淅瀝覆寒騎，飄颻暗川容。","行子郡城晓，披云看杉松。"]', '诗', 'shi', '', NULL, '雪行寄襃子 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc54a18-46f4-4f28-9f95-01c987afc9a0', '寄裴處士', '寄裴处士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["春風駐遊騎，晚景澹山暉。","一問清泠子，獨掩荒園扉。","草木雨來長，里閭人到稀。","方從廣陵宴，花落未言歸。"]', '["春风駐游騎，晚景澹山暉。","一问清泠子，独掩荒园扉。","草木雨来长，里閭人到稀。","方從廣陵宴，花落未言归。"]', '诗', 'shi', '', NULL, '寄裴處士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652cdae6-ec60-4dc2-9c3c-ed128d0f28ff', '偶入西齋院示釋子恆璨', '偶入西斋院示釋子恆璨', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["僧齋地雖密，忘子跡要賒。","一來非問訊，自是看山花。"]', '["僧斋地雖密，忘子跡要賒。","一来非问訊，自是看山花。"]', '诗', 'shi', '', NULL, '偶入西齋院示釋子恆璨 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e105457-08ca-48c7-a77d-c1bc47b7f69d', '示全真元常', '示全真元常', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["余辭郡符去，爾爲外事牽。","寧知風雪夜，復此對牀眠。","始話南池飲，更詠西樓篇。","無將一會易，歲月坐推遷。"]', '["余辞郡符去，爾爲外事牽。","寧知风雪夜，复此对牀眠。","始話南池饮，更詠西楼篇。","無將一會易，歲月坐推遷。"]', '诗', 'shi', '', NULL, '示全真元常 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e8da910-15dd-443b-aba8-1b4cb1aecb4d', '寄劉尊師', '寄劉尊師', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["世間荏苒縈此身，長望碧山到無因。","白鶴徘徊看不去，遙知下有清都人。"]', '["世间荏苒縈此身，长望碧山到無因。","白鹤徘徊看不去，遙知下有清都人。"]', '诗', 'shi', '', NULL, '寄劉尊師 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c32284e3-2ad7-46b1-a1d1-b9ea203d4935', '寄廬山椶衣居士', '寄廬山椶衣居士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["兀兀山行無處歸，山中猛虎識椶衣。","俗客欲尋應不遇，雲溪道士見猶稀。"]', '["兀兀山行無处归，山中猛虎識椶衣。","俗客欲尋應不遇，云溪道士见猶稀。"]', '诗', 'shi', '', NULL, '寄廬山椶衣居士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66b5b451-6b63-4977-b257-e66478fed4ae', '因省風俗與從姪成緒遊山水中道先歸寄示', '因省风俗與從姪成緒游山水中道先归寄示', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["累宵同燕酌，十舍攜征騎。","始造雙林寂，遐搜洞府祕。","羣峰繞盤鬱，懸泉仰特異。","陰壑雲松埋，陽崖煙花媚。","每慮觀省牽，中乖遊踐志。","我尚山水行，子歸棲息地。","一操臨流袂，上聳干雲轡。","獨往倦危途，懷沖寡幽致。","賴爾還都期，方將登樓遲。"]', '["累宵同燕酌，十舍携征騎。","始造雙林寂，遐搜洞府祕。","羣峰繞盤鬱，懸泉仰特異。","陰壑云松埋，陽崖煙花媚。","每慮观省牽，中乖游踐志。","我尚山水行，子归棲息地。","一操臨流袂，上聳干云轡。","独往倦危途，懷沖寡幽致。","賴爾還都期，方將登楼遲。"]', '诗', 'shi', '', NULL, '因省風俗與從姪成緒遊山水中道先歸寄示 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed7ce24a-197a-42fb-a622-e331144496b4', '寒食寄京師諸弟', '寒食寄京師諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雨中禁火空齋冷，江上流鶯獨坐聽。","把酒看花想諸弟，杜陵寒食草青青。"]', '["雨中禁火空斋冷，江上流鶯独坐听。","把酒看花想諸弟，杜陵寒食草青青。"]', '诗', 'shi', '', NULL, '寒食寄京師諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0eae94-0bd8-49f6-b87f-a1fab2f196dd', '歲日寄京師諸[季]端武等', '歲日寄京師諸[季]端武等', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["獻歲抱深惻，僑居念歸緣。","常患親愛離，始覺世務牽。","少事河陽府，晚守淮南壖。","平生幾會散，已及蹉跎年。","昨日罷符竹，家貧遂留連。","部曲多已去，車馬不復全。","閑將酒爲偶，默以道自詮。","聽松南巖寺，見月西澗泉。","爲政無異術，當責豈望遷。","終理來時裝，歸鑿杜陵田。"]', '["獻歲抱深惻，僑居念归緣。","常患親愛離，始覺世務牽。","少事河陽府，晚守淮南壖。","平生幾會散，已及蹉跎年。","昨日罷符竹，家貧遂留連。","部曲多已去，车马不复全。","闲將酒爲偶，默以道自詮。","听松南巖寺，见月西澗泉。","爲政無異術，當責豈望遷。","終理来时裝，归鑿杜陵田。"]', '诗', 'shi', '', NULL, '歲日寄京師諸[季]端武等 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c6d320-b3b2-473b-8978-ad9f3a39ee60', '簡盧陟', '簡盧陟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["可憐白雪曲，未遇知音人。","恓惶戎旅下，蹉跎淮海濱。","澗樹含朝雨，山鳥哢餘春。","我有一瓢酒，可以慰風塵。"]', '["可怜白雪曲，未遇知音人。","恓惶戎旅下，蹉跎淮海濱。","澗樹含朝雨，山鸟哢餘春。","我有一瓢酒，可以慰风塵。"]', '诗', 'shi', '', NULL, '簡盧陟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e99e6a8-2880-4c2c-90f3-fa762dba9724', '西澗即事示盧陟', '西澗即事示盧陟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["寢扉臨碧澗，晨起澹忘情。","空林細雨至，圓文遍水生。","永日無餘事，山中伐木聲。","知子塵喧久，暫可散煩纓。"]', '["寢扉臨碧澗，晨起澹忘情。","空林細雨至，圓文遍水生。","永日無餘事，山中伐木声。","知子塵喧久，暫可散煩纓。"]', '诗', 'shi', '', NULL, '西澗即事示盧陟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aef24cb-945d-410b-aff3-a1ce838780a2', '登郡寄京師諸季淮南子弟', '登郡寄京師諸季淮南子弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["始罷永陽守，復臥潯陽樓。","懸檻飄寒雨，危堞侵江流。","迨茲聞雁夜，重憶別離秋。","徒有盈樽酒，鎮此百端憂。"]', '["始罷永陽守，复臥潯陽楼。","懸檻飄寒雨，危堞侵江流。","迨茲闻雁夜，重憶別離秋。","徒有盈樽酒，鎮此百端憂。"]', '诗', 'shi', '', NULL, '登郡寄京師諸季淮南子弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42b4c71e-e70b-4aa5-af91-0db1b1c9d5ea', '寄黃尊師', '寄黄尊師', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["結茅種杏在雲端，掃雪焚香宿石壇。","靈祇不許世人到，忽作雷風登嶺難。"]', '["結茅種杏在云端，掃雪焚香宿石壇。","靈祇不許世人到，忽作雷风登嶺难。"]', '诗', 'shi', '', NULL, '寄黃尊師 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7913e7de-ef79-4534-8b35-6dfde61fd8e9', '寄黃劉二尊師', '寄黄劉二尊師', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["廬山兩道士，各在一峰居。","矯掌白雲表，晞髮陽和初。","清夜降真侶，焚香滿空虛。","中有無爲樂，自然與世疎。","道尊不可屈，符守豈暇餘。","高齋遙致敬，願示一編書。"]', '["廬山兩道士，各在一峰居。","矯掌白云表，晞髮陽和初。","清夜降真侶，焚香满空虛。","中有無爲乐，自然與世疎。","道尊不可屈，符守豈暇餘。","高斋遙致敬，願示一編书。"]', '诗', 'shi', '', NULL, '寄黃劉二尊師 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96455db1-a0c6-402c-8892-05c6b9a3d029', '秋夜寄丘二十二員外', '秋夜寄丘二十二員外', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["懷君屬秋夜，散步詠涼天。","山空松子落，幽人應未眠。"]', '["懷君屬秋夜，散步詠涼天。","山空松子落，幽人應未眠。"]', '诗', 'shi', '', NULL, '秋夜寄丘二十二員外 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9deac157-0946-47da-9f9a-9094a2f5bdae', '贈丘員外二首 一', '贈丘員外二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高詞棄浮靡，貞行表鄉閭。","未真南宮拜，聊偃東山居。","大藩本多事，日與文章疎。","每一覩之子，高詠遂起予。","宵晝方連燕，煩恡亦頓祛。","格言雅誨闕，善謔矜數餘。","久跼思遊曠，窮慘遇陽舒。","虎丘愜登眺，吳門悵躊躇。","方此戀攜手，豈云還舊墟。","告諸吳子弟，文學爲何如。"]', '["高词棄浮靡，貞行表乡閭。","未真南宮拜，聊偃东山居。","大藩本多事，日與文章疎。","每一覩之子，高詠遂起予。","宵晝方連燕，煩恡亦頓祛。","格言雅誨闕，善謔矜數餘。","久跼思游曠，窮慘遇陽舒。","虎丘愜登眺，吳门悵躊躇。","方此戀携手，豈云還旧墟。","告諸吳子弟，文学爲何如。"]', '诗', 'shi', '', NULL, '贈丘員外二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d01edfd-9e02-4a1c-a4a6-3e0acf11dd62', '贈丘員外二首 二', '贈丘員外二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["跡與孤雲遠，心將野鶴俱。","那同石氏子，每到府門趨。"]', '["跡與孤云远，心將野鹤俱。","那同石氏子，每到府门趨。"]', '诗', 'shi', '', NULL, '贈丘員外二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03a9fde8-1a26-41ac-8fc8-0195b16a38d5', '贈李判官', '贈李判官', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["良玉定爲寶，長材世所稀。","佐幕方巡郡，奏命布恩威。","食蔬程獨守，飲冰節靡違。","決獄興邦頌，高文稟天機。","賓館在林表，望山啓西扉。","下有千畝田，泱漭吳土肥。","始耕已見穫，袗絺今授衣。","政拙勞詳省，淹留未得歸。","雖慙且忻願，日夕覩光輝。"]', '["良玉定爲寶，长材世所稀。","佐幕方巡郡，奏命布恩威。","食蔬程独守，饮冰節靡違。","決獄兴邦頌，高文稟天機。","賓館在林表，望山啓西扉。","下有千畝田，泱漭吳土肥。","始耕已见穫，袗絺今授衣。","政拙勞詳省，淹留未得归。","雖慙且忻願，日夕覩光輝。"]', '诗', 'shi', '', NULL, '贈李判官 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c3bd4fb-9400-4f20-b667-50141679abbb', '寄皎然上人', '寄皎然上人', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["吳興老釋子，野雪蓋精廬。","詩名徒自振，道心長晏如。","想茲棲禪夜，見月東峰初。","鳴鐘驚巖壑，焚香滿空虛。","叨慕端成舊，未識豈爲疎。","願以碧雲思，方君怨別餘。","茂苑文華地，流水古僧居。","何當一遊詠，倚閣吟躊躇。"]', '["吳兴老釋子，野雪蓋精廬。","诗名徒自振，道心长晏如。","想茲棲禪夜，见月东峰初。","鳴鐘驚巖壑，焚香满空虛。","叨慕端成旧，未識豈爲疎。","願以碧云思，方君怨別餘。","茂苑文华地，流水古僧居。","何當一游詠，倚閣吟躊躇。"]', '诗', 'shi', '', NULL, '寄皎然上人 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f06116-cbd0-4f5c-9e32-1414b666c561', '贈舊識', '贈旧識', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["少年遊太學，負氣蔑諸生。","蹉跎三十載，今日海隅行。"]', '["少年游太学，負氣蔑諸生。","蹉跎三十載，今日海隅行。"]', '诗', 'shi', '', NULL, '贈舊識 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78f8ccd5-d32a-41ad-81cf-763be1de2352', '復理西齋寄丘員外', '复理西斋寄丘員外', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["前歲理西齋，得與君子同。","迨茲已一周，悵望臨春風。","始自疎林竹，還復長榛叢。","端正良難久，蕪穢易爲功。","援斧開衆鬱，如師啓羣蒙。","庭宇還清曠，煩抱亦舒通。","海隅雨雪霽，春序風景融。","時物方如故，懷賢思無窮。"]', '["前歲理西斋，得與君子同。","迨茲已一周，悵望臨春风。","始自疎林竹，還复长榛叢。","端正良难久，蕪穢易爲功。","援斧开衆鬱，如師啓羣蒙。","庭宇還清曠，煩抱亦舒通。","海隅雨雪霽，春序风景融。","时物方如故，懷賢思無窮。"]', '诗', 'shi', '', NULL, '復理西齋寄丘員外 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f9535fc-6a54-4bab-8cf9-d786375155da', '和張舍人夜直中書寄吏部劉員外', '和張舍人夜直中书寄吏部劉員外', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["西垣草詔罷，南宮憶上才。","月臨蘭殿出，涼自鳳池來。","松桂生丹禁，鴛鷺集雲臺。","託身各有所，相望徒徘徊。"]', '["西垣草詔罷，南宮憶上才。","月臨蘭殿出，涼自鳳池来。","松桂生丹禁，鴛鷺集云台。","託身各有所，相望徒徘徊。"]', '诗', 'shi', '', NULL, '和張舍人夜直中書寄吏部劉員外 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea87cf5c-f4b1-404d-b2f4-391143b570d0', '和李二主簿寄淮上綦毋三', '和李二主簿寄淮上綦毋三', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["滿城憐傲吏，終日賦新詩。","請報淮陰客，春帆浪作期。"]', '["满城怜傲吏，終日賦新诗。","請報淮陰客，春帆浪作期。"]', '诗', 'shi', '', NULL, '和李二主簿寄淮上綦毋三 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4501fd99-4a46-4994-afc9-056ec629fa6f', '寄二嚴', '寄二嚴', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["絲竹久已懶，今日遇君忺。","打破蜘蛛千道網，總爲鶺鴒兩箇嚴。"]', '["絲竹久已懶，今日遇君忺。","打破蜘蛛千道網，總爲鶺鴒兩箇嚴。"]', '诗', 'shi', '', NULL, '寄二嚴 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af5671d-7a66-48a3-b22c-8386d3a668f8', '李五席送李主簿歸西臺', '李五席送李主簿归西台', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["請告嚴程盡，西歸道路寒。","欲陪鷹隼集，猶戀鶺鴒單。","洛邑人全少，嵩高雪尚殘。","滿臺誰不故，報我在微官。"]', '["請告嚴程尽，西归道路寒。","欲陪鷹隼集，猶戀鶺鴒單。","洛邑人全少，嵩高雪尚殘。","满台誰不故，報我在微官。"]', '诗', 'shi', '', NULL, '李五席送李主簿歸西臺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('593ae5b3-4b44-4478-bf2a-f408a5785659', '送崔押衙相州', '送崔押衙相州', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["禮樂儒家子，英豪燕趙風。","驅雞嘗理邑，走馬却從戎。","白刃千夫闢，黃金四海同。","嫖姚恩顧下，諸將指揮中。","別路憐芳草，歸心伴塞鴻。","鄴城新騎滿，魏帝舊臺空。","望闕應懷戀，遭時貴立功。","萬方如已靜，何處欲輸忠。"]', '["禮乐儒家子，英豪燕趙风。","驱雞嘗理邑，走马却從戎。","白刃千夫闢，黄金四海同。","嫖姚恩顧下，諸將指揮中。","別路怜芳草，归心伴塞鴻。","鄴城新騎满，魏帝旧台空。","望闕應懷戀，遭时貴立功。","万方如已静，何处欲輸忠。"]', '诗', 'shi', '', NULL, '送崔押衙相州 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a4d344-efec-4080-863a-82faa46eaa2c', '送宣城路錄事', '送宣城路錄事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["江上宣城郡，孤舟遠到時。","雲林謝家宅，山水敬亭祠。","綱紀多閑日，觀遊得賦詩。","都門且盡醉，此別數年期。"]', '["江上宣城郡，孤舟远到时。","云林謝家宅，山水敬亭祠。","綱紀多闲日，观游得賦诗。","都门且尽醉，此別數年期。"]', '诗', 'shi', '', NULL, '送宣城路錄事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fab821c1-7d3d-4d65-898f-441e53ff1c6f', '送李十四山東遊', '送李十四山东游', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["聖朝有遺逸，披膽謁至尊。","豈是貿榮寵，誓將救元元。","權豪非所便，書奏寢禁門。","高歌長安酒，忠憤不可吞。","欻來客河洛，日與靜者論。","濟世飜小事，丹砂駐精魂。","東遊無復繫，梁楚多大蕃。","高論動侯伯，疎懷脫塵喧。","送君都門野，飲我林中樽。","立馬望東道，白雲滿梁園。","踟躕欲何贈，空是平生言。"]', '["聖朝有遺逸，披膽謁至尊。","豈是貿榮寵，誓將救元元。","權豪非所便，书奏寢禁门。","高歌长安酒，忠憤不可吞。","欻来客河洛，日與静者論。","濟世飜小事，丹砂駐精魂。","东游無复繫，梁楚多大蕃。","高論动侯伯，疎懷脫塵喧。","送君都门野，饮我林中樽。","立马望东道，白云满梁园。","踟躕欲何贈，空是平生言。"]', '诗', 'shi', '', NULL, '送李十四山東遊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e381ff-c51c-4fe2-9326-64d832bc4c4b', '送李二歸楚州', '送李二归楚州', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["情人南楚別，復詠在原詩。","忽此嗟歧路，還令泣素絲。","風波朝夕遠，音信往來遲。","好去扁舟客，青雲何處期。"]', '["情人南楚別，复詠在原诗。","忽此嗟歧路，還令泣素絲。","风波朝夕远，音信往来遲。","好去扁舟客，青云何处期。"]', '诗', 'shi', '', NULL, '送李二歸楚州 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de217f9f-e4f0-45d0-b87f-97a3ae4784aa', '送閻寀赴東川辟', '送閻寀赴东川辟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["冰炭俱可懷，孰云熱與寒。","何如結髮友，不得攜手懽。","晨登嚴霜野，送子天一端。","祗承簡書命，俯仰豸角冠。","上陟白雲嶠，下冥玄壑湍。","離羣自有託，歷險得所安。","當念反窮巷，登朝成慨嘆。"]', '["冰炭俱可懷，孰云熱與寒。","何如結髮友，不得携手懽。","晨登嚴霜野，送子天一端。","祗承簡书命，俯仰豸角冠。","上陟白云嶠，下冥玄壑湍。","離羣自有託，歷險得所安。","當念反窮巷，登朝成慨嘆。"]', '诗', 'shi', '', NULL, '送閻寀赴東川辟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('337639a4-b1f1-4e9d-b0a3-5a48dba69d56', '送令狐岫宰恩陽', '送令狐岫宰恩陽', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["大雪天地閉，羣山夜來晴。","居家猶苦寒，子有千里行。","行行安得辭，荷此蒲璧榮。","賢豪爭追攀，飲餞出西京。","樽酒豈不歡，暮春自有程。","離人起視日，僕御促前征。","逶遲歲已窮，當造巴子城。","和風被草木，江水日夜清。","從來知善政，離別慰友生。"]', '["大雪天地閉，羣山夜来晴。","居家猶苦寒，子有千里行。","行行安得辞，荷此蒲璧榮。","賢豪爭追攀，饮餞出西京。","樽酒豈不歡，暮春自有程。","離人起視日，僕御促前征。","逶遲歲已窮，當造巴子城。","和风被草木，江水日夜清。","從来知善政，離別慰友生。"]', '诗', 'shi', '', NULL, '送令狐岫宰恩陽 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5575cb2e-f83e-46b5-963d-1fad347af280', '送馮著受李廣州署爲錄事', '送馮著受李廣州署爲錄事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鬱鬱楊柳枝，蕭蕭征馬悲。","送君灞陵岸，糾郡南海湄。","名在翰墨場，羣公正追隨。","如何從此去，千里萬里期。","大海吞東南，橫嶺隔地維。","建邦臨日域，溫燠御四時。","百國共臻奏，珍奇獻京師。","富豪虞興戎，繩墨不易持。","州伯荷天寵，還當翊丹墀。","子爲門下生，終始豈見遺。","所願酌貪泉，心不爲磷緇。","上將玩國士，下以報渴飢。"]', '["鬱鬱楊柳枝，蕭蕭征马悲。","送君灞陵岸，糾郡南海湄。","名在翰墨場，羣公正追隨。","如何從此去，千里万里期。","大海吞东南，橫嶺隔地維。","建邦臨日域，溫燠御四时。","百国共臻奏，珍奇獻京師。","富豪虞兴戎，繩墨不易持。","州伯荷天寵，還當翊丹墀。","子爲门下生，終始豈见遺。","所願酌貪泉，心不爲磷緇。","上將玩国士，下以報渴飢。"]', '诗', 'shi', '', NULL, '送馮著受李廣州署爲錄事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55dbaccb-ddf8-467e-94f1-729a96e18e8d', '送元倉曹歸廣陵', '送元倉曹归廣陵', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["官閑得去住，告別戀音徽。","舊國應無業，他鄉到是歸。","楚山明月滿，淮甸夜鐘微。","何處孤舟泊，遙遙心曲違。"]', '["官闲得去住，告別戀音徽。","旧国應無業，他乡到是归。","楚山明月满，淮甸夜鐘微。","何处孤舟泊，遙遙心曲違。"]', '诗', 'shi', '', NULL, '送元倉曹歸廣陵 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd789a80-d20a-49da-a1ba-c0b177ab9e9c', '送唐明府赴溧水', '送唐明府赴溧水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["三爲百里宰，已過十餘年。","祗嘆官如舊，旋聞邑屢遷。","魚鹽濱海利，薑蔗傍湖田。","到此安甿俗，琴堂又晏然。"]', '["三爲百里宰，已過十餘年。","祗嘆官如旧，旋闻邑屢遷。","鱼鹽濱海利，薑蔗傍湖田。","到此安甿俗，琴堂又晏然。"]', '诗', 'shi', '', NULL, '送唐明府赴溧水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41cd3ab4-9463-43b3-8a5c-87c70ca0b35e', '喜於廣陵拜覲家兄奉送發還池州', '喜於廣陵拜覲家兄奉送發還池州', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["青青連枝樹，苒苒久別離。","客遊廣陵中，俱到若有期。","俯仰敘存歿，哀腸發酸悲。","收情且爲歡，累日不知飢。","夙駕多所迫，復當還歸池。","長安三千里，歲晏獨何爲。","南出登閶門，驚飆左右吹。","所別諒非遠，要令心不怡。"]', '["青青連枝樹，苒苒久別離。","客游廣陵中，俱到若有期。","俯仰敘存歿，哀腸發酸悲。","收情且爲歡，累日不知飢。","夙駕多所迫，复當還归池。","长安三千里，歲晏独何爲。","南出登閶门，驚飆左右吹。","所別諒非远，要令心不怡。"]', '诗', 'shi', '', NULL, '喜於廣陵拜覲家兄奉送發還池州 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1353e07f-fe8e-4780-bd14-374dba6d58b8', '送章八元秀才擢第往上都應制', '送章八元秀才擢第往上都應制', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["決勝文場戰已酣，行應辟命復才堪。","旅食不辭遊闕下，春衣未換報江南。","天邊宿鳥生歸思，關外晴山滿夕嵐。","立馬欲從何處別，都門楊柳正毿毿。"]', '["決勝文場戰已酣，行應辟命复才堪。","旅食不辞游闕下，春衣未換報江南。","天邊宿鸟生归思，关外晴山满夕嵐。","立马欲從何处別，都门楊柳正毿毿。"]', '诗', 'shi', '', NULL, '送章八元秀才擢第往上都應制 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bec25d3-378b-4098-a26e-5111edc31bbe', '送張侍御祕書江左覲省', '送張侍御祕书江左覲省', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["莫歎都門路，歸無駟馬車。","繡衣猶在篋，芸閣已觀書。","沃野收紅稻，長江釣白魚。","晨飡亦可薦，名利欲何如。"]', '["莫歎都门路，归無駟马车。","繡衣猶在篋，芸閣已观书。","沃野收紅稻，长江釣白鱼。","晨飡亦可薦，名利欲何如。"]', '诗', 'shi', '', NULL, '送張侍御祕書江左覲省 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('643fa837-422c-458a-9036-81a92d946a55', '賦得鼎門送盧耿赴任', '賦得鼎门送盧耿赴任', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["名因定鼎地，門對鑿龍山。","水北樓臺近，城南車馬還。","稍開芳野靜，欲掩暮鐘閑。","去此無嗟屈，前賢尚抱關。"]', '["名因定鼎地，门对鑿龙山。","水北楼台近，城南车马還。","稍开芳野静，欲掩暮鐘闲。","去此無嗟屈，前賢尚抱关。"]', '诗', 'shi', '', NULL, '賦得鼎門送盧耿赴任 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e22d607-c30a-4ce9-8d29-6728180a3fd3', '賦得浮雲起離色送鄭述誠', '賦得浮云起離色送鄭述誠', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遊子欲言去，浮雲那得知。","偏能見行色，自是獨傷離。","晚帶城遙暗，秋生峰尚奇。","還因朔吹斷，匹馬與相隨。"]', '["游子欲言去，浮云那得知。","偏能见行色，自是独傷離。","晚带城遙暗，秋生峰尚奇。","還因朔吹斷，匹马與相隨。"]', '诗', 'shi', '', NULL, '賦得浮雲起離色送鄭述誠 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0aafd21-88cf-4849-b4b0-524fbadd2566', '餞雍聿之潞州謁李中丞', '餞雍聿之潞州謁李中丞', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鬱鬱雨相遇，出門草青青。","酒酣拔劒舞，慷慨送子行。","驅馬涉大河，日暮懷洛京。","前登太行路，志士亦未平。","薄遊五府都，高步振英聲。","主人才且賢，重士百金輕。","絲竹促飛觴，夜醼達晨星。","娛樂易淹暮，諒在執高情。"]', '["鬱鬱雨相遇，出门草青青。","酒酣拔劒舞，慷慨送子行。","驱马涉大河，日暮懷洛京。","前登太行路，志士亦未平。","薄游五府都，高步振英声。","主人才且賢，重士百金轻。","絲竹促飞觴，夜醼達晨星。","娛乐易淹暮，諒在執高情。"]', '诗', 'shi', '', NULL, '餞雍聿之潞州謁李中丞 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcceee3d-2938-487b-af32-0dda3c4d5fce', '上東門會送李幼舉南遊徐方', '上东门會送李幼舉南游徐方', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["離絃既罷彈，罇酒亦已闌。","聽我歌一曲，南徐在雲端。","雲端雖云邈，行路本非難。","諸侯皆愛才，公子遠結歡。","濟濟都門宴，將去復盤桓。","令姿何昂昂，良馬遠遊冠。","意氣且爲別，由來非所嘆。"]', '["離絃既罷彈，罇酒亦已闌。","听我歌一曲，南徐在云端。","云端雖云邈，行路本非难。","諸侯皆愛才，公子远結歡。","濟濟都门宴，將去复盤桓。","令姿何昂昂，良马远游冠。","意氣且爲別，由来非所嘆。"]', '诗', 'shi', '', NULL, '上東門會送李幼舉南遊徐方 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3f53a5-72a3-4286-b656-04fb4ceb1bf8', '送洛陽韓丞東遊', '送洛陽韓丞东游', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["仙鳥何飄颻，綠衣翠爲襟。","顧我差池羽，咬咬懷好音。","徘徊洛陽中，遊戲清川潯。","神交不在結，歡愛自中心。","駕言忽徂征，雲路邈且深。","朝遊尚同啄，夕息當異林。","出餞宿東郊，列筵屬城陰。","舉酒欲爲樂，憂懷方沈沈。"]', '["仙鸟何飄颻，綠衣翠爲襟。","顧我差池羽，咬咬懷好音。","徘徊洛陽中，游戲清川潯。","神交不在結，歡愛自中心。","駕言忽徂征，云路邈且深。","朝游尚同啄，夕息當異林。","出餞宿东郊，列筵屬城陰。","舉酒欲爲乐，憂懷方沈沈。"]', '诗', 'shi', '', NULL, '送洛陽韓丞東遊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4269cd3d-9f7e-4c42-8335-ca0088089487', '送鄭長源', '送鄭长源', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["少年一相見，飛轡河洛間。","歡遊不知罷，中路忽言還。","泠泠鵾絃哀，悄悄冬夜閑。","丈夫雖耿介，遠別多苦顏。","君行拜高堂，速駕難久攀。","雞鳴儔侶發，朔雪滿河關。","須臾在今夕，罇酌且循環。"]', '["少年一相见，飞轡河洛间。","歡游不知罷，中路忽言還。","泠泠鵾絃哀，悄悄冬夜闲。","丈夫雖耿介，远別多苦顏。","君行拜高堂，速駕难久攀。","雞鳴儔侶發，朔雪满河关。","須臾在今夕，罇酌且循环。"]', '诗', 'shi', '', NULL, '送鄭長源 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c30b450-c7f4-43c0-9df1-524d63508a4c', '送李儋', '送李儋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["別離何從生，乃在親愛中。","反念行路子，拂衣自西東。","日昃不留宴，嚴車出崇墉。","行遊非所樂，端憂道未通。","春野百卉發，清川思無窮。","芳時坐離散，世事誰可同。","歸當掩重關，默默想音容。"]', '["別離何從生，乃在親愛中。","反念行路子，拂衣自西东。","日昃不留宴，嚴车出崇墉。","行游非所乐，端憂道未通。","春野百卉發，清川思無窮。","芳时坐離散，世事誰可同。","归當掩重关，默默想音容。"]', '诗', 'shi', '', NULL, '送李儋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83dcb67c-ccbc-4592-b232-368a6b5275ce', '賦得暮雨送李胄', '賦得暮雨送李胄', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["楚江微雨裏，建業暮鐘時。","漠漠帆來重，冥冥鳥去遲。","海門深不見，浦樹遠含滋。","相送情無限，沾襟比散絲。"]', '["楚江微雨裏，建業暮鐘时。","漠漠帆来重，冥冥鸟去遲。","海门深不见，浦樹远含滋。","相送情無限，沾襟比散絲。"]', '诗', 'shi', '', NULL, '賦得暮雨送李胄 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c48718-06ba-4b1a-b220-0a1f2d2afe23', '留別洛京親友', '留別洛京親友', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["握手出都門，駕言適京師。","豈不懷舊廬，惆悵與子辭。","麗日坐高閣，清觴醼華池。","昨遊倏已過，後遇良未知。","念結路方永，歲陰野無暉。","單車我當前，暮雪子獨歸。","臨流一相望，零淚忽沾衣。"]', '["握手出都门，駕言適京師。","豈不懷旧廬，惆悵與子辞。","丽日坐高閣，清觴醼华池。","昨游倏已過，後遇良未知。","念結路方永，歲陰野無暉。","單车我當前，暮雪子独归。","臨流一相望，零泪忽沾衣。"]', '诗', 'shi', '', NULL, '留別洛京親友 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7ba4e5-9d7b-4e0c-acd9-4b55033c5810', '賦得沙際路送從叔象', '賦得沙際路送從叔象', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["獨樹沙邊人跡稀，欲行愁遠暮鍾時。","野泉幾處侵應盡，不過山僧知問誰。"]', '["独樹沙邊人跡稀，欲行愁远暮鍾时。","野泉幾处侵應尽，不過山僧知问誰。"]', '诗', 'shi', '', NULL, '賦得沙際路送從叔象 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f2c67e1-55c5-430c-9d04-8d9576dec49e', '送榆次林明府', '送榆次林明府', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["無嗟千里遠，亦是宰王畿。","策馬雨中去，逢人關外稀。","邑傳榆石在，路遶晉山微。","別思方蕭索，新秋一葉飛。"]', '["無嗟千里远，亦是宰王畿。","策马雨中去，逢人关外稀。","邑傳榆石在，路遶晉山微。","別思方蕭索，新秋一葉飞。"]', '诗', 'shi', '', NULL, '送榆次林明府 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f47c3f1e-22d6-4f85-a154-d197ad529d61', '雜言送黎六郎', '杂言送黎六郎', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["冰壺見底未見清，少年如玉有詩名。","聞話嵩峰多野寺，不嫌黃綬向陽城。","朱門嚴訓朝辭去，騎出東郊滿飛絮。","河南庭下拜府君，陽城歸路山氛氳。","山氛氳，長不見，釣臺水淥荷已生，少姨廟寒花始徧。","縣閑吏傲與塵隔，移竹疏泉常岸幘。","莫言去作折腰官，豈似長安折腰客。"]', '["冰壺见底未见清，少年如玉有诗名。","闻話嵩峰多野寺，不嫌黄綬向陽城。","朱门嚴訓朝辞去，騎出东郊满飞絮。","河南庭下拜府君，陽城归路山氛氳。","山氛氳，长不见，釣台水淥荷已生，少姨廟寒花始徧。","縣闲吏傲與塵隔，移竹疏泉常岸幘。","莫言去作折腰官，豈似长安折腰客。"]', '诗', 'shi', '', NULL, '雜言送黎六郎 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f3fcee2-0c1b-4150-8be6-2a6a823f2764', '天長寺上方別子西有道', '天长寺上方別子西有道', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["假邑非拙素，況乃別伊人。","聊登釋氏居，攜手戀茲晨。","高曠出塵表，逍遙滌心神。","青山對芳苑，列樹遶通津。","車馬無時絕，行子倦風塵。","今當遵往路，佇立欲何申。","唯持貞白志，以慰心所親。"]', '["假邑非拙素，況乃別伊人。","聊登釋氏居，携手戀茲晨。","高曠出塵表，逍遙滌心神。","青山对芳苑，列樹遶通津。","车马無时絕，行子倦风塵。","今當遵往路，佇立欲何申。","唯持貞白志，以慰心所親。"]', '诗', 'shi', '', NULL, '天長寺上方別子西有道 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0937405c-be42-435b-b59e-f26a0950541c', '送黎六郎赴陽翟少府', '送黎六郎赴陽翟少府', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["試吏向嵩陽，春山躑躅芳。","腰垂新綬色，衣滿舊芸香。","喬樹別時綠，客程關外長。","祗應傳善政，日夕慰高堂。"]', '["試吏向嵩陽，春山躑躅芳。","腰垂新綬色，衣满旧芸香。","喬樹別时綠，客程关外长。","祗應傳善政，日夕慰高堂。"]', '诗', 'shi', '', NULL, '送黎六郎赴陽翟少府 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008ca8a4-5226-475b-968d-edaa3be21cb8', '送別覃孝廉', '送別覃孝廉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["思親自當去，不第未蹉跎。","家住青山下，門前芳草多。","秭歸通遠徼，巫峽注驚波。","州舉年年事，還期復幾何。"]', '["思親自當去，不第未蹉跎。","家住青山下，门前芳草多。","秭归通远徼，巫峽注驚波。","州舉年年事，還期复幾何。"]', '诗', 'shi', '', NULL, '送別覃孝廉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d9c8a1f-5baa-4b18-9d7f-dae56393677e', '送開封盧少府', '送开封盧少府', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雄藩車馬地，作尉有光輝。","滿席賓常侍，闐街燭夜歸。","關河征斾遠，煙樹夕陽微。","到處無留滯，梁園花欲稀。"]', '["雄藩车马地，作尉有光輝。","满席賓常侍，闐街燭夜归。","关河征斾远，煙樹夕陽微。","到处無留滯，梁园花欲稀。"]', '诗', 'shi', '', NULL, '送開封盧少府 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb36b544-6c83-4b89-81b5-cf7e3839958a', '送槐廣落第歸揚州', '送槐廣落第归揚州', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["下第常稱屈，少年心獨輕。","拜親歸海畔，似舅得詩名。","晚對青山別，遙尋芳草行。","還期應不遠，寒露濕蕪城。"]', '["下第常稱屈，少年心独轻。","拜親归海畔，似舅得诗名。","晚对青山別，遙尋芳草行。","還期應不远，寒露濕蕪城。"]', '诗', 'shi', '', NULL, '送槐廣落第歸揚州 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94940d3a-7ed5-4809-b80d-b04e650163a9', '送汾城王主簿', '送汾城王主簿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["少年初帶印，汾上又經過。","芳草歸時徧，情人故郡多。","禁鐘春雨細，宮樹野煙和。","相望東橋別，微風起夕波。"]', '["少年初带印，汾上又經過。","芳草归时徧，情人故郡多。","禁鐘春雨細，宮樹野煙和。","相望东橋別，微风起夕波。"]', '诗', 'shi', '', NULL, '送汾城王主簿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e316ee-4bad-4598-b7cf-3e07180f239d', '送澠池崔主簿', '送澠池崔主簿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["邑帶洛陽道，年年應此行。","當時匹馬客，今日縣人迎。","暮雨投關郡，春風別帝城。","東西殊不遠，朝夕待佳聲。"]', '["邑带洛陽道，年年應此行。","當时匹马客，今日縣人迎。","暮雨投关郡，春风別帝城。","东西殊不远，朝夕待佳声。"]', '诗', 'shi', '', NULL, '送澠池崔主簿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950ba5ca-ed43-46ba-82ff-aef90c479fdd', '送顏司議使蜀訪圖書', '送顏司議使蜀訪圖书', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["軺駕一封急，蜀門千嶺曛。","詎分江轉字，但見路緣雲。","山館夜聽雨，秋猿獨呌羣。","無爲久留滯，聖主待遺文。"]', '["軺駕一封急，蜀门千嶺曛。","詎分江轉字，但见路緣云。","山館夜听雨，秋猿独呌羣。","無爲久留滯，聖主待遺文。"]', '诗', 'shi', '', NULL, '送顏司議使蜀訪圖書 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f32b9e7-ab07-4b99-8448-52eba9d2896c', '奉送從兄宰晉陵', '奉送從兄宰晉陵', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["東郊暮草歇，千里夏雲生。","立馬愁將夕，看山獨送行。","依微吳苑樹，迢遞晉陵城。","慰此斷行別，邑人多頌聲。"]', '["东郊暮草歇，千里夏云生。","立马愁將夕，看山独送行。","依微吳苑樹，迢遞晉陵城。","慰此斷行別，邑人多頌声。"]', '诗', 'shi', '', NULL, '奉送從兄宰晉陵 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb0d0d8-2909-46b1-98db-3153a224e133', '贈別河南李功曹', '贈別河南李功曹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["耿耿抱私戚，寥寥獨掩扉。","臨觴自不飲，況與故人違。","故人方琢磨，瓌朗代所稀。","憲禮更右職，文翰灑天機。","聿來自東山，羣彥仰餘輝。","談笑取高第，綰綬即言歸。","洛都遊燕地，千里及芳菲。","今朝章臺別，楊柳亦依依。","雲霞未改色，山川猶夕暉。","忽復不相見，心思亂霏霏。"]', '["耿耿抱私戚，寥寥独掩扉。","臨觴自不饮，況與故人違。","故人方琢磨，瓌朗代所稀。","憲禮更右職，文翰灑天機。","聿来自东山，羣彥仰餘輝。","談笑取高第，綰綬即言归。","洛都游燕地，千里及芳菲。","今朝章台別，楊柳亦依依。","云霞未改色，山川猶夕暉。","忽复不相见，心思亂霏霏。"]', '诗', 'shi', '', NULL, '贈別河南李功曹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a7a8a69-b61d-4254-964e-7dd549a6fa25', '送五經趙隨登科授廣德尉', '送五經趙隨登科授廣德尉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["明經有清秩，當在石渠中。","獨往宣城郡，高齋謁謝公。","寒原正蕪漫，夕鳥自西東。","秋日不堪別，淒淒多朔風。"]', '["明經有清秩，當在石渠中。","独往宣城郡，高斋謁謝公。","寒原正蕪漫，夕鸟自西东。","秋日不堪別，淒淒多朔风。"]', '诗', 'shi', '', NULL, '送五經趙隨登科授廣德尉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60e616d-5c6f-4e28-ad5d-fab7c6db851e', '宴別幼遐與君貺兄弟', '宴別幼遐與君貺兄弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["乖闕意方弭，安知忽來翔。","累日重歡宴，一旦復離傷。","置酒慰茲夕，秉燭坐華堂。","契闊未及展，晨星出東方。","征人慘已辭，車馬儼成裝。","我懷自無歡，原野滿春光。","羣水含時澤，野雉鳴朝陽。","平生有壯志，不覺淚霑裳。","況自守空宇，日夕但徬徨。"]', '["乖闕意方弭，安知忽来翔。","累日重歡宴，一旦复離傷。","置酒慰茲夕，秉燭坐华堂。","契闊未及展，晨星出东方。","征人慘已辞，车马儼成裝。","我懷自無歡，原野满春光。","羣水含时澤，野雉鳴朝陽。","平生有壯志，不覺泪霑裳。","況自守空宇，日夕但徬徨。"]', '诗', 'shi', '', NULL, '宴別幼遐與君貺兄弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29cec281-c255-4007-8724-e216e5b078ef', '送宣州周錄事', '送宣州周錄事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["清時重儒士，糾郡屬伊人。","薄遊長安中，始得一交親。","英豪若雲集，餞別塞城闉。","高駕臨長路，日夕起風塵。","方念清宵宴，已度芳林春。","從茲一分手，緬邈吳與秦。","但覩年運駛，安知後會因。","唯當存令德，可以解悁勤。"]', '["清时重儒士，糾郡屬伊人。","薄游长安中，始得一交親。","英豪若云集，餞別塞城闉。","高駕臨长路，日夕起风塵。","方念清宵宴，已度芳林春。","從茲一分手，緬邈吳與秦。","但覩年運駛，安知後會因。","唯當存令德，可以解悁勤。"]', '诗', 'shi', '', NULL, '送宣州周錄事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d0603f-f8b1-48d8-91e3-6a7787e096a5', '謝櫟陽令歸西郊贈別諸友生', '謝櫟陽令归西郊贈別諸友生', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["結髮仕州縣，蹉跎在文墨。","徒有排雲心，何由生羽翼。","幸遭明盛日，萬物蒙生植。","獨此抱微痾，頹然謝斯職。","世道方荏苒，郊園思偃息。","爲歡日已延，君子情未極。","馳觴忽云晏，高論良難測。","遊步清都宮，迎風嘉樹側。","晨起西郊道，原野分黍稷。","自樂陶唐人，服勤在微力。","佇君列丹陛，出處兩爲得。"]', '["結髮仕州縣，蹉跎在文墨。","徒有排云心，何由生羽翼。","幸遭明盛日，万物蒙生植。","独此抱微痾，頹然謝斯職。","世道方荏苒，郊园思偃息。","爲歡日已延，君子情未極。","驰觴忽云晏，高論良难測。","游步清都宮，迎风嘉樹側。","晨起西郊道，原野分黍稷。","自乐陶唐人，服勤在微力。","佇君列丹陛，出处兩爲得。"]', '诗', 'shi', '', NULL, '謝櫟陽令歸西郊贈別諸友生 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f775ac78-2e99-49cc-9710-f1ac2c2f01e7', '送端東行', '送端东行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["世承清白遺，躬服古人言。","從官俱守道，歸來共閉門。","驅車何處去，暮雪滿平原。"]', '["世承清白遺，躬服古人言。","從官俱守道，归来共閉门。","驱车何处去，暮雪满平原。"]', '诗', 'shi', '', NULL, '送端東行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e227e0-a8f9-479f-9bbc-68b3b8b7da6f', '送姚孫還河中', '送姚孫還河中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["上國旅遊罷，故園生事微。","風塵滿路起，行人何處歸。","留思芳樹飲，惜別暮春暉。","幾日投關郡，河山對掩扉。"]', '["上国旅游罷，故园生事微。","风塵满路起，行人何处归。","留思芳樹饮，惜別暮春暉。","幾日投关郡，河山对掩扉。"]', '诗', 'shi', '', NULL, '送姚孫還河中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9417801f-4ca2-4456-8bbc-85fcc6cade9f', '始除尚書郎別善福精舍', '始除尚书郎別善福精舍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["簡略非世器，委身同草木。","逍遙精舍居，飲酒自爲足。","累日曾一櫛，對書常懶讀。","社臘會高年，山川恣遊矚。","明世方選士，中朝懸美祿。","除書忽到門，冠帶便拘束。","愧忝郎署跡，謬蒙君子錄。","俯仰垂華纓，飄颻翔輕轂。","行將親愛別，戀此西澗曲。","遠峰明夕川，夏雨生衆綠。","迅風飄野路，廻首不遑宿。","明晨下煙閣，白雲在幽谷。"]', '["簡略非世器，委身同草木。","逍遙精舍居，饮酒自爲足。","累日曾一櫛，对书常懶读。","社臘會高年，山川恣游矚。","明世方選士，中朝懸美祿。","除书忽到门，冠带便拘束。","愧忝郎署跡，謬蒙君子錄。","俯仰垂华纓，飄颻翔轻轂。","行將親愛別，戀此西澗曲。","远峰明夕川，夏雨生衆綠。","迅风飄野路，廻首不遑宿。","明晨下煙閣，白云在幽谷。"]', '诗', 'shi', '', NULL, '始除尚書郎別善福精舍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34b13103-af4f-4f03-adb0-ef2c1b785810', '送常侍御却使西蕃', '送常侍御却使西蕃', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["歸奏聖朝行萬里，却銜天詔報蕃臣。","本是諸生守文墨，今將匹馬靜煙塵。","旅宿關河逢暮雨，春耕亭障識遺民。","此去多應收故地，寧辭沙塞往來頻。"]', '["归奏聖朝行万里，却銜天詔報蕃臣。","本是諸生守文墨，今將匹马静煙塵。","旅宿关河逢暮雨，春耕亭障識遺民。","此去多應收故地，寧辞沙塞往来頻。"]', '诗', 'shi', '', NULL, '送常侍御却使西蕃 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e99c90-2d08-4468-8872-a6cc5dec67dd', '送郗詹事', '送郗詹事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["聖朝列羣彥，穆穆佐休明。","君子獨知止，懸車守國程。","忠良信舊德，文學播英聲。","既獲天爵美，況將齒位幷。","書奏蒙省察，命駕乃東征。","皇恩賜印綬，歸爲田里榮。","朝野同稱歎，園綺鬱齊名。","長衢軒葢集，飲餞出西京。","時屬春陽節，草木已含英。","洛川當盛宴，斯焉爲達生。"]', '["聖朝列羣彥，穆穆佐休明。","君子独知止，懸车守国程。","忠良信旧德，文学播英声。","既獲天爵美，況將齒位幷。","书奏蒙省察，命駕乃东征。","皇恩賜印綬，归爲田里榮。","朝野同稱歎，园綺鬱齊名。","长衢軒葢集，饮餞出西京。","时屬春陽節，草木已含英。","洛川當盛宴，斯焉爲達生。"]', '诗', 'shi', '', NULL, '送郗詹事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dffd275-e938-46a3-a4b9-005623b3fa2a', '送蘇評事', '送蘇評事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["季弟仕譙都，元兄坐蘭省。","言訪始忻忻，念離當耿耿。","嵯峨夏雲起，迢遰山川永。","登高望去塵，紛思終難整。"]', '["季弟仕譙都，元兄坐蘭省。","言訪始忻忻，念離當耿耿。","嵯峨夏云起，迢遰山川永。","登高望去塵，紛思終难整。"]', '诗', 'shi', '', NULL, '送蘇評事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25f71b36-8615-4900-9dc8-051bfdce8d3e', '送李侍御益赴幽州幕', '送李侍御益赴幽州幕', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["二十揮篇翰，三十窮典墳。","辟書五府至，名爲四海聞。","始從車騎幕，今赴嫖姚軍。","契闊晚相遇，草慼遽離羣。","悠悠行子遠，眇眇川途分。","登高望燕代，日夕生夏雲。","司徒擁精甲，誓將除國氛。","儒生幸持斧，可以佐功勳。","無言羽書急，坐闕相思文。"]', '["二十揮篇翰，三十窮典墳。","辟书五府至，名爲四海闻。","始從车騎幕，今赴嫖姚軍。","契闊晚相遇，草慼遽離羣。","悠悠行子远，眇眇川途分。","登高望燕代，日夕生夏云。","司徒擁精甲，誓將除国氛。","儒生幸持斧，可以佐功勳。","無言羽书急，坐闕相思文。"]', '诗', 'shi', '', NULL, '送李侍御益赴幽州幕 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('878f36d8-5f49-4a16-8e05-ffd2481f139b', '自尚書郎出爲滁州刺史', '自尚书郎出爲滁州刺史', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["少年不遠仕，秉笏東西京。","中歲守淮郡，奉命乃征行。","素慙省閣姿，況忝符竹榮。","効愚方此始，顧私豈獲幷。","徘徊親交戀，愴悢昆友情。","日暮風雪起，我去子還城。","登塗建隼旟，勒駕望承明。","雲臺煥中天，龍闕鬱上征。","晨興奉早朝，玉露霑華纓。","一朝從此去，服膺理庶甿。","皇恩儻歲月，歸服廁羣英。"]', '["少年不远仕，秉笏东西京。","中歲守淮郡，奉命乃征行。","素慙省閣姿，況忝符竹榮。","効愚方此始，顧私豈獲幷。","徘徊親交戀，愴悢昆友情。","日暮风雪起，我去子還城。","登塗建隼旟，勒駕望承明。","云台煥中天，龙闕鬱上征。","晨兴奉早朝，玉露霑华纓。","一朝從此去，服膺理庶甿。","皇恩儻歲月，归服廁羣英。"]', '诗', 'shi', '', NULL, '自尚書郎出爲滁州刺史 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11071f40-e192-4519-a90d-133bf4cbeabb', '送元錫楊凌', '送元錫楊凌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["荒林翳山郭，積水成秋晦。","端居意自違，況別親與愛。","歡筵慊未足，離燈悄已對。","還當掩郡閣，佇君方此會。"]', '["荒林翳山郭，積水成秋晦。","端居意自違，況別親與愛。","歡筵慊未足，離灯悄已对。","還當掩郡閣，佇君方此會。"]', '诗', 'shi', '', NULL, '送元錫楊凌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f800050a-d7a0-4f12-a614-17fe23df8f41', '送楊氏女', '送楊氏女', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["永日方慼慼，出門復悠悠。","女子今有行，大江泝輕舟。","爾輩況無恃，撫念益慈柔。","幼爲長所育，兩別泣不休。","對此結中腸，義往難復留。","自小闕內訓，事姑貽我憂。","賴茲託令門，仁恤庶無尤。","貧儉誠所尚，資從豈待周。","孝恭遵婦道，容止順其猷。","別離在今晨，見爾當何秋。","居閑始自遣，臨感忽難收。","歸來視幼女，零淚緣纓流。"]', '["永日方慼慼，出门复悠悠。","女子今有行，大江泝轻舟。","爾輩況無恃，撫念益慈柔。","幼爲长所育，兩別泣不休。","对此結中腸，義往难复留。","自小闕內訓，事姑貽我憂。","賴茲託令门，仁恤庶無尤。","貧儉誠所尚，資從豈待周。","孝恭遵婦道，容止順其猷。","別離在今晨，见爾當何秋。","居闲始自遣，臨感忽难收。","归来視幼女，零泪緣纓流。"]', '诗', 'shi', '', NULL, '送楊氏女 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527e9413-ac14-409b-a6f6-b2bb7d33a3e1', '送中弟', '送中弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秋風入疎戶，離人起晨朝。","山郡多風雨，西樓更蕭條。","嗟予淮海老，送子關河遙。","同來不同去，沈憂寧復消。"]', '["秋风入疎戶，離人起晨朝。","山郡多风雨，西楼更蕭條。","嗟予淮海老，送子关河遙。","同来不同去，沈憂寧复消。"]', '诗', 'shi', '', NULL, '送中弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256dd26f-9223-4e29-84bb-b1253886cb65', '寄別李儋', '寄別李儋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["首戴惠文冠，心有決勝籌。","翩翩四五騎，結束向幷州。","名在相公幕，丘山恩未酬。","妻子不及顧，親友安得留。","宿昔同文翰，交分共綢繆。","忽枉別離札，涕淚一交流。","遠郡臥殘疾，涼氣滿西樓。","想子臨長路，時當淮海秋。"]', '["首戴惠文冠，心有決勝籌。","翩翩四五騎，結束向幷州。","名在相公幕，丘山恩未酬。","妻子不及顧，親友安得留。","宿昔同文翰，交分共綢繆。","忽枉別離札，涕泪一交流。","远郡臥殘疾，涼氣满西楼。","想子臨长路，时當淮海秋。"]', '诗', 'shi', '', NULL, '寄別李儋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69758b16-d314-44a0-8c82-85309d6778f7', '送倉部蕭員外院長存', '送倉部蕭員外院长存', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["襆被蹉跎老江國，情人邂逅此相逢。","不隨鴛鷺朝天去，遙想蓬萊臺閣重。"]', '["襆被蹉跎老江国，情人邂逅此相逢。","不隨鴛鷺朝天去，遙想蓬萊台閣重。"]', '诗', 'shi', '', NULL, '送倉部蕭員外院長存 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f65d874a-316b-4c34-9fab-cc0eb6265d33', '送王校書', '送王校书', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["同宿高齋換時節，共看移石復栽杉。","送君江浦已惆悵，更上西樓看遠帆。"]', '["同宿高斋換时節，共看移石复栽杉。","送君江浦已惆悵，更上西楼看远帆。"]', '诗', 'shi', '', NULL, '送王校書 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74be64d3-9cc2-4de4-92ce-410e038a044c', '送丘員外還山', '送丘員外還山', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["長棲白雲表，蹔訪高齋宿。","還辭郡邑諠，歸泛松江淥。","結茅隱蒼嶺，伐薪響深谷。","同是山中人，不知往來躅。","靈芝非庭草，遼鶴委池鶩。","終當署里門，一表高陽族。"]', '["长棲白云表，蹔訪高斋宿。","還辞郡邑諠，归泛松江淥。","結茅隐蒼嶺，伐薪响深谷。","同是山中人，不知往来躅。","靈芝非庭草，遼鹤委池鶩。","終當署里门，一表高陽族。"]', '诗', 'shi', '', NULL, '送丘員外還山 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76214013-558f-49ff-ac2a-a988621405ce', '重送丘二十二還臨平山居', '重送丘二十二還臨平山居', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["歲中始再覯，方來又解攜。","纔留野艇語，已憶故山棲。","幽澗人夜汲，深林鳥長啼。","還持郡齋酒，慰子霜露淒。"]', '["歲中始再覯，方来又解携。","纔留野艇語，已憶故山棲。","幽澗人夜汲，深林鸟长啼。","還持郡斋酒，慰子霜露淒。"]', '诗', 'shi', '', NULL, '重送丘二十二還臨平山居 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec82071b-cfe0-4bb2-b814-a98d42c34c32', '送鄭端公弟移院常州', '送鄭端公弟移院常州', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["時瞻憲臣重，禮爲內兄全。","公程儻見責，私愛信不愆。","況昔陪朝列，今茲俱海壖。","清觴方對酌，天書忽告遷。","豈徒咫尺地，使我心思綿。","應當自此始，歸拜雲臺前。"]', '["时瞻憲臣重，禮爲內兄全。","公程儻见責，私愛信不愆。","況昔陪朝列，今茲俱海壖。","清觴方对酌，天书忽告遷。","豈徒咫尺地，使我心思綿。","應當自此始，归拜云台前。"]', '诗', 'shi', '', NULL, '送鄭端公弟移院常州 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87149227-342f-4959-9dd8-058e590e2169', '送房杭州', '送房杭州', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["專城未四十，暫謫豈蹉跎。","風雨吳門夜，惻愴別情多。"]', '["專城未四十，暫謫豈蹉跎。","风雨吳门夜，惻愴別情多。"]', '诗', 'shi', '', NULL, '送房杭州 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda4b0ab-0aba-4b42-8092-137a2aacf9df', '送陸侍御還越', '送陸侍御還越', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["居藩久不樂，遇子聊一欣。","英聲頗籍甚，交辟迺時珍。","繡衣過舊里，驄馬輝四鄰。","敬恭尊郡守，牋簡具州民。","謬忝誠所愧，思懷方見申。","置榻宿清夜，加籩醼良辰。","遵塗還盛府，行舫遶長津。","自有賢方伯，得此文翰賓。"]', '["居藩久不乐，遇子聊一欣。","英声頗籍甚，交辟迺时珍。","繡衣過旧里，驄马輝四鄰。","敬恭尊郡守，牋簡具州民。","謬忝誠所愧，思懷方见申。","置榻宿清夜，加籩醼良辰。","遵塗還盛府，行舫遶长津。","自有賢方伯，得此文翰賓。"]', '诗', 'shi', '', NULL, '送陸侍御還越 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f064a8c2-d27b-40d2-a5f9-55ec5afd55a1', '聽江笛送陸侍御', '听江笛送陸侍御', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遠聽江上笛，臨觴一送君。","還愁獨宿夜，更向郡齋聞。"]', '["远听江上笛，臨觴一送君。","還愁独宿夜，更向郡斋闻。"]', '诗', 'shi', '', NULL, '聽江笛送陸侍御 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a080dcfa-22cc-41e6-8378-1a1179a853e8', '送丘員外歸山居', '送丘員外归山居', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["郡閣始嘉宴，青山憶舊居。","爲君量革履，且願住藍轝。"]', '["郡閣始嘉宴，青山憶旧居。","爲君量革履，且願住藍轝。"]', '诗', 'shi', '', NULL, '送丘員外歸山居 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2f0faa-3a7f-4554-a338-a9addcf65180', '送崔叔清遊越', '送崔叔清游越', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["忘茲適越意，愛我郡齋幽。","野情豈好謁，詩興一相留。","遠水帶寒樹，閶門望去舟。","方伯憐文士，無爲成滯遊。"]', '["忘茲適越意，愛我郡斋幽。","野情豈好謁，诗兴一相留。","远水带寒樹，閶门望去舟。","方伯怜文士，無爲成滯游。"]', '诗', 'shi', '', NULL, '送崔叔清遊越 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c37681ff-4f6d-4098-a1a5-dd7b1808546a', '送雲陽鄒儒立少府侍奉還京師', '送云陽鄒儒立少府侍奉還京師', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["建中即藩守，天寶爲侍臣。","歷觀兩都士，多閱諸侯人。","鄒生乃後來，英俊亦罕倫。","爲文頗瓌麗，稟度自貞醇。","甲科推令名，延閣播芳塵。","再命趨王畿，請告奉慈親。","一鍾信榮祿，可以展歡欣。","昆弟俱時秀，長衢當自伸。","聊從郡閣暇，美此時景新。","方將極娛宴，已復及離晨。","省署慙再入，江海綿十春。","今日閶門路，握手子歸秦。"]', '["建中即藩守，天寶爲侍臣。","歷观兩都士，多閱諸侯人。","鄒生乃後来，英俊亦罕倫。","爲文頗瓌丽，稟度自貞醇。","甲科推令名，延閣播芳塵。","再命趨王畿，請告奉慈親。","一鍾信榮祿，可以展歡欣。","昆弟俱时秀，长衢當自伸。","聊從郡閣暇，美此时景新。","方將極娛宴，已复及離晨。","省署慙再入，江海綿十春。","今日閶门路，握手子归秦。"]', '诗', 'shi', '', NULL, '送雲陽鄒儒立少府侍奉還京師 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53977d89-ac24-472a-b263-e05375222bdc', '送豆盧策秀才', '送豆盧策秀才', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["歲交冰未泮，地卑海氣昏。","子有京師遊，始發吳閶門。","新黃含遠林，微綠生陳根。","詩人感時節，行道當憂煩。","古來濩落者，俱不事田園。","文如金石韻，豈乏知音言。","方辭郡齋榻，爲酌離亭罇。","無爲倦羈旅，一去高飛翻。"]', '["歲交冰未泮，地卑海氣昏。","子有京師游，始發吳閶门。","新黄含远林，微綠生陳根。","诗人感时節，行道當憂煩。","古来濩落者，俱不事田园。","文如金石韻，豈乏知音言。","方辞郡斋榻，爲酌離亭罇。","無爲倦羈旅，一去高飞翻。"]', '诗', 'shi', '', NULL, '送豆盧策秀才 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0a29119-bdbe-430c-abbc-bab4893d8f96', '送王卿', '送王卿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["別酌春林啼鳥稀，雙旌背日晚風吹。","却憶回來花已盡，東郊立馬望城池。"]', '["別酌春林啼鸟稀，雙旌背日晚风吹。","却憶回来花已尽，东郊立马望城池。"]', '诗', 'shi', '', NULL, '送王卿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24288aa4-a7b2-4e88-b4f2-55b59b376dff', '送劉評事', '送劉評事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["聲華滿京洛，藻翰發陽春。","未遂鵷鴻舉，尚爲江海賓。","吳中高宴罷，西上一遊秦。","已想函關道，遊子冒風塵。","籠禽羨歸翼，遠守懷交親。","況復歲云暮，凜凜冰霜辰。","旭霽開郡閣，寵餞集文人。","洞庭摘朱實，松江獻白鱗。","丈夫豈恨別，一酌且歡忻。"]', '["声华满京洛，藻翰發陽春。","未遂鵷鴻舉，尚爲江海賓。","吳中高宴罷，西上一游秦。","已想函关道，游子冒风塵。","籠禽羨归翼，远守懷交親。","況复歲云暮，凜凜冰霜辰。","旭霽开郡閣，寵餞集文人。","洞庭摘朱實，松江獻白鱗。","丈夫豈恨別，一酌且歡忻。"]', '诗', 'shi', '', NULL, '送劉評事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('341f804d-2536-4b3d-8db6-f9601994b9b1', '送雷監赴闕庭', '送雷監赴闕庭', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["才大無不備，出入爲時須。","雄藩精理行，祕府擢文儒。","詔書忽已至，焉得久踟躅。","方舟趂朝謁，觀者盈路衢。","廣筵列衆賓，送爵無停迂。","攀餞誠愴恨，賀榮且歡娛。","長陪柏梁宴，日向丹墀趨。","時方重右職，蹉跎獨海隅。"]', '["才大無不備，出入爲时須。","雄藩精理行，祕府擢文儒。","詔书忽已至，焉得久踟躅。","方舟趂朝謁，观者盈路衢。","廣筵列衆賓，送爵無停迂。","攀餞誠愴恨，賀榮且歡娛。","长陪柏梁宴，日向丹墀趨。","时方重右職，蹉跎独海隅。"]', '诗', 'shi', '', NULL, '送雷監赴闕庭 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec552279-91ec-4018-bfbb-d11abd1eaa53', '送秦系赴潤州', '送秦系赴潤州', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["近作新婚鑷白髯，長懷舊卷映藍衫。","更欲攜君虎丘寺，不知方伯望征帆。"]', '["近作新婚鑷白髯，长懷旧卷映藍衫。","更欲携君虎丘寺，不知方伯望征帆。"]', '诗', 'shi', '', NULL, '送秦系赴潤州 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944a28ec-3ced-4bd1-8145-bc4a526b9b8d', '送孫徵赴雲中', '送孫徵赴云中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["黃驄少年舞雙戟，目視傍人皆辟易。","百戰會誇隴上兒，一身復作雲中客。","寒風動地氣蒼芒，橫吹先悲出塞長。","敲石軍中傳夜火，斧冰河畔汲朝漿。","前鋒直指陰山外，虜騎紛紛翦應碎。","匈奴破盡看君歸，金印酬功如斗大。"]', '["黄驄少年舞雙戟，目視傍人皆辟易。","百戰會誇隴上兒，一身复作云中客。","寒风动地氣蒼芒，橫吹先悲出塞长。","敲石軍中傳夜火，斧冰河畔汲朝漿。","前鋒直指陰山外，虜騎紛紛翦應碎。","匈奴破尽看君归，金印酬功如斗大。"]', '诗', 'shi', '', NULL, '送孫徵赴雲中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e183b980-003b-43fa-8e3e-3443de151dca', '期盧嵩枉書稱日暮無馬不赴以詩答', '期盧嵩枉书稱日暮無马不赴以诗答', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["佳期不可失，終願枉衡門。","南陌人猶度，西林日未昏。","庭前空倚杖，花裏獨留罇。","莫道無來駕，知君有短轅。"]', '["佳期不可失，終願枉衡门。","南陌人猶度，西林日未昏。","庭前空倚杖，花裏独留罇。","莫道無来駕，知君有短轅。"]', '诗', 'shi', '', NULL, '期盧嵩枉書稱日暮無馬不赴以詩答 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4080ad-bdb7-42ed-b2bf-2d1d1dd40b78', '任洛陽丞答前長安田少府問', '任洛陽丞答前长安田少府问', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["相逢且對酒，相問欲何如。","數歲猶卑吏，家人笑著書。","告歸應未得，榮宦又知疎。","日日生春草，空令憶舊居。"]', '["相逢且对酒，相问欲何如。","數歲猶卑吏，家人笑著书。","告归應未得，榮宦又知疎。","日日生春草，空令憶旧居。"]', '诗', 'shi', '', NULL, '任洛陽丞答前長安田少府問 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6f667e6-dbf3-4565-9d3c-fe2a2c3857d9', '假中枉盧二十二書亦稱臥疾兼訝李二久不訪問以詩答書因亦戲李二', '假中枉盧二十二书亦稱臥疾兼訝李二久不訪问以诗答书因亦戲李二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["微官何事勞趨走，服藥閑眠養不才。","花裏棋盤憎鳥汙，枕邊書卷訝風開。","故人問訊緣同病，芳月相思阻一杯。","應笑王戎成俗物，遙持麈尾獨徘徊。"]', '["微官何事勞趨走，服藥闲眠養不才。","花裏棋盤憎鸟汙，枕邊书卷訝风开。","故人问訊緣同病，芳月相思阻一杯。","應笑王戎成俗物，遙持麈尾独徘徊。"]', '诗', 'shi', '', NULL, '假中枉盧二十二書亦稱臥疾兼訝李二久不訪問以詩答書因亦戲李二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7903b8d8-92bf-4a77-955f-858859783050', '酬盧嵩秋夜見寄五韻', '酬盧嵩秋夜见寄五韻', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["喬木生夜涼，月華滿前墀。","去君咫尺地，勞君千里思。","素秉棲遁志，況貽招隱詩。","坐見林木榮，願赴滄洲期。","何能待歲晏，攜手當此時。"]', '["喬木生夜涼，月华满前墀。","去君咫尺地，勞君千里思。","素秉棲遁志，況貽招隐诗。","坐见林木榮，願赴滄洲期。","何能待歲晏，携手當此时。"]', '诗', 'shi', '', NULL, '酬盧嵩秋夜見寄五韻 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c726c82-b094-4258-bdfc-12b27cf1a3c9', '酬鄭戶曹驪山感懷', '酬鄭戶曹驪山感懷', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["蒼山何鬱盤，飛閣凌上清。","先帝昔好道，下元朝百靈。","白雲已蕭條，麋鹿但縱橫。","泉水今尚煖，舊林亦青青。","我念綺襦歲，扈從當太平。","小臣職前驅，馳道出灞亭。","翻翻日月旗，殷殷鼙鼓聲。","萬馬自騰驤，八駿按轡行。","日出煙嶠綠，氛氳麗層甍。","登臨起遐想，沐浴懽聖情。","朝燕詠無事，時豐賀國禎。","日和絃管音，下使萬室聽。","海內湊朝貢，賢愚共歡榮。","合沓車馬喧，西聞長安城。","事往世如寄，感深迹所經。","申章報蘭藻，一望雙涕零。"]', '["蒼山何鬱盤，飞閣凌上清。","先帝昔好道，下元朝百靈。","白云已蕭條，麋鹿但縱橫。","泉水今尚煖，旧林亦青青。","我念綺襦歲，扈從當太平。","小臣職前驱，驰道出灞亭。","翻翻日月旗，殷殷鼙鼓声。","万马自腾驤，八駿按轡行。","日出煙嶠綠，氛氳丽層甍。","登臨起遐想，沐浴懽聖情。","朝燕詠無事，时豐賀国禎。","日和絃管音，下使万室听。","海內湊朝貢，賢愚共歡榮。","合沓车马喧，西闻长安城。","事往世如寄，感深迹所經。","申章報蘭藻，一望雙涕零。"]', '诗', 'shi', '', NULL, '酬鄭戶曹驪山感懷 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('771bbf2f-d2c9-4f35-ad0c-88316209ff40', '答李澣三首 一', '答李澣三首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["孤客逢春暮，緘情寄舊遊。","海隅人使遠，書到洛陽秋。"]', '["孤客逢春暮，緘情寄旧游。","海隅人使远，书到洛陽秋。"]', '诗', 'shi', '', NULL, '答李澣三首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4736d323-1659-4795-bed4-39fb2f67c084', '答李澣三首 二', '答李澣三首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["馬卿猶有壁，漁父自無家。","想子今何處，扁舟隱荻花。"]', '["马卿猶有壁，漁父自無家。","想子今何处，扁舟隐荻花。"]', '诗', 'shi', '', NULL, '答李澣三首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('464481b2-d920-4137-80ec-4abcc16d3698', '答李澣三首 三', '答李澣三首 三', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["林中觀易罷，溪上對鷗閑。","楚俗饒辭客，何人最往還。"]', '["林中观易罷，溪上对鷗闲。","楚俗饒辞客，何人最往還。"]', '诗', 'shi', '', NULL, '答李澣三首 三 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ada2e6e4-3731-4b83-9f0c-3ade61fbad0c', '酬柳郎中春日歸揚州南郭見別之作', '酬柳郎中春日归揚州南郭见別之作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["廣陵三月花正開，花裏逢君醉一廻。","南北相過殊不遠，暮潮從去早潮來。"]', '["廣陵三月花正开，花裏逢君醉一廻。","南北相過殊不远，暮潮從去早潮来。"]', '诗', 'shi', '', NULL, '酬柳郎中春日歸揚州南郭見別之作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27df5f17-664c-4d3a-829d-a90c868d7264', '酬豆盧倉曹題庫壁見示', '酬豆盧倉曹題庫壁见示', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["掾局勞才子，新詩動洛川。","運籌知決勝，聚米似論邊。","宴罷常分騎，晨趨又比肩。","莫嗟年鬢改，郎署定推先。"]', '["掾局勞才子，新诗动洛川。","運籌知決勝，聚米似論邊。","宴罷常分騎，晨趨又比肩。","莫嗟年鬢改，郎署定推先。"]', '诗', 'shi', '', NULL, '酬豆盧倉曹題庫壁見示 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1ef593a-1a40-4189-9a5a-878b01b33d67', '酬李儋', '酬李儋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["開門臨廣陌，旭旦車駕喧。","不見同心友，徘徊憂且煩。","都城二十里，居在艮與坤。","人生所各務，乖闊累朝昏。","湛湛罇中酒，青青芳樹園。","緘情未及發，先此枉璵璠。","邁世超高躅，尋流得真源。","明當策疲馬，與子同笑言。"]', '["开门臨廣陌，旭旦车駕喧。","不见同心友，徘徊憂且煩。","都城二十里，居在艮與坤。","人生所各務，乖闊累朝昏。","湛湛罇中酒，青青芳樹园。","緘情未及發，先此枉璵璠。","邁世超高躅，尋流得真源。","明當策疲马，與子同笑言。"]', '诗', 'shi', '', NULL, '酬李儋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef4e505-6345-47ee-92ae-25fff6ea32c1', '酬元偉過洛陽夜燕', '酬元偉過洛陽夜燕', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["三載寄關東，所懽皆遠違。","思懷方耿耿，忽得觀容輝。","親燕在良夜，歡攜闢中闈。","問我猶杜門，不能奮高飛。","明燈照四隅，炎炭正可依。","清觴雖云酌，所媿乏珍肥。","晨裝復當行，寥落星已稀。","何以慰心曲，佇子西還歸。"]', '["三載寄关东，所懽皆远違。","思懷方耿耿，忽得观容輝。","親燕在良夜，歡携闢中闈。","问我猶杜门，不能奮高飞。","明灯照四隅，炎炭正可依。","清觴雖云酌，所媿乏珍肥。","晨裝复當行，寥落星已稀。","何以慰心曲，佇子西還归。"]', '诗', 'shi', '', NULL, '酬元偉過洛陽夜燕 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac178252-f128-4e72-8401-eb9543f380bd', '酬韓質舟行阻凍', '酬韓質舟行阻凍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晨坐枉嘉藻，持此慰寢興。","中獲辛苦奏，長河結陰冰。","皓曜羣玉發，淒清孤景凝。","至柔反成堅，造化安可恆。","方舟未得行，鑿飲空兢兢。","寒苦彌時節，待泮豈所能。","何必涉廣川，荒衢且升騰。","殷勤宣中意，庶用達吾朋。"]', '["晨坐枉嘉藻，持此慰寢兴。","中獲辛苦奏，长河結陰冰。","皓曜羣玉發，淒清孤景凝。","至柔反成堅，造化安可恆。","方舟未得行，鑿饮空兢兢。","寒苦彌时節，待泮豈所能。","何必涉廣川，荒衢且升腾。","殷勤宣中意，庶用達吾朋。"]', '诗', 'shi', '', NULL, '酬韓質舟行阻凍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3821b830-dbd9-489b-8e78-6c6fb0f0ba82', '李博士弟以余罷官居同德精舍共有伊陸名山之期久而未去枉詩見問中云宋生昔登覽未云那能顧蓬蓽直寄鄙懷聊以爲答', '李博士弟以余罷官居同德精舍共有伊陸名山之期久而未去枉诗见问中云宋生昔登覽未云那能顧蓬蓽直寄鄙懷聊以爲答', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["初夏息衆緣，雙林對禪客。","枉茲芳蘭藻，促我幽人策。","冥搜企前哲，逸句陳往迹。","髣髴陸渾南，迢遞千峰碧。","從來遲高駕，自顧無物役。","山水心所娛，如何更朝夕。","晨興涉清洛，訪子高陽宅。","莫言往來疎，駑馬知阡陌。"]', '["初夏息衆緣，雙林对禪客。","枉茲芳蘭藻，促我幽人策。","冥搜企前哲，逸句陳往迹。","髣髴陸渾南，迢遞千峰碧。","從来遲高駕，自顧無物役。","山水心所娛，如何更朝夕。","晨兴涉清洛，訪子高陽宅。","莫言往来疎，駑马知阡陌。"]', '诗', 'shi', '', NULL, '李博士弟以余罷官居同德精舍共有伊陸名山之期久而未去枉詩見問中云宋生昔登覽未云那能顧蓬蓽直寄鄙懷聊以爲答 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26488cf1-994f-4a08-bee7-754c45299cf3', '寄酬李博士永寧主簿叔廳見待', '寄酬李博士永寧主簿叔廳见待', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["解鞍先幾日，款曲見新詩。","定向公堂醉，遙憐獨去時。","葉霑寒雨落，鐘度遠山遲。","晨策已云整，當同林下期。"]', '["解鞍先幾日，款曲见新诗。","定向公堂醉，遙怜独去时。","葉霑寒雨落，鐘度远山遲。","晨策已云整，當同林下期。"]', '诗', 'shi', '', NULL, '寄酬李博士永寧主簿叔廳見待 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3031b70-afde-4fba-bb06-2fd5de9bd9c5', '荅令狐士曹獨孤兵曹聯騎暮歸望山見寄', '荅令狐士曹独孤兵曹聯騎暮归望山见寄', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["共愛青山住近南，行牽吏役背雙驂。","枉書獨宿對流水，遙羨歸時滿夕嵐。"]', '["共愛青山住近南，行牽吏役背雙驂。","枉书独宿对流水，遙羨归时满夕嵐。"]', '诗', 'shi', '', NULL, '荅令狐士曹獨孤兵曹聯騎暮歸望山見寄 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd60de7-b504-4b65-9f43-831766d41c82', '荅李博士', '荅李博士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["休沐去人遠，高齋出林杪。","晴山多碧峰，顥氣疑秋曉。","端居喜良友，枉使千里路。","緘書當夏時，開緘時已度。","簷雛已颻颺，荷露方蕭颯。","夢遠竹窗幽，行稀蘭徑合。","舊居共南北，往來只如昨。","問君今爲誰，日夕度清洛。"]', '["休沐去人远，高斋出林杪。","晴山多碧峰，顥氣疑秋晓。","端居喜良友，枉使千里路。","緘书當夏时，开緘时已度。","簷雛已颻颺，荷露方蕭颯。","梦远竹窗幽，行稀蘭徑合。","旧居共南北，往来只如昨。","问君今爲誰，日夕度清洛。"]', '诗', 'shi', '', NULL, '荅李博士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be33ce3-fafa-44f9-bb62-381a73cf26ba', '荅劉西曹', '荅劉西曹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["公館夜云寂，微涼羣樹秋。","西曹得時彥，華月共淹留。","長嘯舉清觴，志氣誰與儔。","千齡事雖邈，俯念忽已周。","篇翰如雲興，京洛頗優游。","詮文不獨古，理妙即同流。","淺劣見推許，恐爲識者尤。","空慙文璧贈，日夕不能酬。"]', '["公館夜云寂，微涼羣樹秋。","西曹得时彥，华月共淹留。","长嘯舉清觴，志氣誰與儔。","千齡事雖邈，俯念忽已周。","篇翰如云兴，京洛頗優游。","詮文不独古，理妙即同流。","淺劣见推許，恐爲識者尤。","空慙文璧贈，日夕不能酬。"]', '诗', 'shi', '', NULL, '荅劉西曹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b242d0-ed07-4658-8c21-94a5b9df3c4a', '荅貢士黎逢', '荅貢士黎逢', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["茂等方上達，諸生安可希。","栖神澹物表，渙汗布令詞。","如彼崑山玉，本自有光輝。","鄙人徒區區，稱歎亦何爲。","彌月曠不接，公門但驅馳。","蘭章忽有贈，持用慰所思。","不見心尚密，況當相見時。"]', '["茂等方上達，諸生安可希。","栖神澹物表，渙汗布令词。","如彼崑山玉，本自有光輝。","鄙人徒區區，稱歎亦何爲。","彌月曠不接，公门但驱驰。","蘭章忽有贈，持用慰所思。","不见心尚密，況當相见时。"]', '诗', 'shi', '', NULL, '荅貢士黎逢 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3cd2565-025e-43e9-977a-8f3fc1caccf9', '答韓庫部', '答韓庫部', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["良玉表貞度，麗藻頗爲工。","名列金閨籍，心與素士同。","日晏下朝來，車馬自生風。","清宵有佳興，皓月直南宮。","矯翮方上征，顧我邈忡忡。","豈不願攀舉，執事府庭中。","智乖時亦蹇，才大命有通。","還當以道推，解組守蒿蓬。"]', '["良玉表貞度，丽藻頗爲工。","名列金閨籍，心與素士同。","日晏下朝来，车马自生风。","清宵有佳兴，皓月直南宮。","矯翮方上征，顧我邈忡忡。","豈不願攀舉，執事府庭中。","智乖时亦蹇，才大命有通。","還當以道推，解組守蒿蓬。"]', '诗', 'shi', '', NULL, '答韓庫部 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5eb903-96d8-4524-841d-041dc410d301', '荅崔主簿倬', '荅崔主簿倬', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["朗月分林靄，遙管動離聲。","故驩良已阻，空宇澹無情。","窈窕雲雁沒，蒼茫河漢橫。","蘭草不可荅，沖襟徒自盈。"]', '["朗月分林靄，遙管动離声。","故驩良已阻，空宇澹無情。","窈窕云雁沒，蒼茫河漢橫。","蘭草不可荅，沖襟徒自盈。"]', '诗', 'shi', '', NULL, '荅崔主簿倬 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('215db3c1-14c1-4a25-b696-647b3bd114ee', '荅徐秀才', '荅徐秀才', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鉛鈍謝貞器，時秀猥見稱。","豈如白玉仙，方與紫霞升。","清詩舞豔雪，孤抱瑩玄冰。","一枝非所貴，懷書思武陵。"]', '["鉛鈍謝貞器，时秀猥见稱。","豈如白玉仙，方與紫霞升。","清诗舞豔雪，孤抱瑩玄冰。","一枝非所貴，懷书思武陵。"]', '诗', 'shi', '', NULL, '荅徐秀才 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e52142f8-32c3-4844-9586-173428734494', '荅東林道士', '荅东林道士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["紫閣西邊第幾峰，茅齋夜雪虎行蹤。","遙看黛色知何處，欲出山門尋暮鐘。"]', '["紫閣西邊第幾峰，茅斋夜雪虎行蹤。","遙看黛色知何处，欲出山门尋暮鐘。"]', '诗', 'shi', '', NULL, '荅東林道士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78b22e6c-43ed-4896-866d-1c09adb76cfb', '荅長寧令楊轍', '荅长寧令楊轍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["皓月升林表，公堂滿清輝。","嘉賓自遠至，觴飲夜何其。","宰邑視京縣，歸來無寸資。","瓌文溢衆寶，雅正得吾師。","廣川含澄瀾，茂樹擢華滋。","短才何足數，枉贈媿妍詞。","歡盼良見屬，素懷亦已披。","何意雲棲翰，不嫌蓬艾卑。","但恐河漢沒，回車首路岐。"]', '["皓月升林表，公堂满清輝。","嘉賓自远至，觴饮夜何其。","宰邑視京縣，归来無寸資。","瓌文溢衆寶，雅正得吾師。","廣川含澄瀾，茂樹擢华滋。","短才何足數，枉贈媿妍词。","歡盼良见屬，素懷亦已披。","何意云棲翰，不嫌蓬艾卑。","但恐河漢沒，回车首路岐。"]', '诗', 'shi', '', NULL, '荅長寧令楊轍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9b3bdf-3a13-4a53-80b3-79db38baa63e', '荅馮魯秀才', '荅馮魯秀才', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晨坐枉瓊藻，知子返中林。","澹然山景晏，泉谷響幽禽。","髣髴謝塵跡，逍遙舒道心。","顧我腰間綬，端爲華髮侵。","簿書勞應對，篇翰曠不尋。","薄田失鋤耨，生苗安可任。","徒令慙所問，想望東山岑。"]', '["晨坐枉瓊藻，知子返中林。","澹然山景晏，泉谷响幽禽。","髣髴謝塵跡，逍遙舒道心。","顧我腰间綬，端爲华髮侵。","簿书勞應对，篇翰曠不尋。","薄田失鋤耨，生苗安可任。","徒令慙所问，想望东山岑。"]', '诗', 'shi', '', NULL, '荅馮魯秀才 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('259a141b-a49b-48de-b42d-b9e48b4293b0', '荅崔主簿問兼簡溫上人', '荅崔主簿问兼簡溫上人', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["緣情生衆累，晚悟依道流。","諸境一已寂，了將身世浮。","閑居澹無味，忽復四時周。","靡靡芳草積，稍稍新篁抽。","即此抱餘素，塊然誠寡儔。","自適一忻意，愧蒙君子憂。"]', '["緣情生衆累，晚悟依道流。","諸境一已寂，了將身世浮。","闲居澹無味，忽复四时周。","靡靡芳草積，稍稍新篁抽。","即此抱餘素，塊然誠寡儔。","自適一忻意，愧蒙君子憂。"]', '诗', 'shi', '', NULL, '荅崔主簿問兼簡溫上人 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b13cbd3-192d-498c-b0f2-b74ce33b51eb', '清都觀荅幼遐', '清都观荅幼遐', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["逍遙仙家子，日夕朝玉皇。","興高清露沒，渴飲瓊華漿。","解組一來款，披衣拂天香。","粲然顧我笑，綠簡發新章。","泠泠如玉音，馥馥若蘭芳。","浩意坐盈此，月華殊未央。","却念諠譁日，何由得清涼。","疎松抗高殿，密竹陰長廊。","榮名等糞土，攜手隨風翔。"]', '["逍遙仙家子，日夕朝玉皇。","兴高清露沒，渴饮瓊华漿。","解組一来款，披衣拂天香。","粲然顧我笑，綠簡發新章。","泠泠如玉音，馥馥若蘭芳。","浩意坐盈此，月华殊未央。","却念諠譁日，何由得清涼。","疎松抗高殿，密竹陰长廊。","榮名等糞土，携手隨风翔。"]', '诗', 'shi', '', NULL, '清都觀荅幼遐 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8871bec-db52-46d1-a273-dab7a92facb6', '善福精舍荅韓司錄清都觀會宴見憶', '善福精舍荅韓司錄清都观會宴见憶', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["弱志厭衆紛，抱素寄精廬。","皦皦仰時彥，悶悶獨爲愚。","之子亦辭秩，高蹤罷馳驅。","忽因西飛禽，贈我以瓊琚。","始表仙都集，復言歡樂殊。","人生各有因，契闊不獲俱。","一來田野中，日與人事疎。","水木澄秋景，逍遙清賞餘。","枉駕懷前諾，引領豈斯須。","無爲便高翔，邈矣不可迂。"]', '["弱志厭衆紛，抱素寄精廬。","皦皦仰时彥，悶悶独爲愚。","之子亦辞秩，高蹤罷驰驱。","忽因西飞禽，贈我以瓊琚。","始表仙都集，复言歡乐殊。","人生各有因，契闊不獲俱。","一来田野中，日與人事疎。","水木澄秋景，逍遙清賞餘。","枉駕懷前諾，引領豈斯須。","無爲便高翔，邈矣不可迂。"]', '诗', 'shi', '', NULL, '善福精舍荅韓司錄清都觀會宴見憶 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ded4bd-f117-4093-8688-11e7c941584d', '荅長安丞裴說', '荅长安丞裴说', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["出身忝時士，於世本無機。","爰以林壑趣，遂成頑鈍姿。","臨流意已淒，采菊露未稀。","舉頭見秋山，萬事都若遺。","獨踐幽人蹤，邈將親友違。","髦士佐京邑，懷念枉貞詞。","久雨積幽抱，清罇宴良知。","從容操劇務，文翰方見推。","安能戢羽翼，顧此林栖時。"]', '["出身忝时士，於世本無機。","爰以林壑趣，遂成頑鈍姿。","臨流意已淒，采菊露未稀。","舉头见秋山，万事都若遺。","独踐幽人蹤，邈將親友違。","髦士佐京邑，懷念枉貞词。","久雨積幽抱，清罇宴良知。","從容操劇務，文翰方见推。","安能戢羽翼，顧此林栖时。"]', '诗', 'shi', '', NULL, '荅長安丞裴說 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5538a5de-fd0f-49ec-9874-f5ce4bc6d4f3', '奉酬處士叔見示', '奉酬处士叔见示', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["挂纓守貧賤，積雪臥郊園。","叔父親降趾，壺觴攜到門。","高齋樂宴罷，清夜道心存。","即此同疎氏，可以一忘言。"]', '["挂纓守貧賤，積雪臥郊园。","叔父親降趾，壺觴携到门。","高斋乐宴罷，清夜道心存。","即此同疎氏，可以一忘言。"]', '诗', 'shi', '', NULL, '奉酬處士叔見示 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebfdfb31-da55-4dff-85a4-f77dbb7c463d', '荅庫部韓郎中', '荅庫部韓郎中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高士不羈世，頗將榮辱齊。","適委華冕去，欲還幽林栖。","雖懷承明戀，忻與物累暌。","逍遙觀運流，誰復職端倪。","而我豈高致，偃息平門西。","愚者世所遺，沮溺共耕犂。","風雪積深夜，園田掩荒蹊。","幸蒙相思札，款曲期見攜。"]', '["高士不羈世，頗將榮辱齊。","適委华冕去，欲還幽林栖。","雖懷承明戀，忻與物累暌。","逍遙观運流，誰复職端倪。","而我豈高致，偃息平门西。","愚者世所遺，沮溺共耕犂。","风雪積深夜，园田掩荒蹊。","幸蒙相思札，款曲期见携。"]', '诗', 'shi', '', NULL, '荅庫部韓郎中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('985cec73-e2e6-4e53-8537-4b9062faecd4', '荅暢校書當', '荅暢校书當', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["偶然棄官去，投跡在田中。","日出照茅屋，園林養愚蒙。","雖云無一資，罇酌會不空。","且忻百穀成，仰嘆造化功。","出入與民伍，作事靡不同。","時伐南澗竹，夜還灃水東。","貧蹇自成退，豈爲高人蹤。","覽君金玉篇，彩色發我容。","日月欲爲報，方春已徂冬。"]', '["偶然棄官去，投跡在田中。","日出照茅屋，园林養愚蒙。","雖云無一資，罇酌會不空。","且忻百穀成，仰嘆造化功。","出入與民伍，作事靡不同。","时伐南澗竹，夜還灃水东。","貧蹇自成退，豈爲高人蹤。","覽君金玉篇，彩色發我容。","日月欲爲報，方春已徂冬。"]', '诗', 'shi', '', NULL, '荅暢校書當 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb371632-bded-4588-b79b-85c1ce20a66d', '荅崔都水', '荅崔都水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["深夜竹亭雪，孤燈案上書。","不遇無爲化，誰復得閒居。"]', '["深夜竹亭雪，孤灯案上书。","不遇無爲化，誰复得閒居。"]', '诗', 'shi', '', NULL, '荅崔都水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1935ba54-4c61-4c59-a93c-342a2739f4be', '酬令狐司錄善福精舍見贈', '酬令狐司錄善福精舍见贈', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["野寺望山雪，空齋對竹林。","我以養愚地，生君道者心。"]', '["野寺望山雪，空斋对竹林。","我以養愚地，生君道者心。"]', '诗', 'shi', '', NULL, '酬令狐司錄善福精舍見贈 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85cca48b-b0fd-4138-b418-4abcc54cf059', '灃上精舍荅趙氏外生伉', '灃上精舍荅趙氏外生伉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遠跡出塵表，寓身雙樹林。","如何小子伉，亦有超世心。","擔書從我遊，攜手廣川陰。","雲開夏郊綠，景晏青山沈。","對榻遇清夜，獻詩合雅音。","所推苟禮數，於性道豈深。","隱拙在沖默，經世昧古今。","無爲率爾言，可以致華簪。"]', '["远跡出塵表，寓身雙樹林。","如何小子伉，亦有超世心。","擔书從我游，携手廣川陰。","云开夏郊綠，景晏青山沈。","对榻遇清夜，獻诗合雅音。","所推苟禮數，於性道豈深。","隐拙在沖默，經世昧古今。","無爲率爾言，可以致华簪。"]', '诗', 'shi', '', NULL, '灃上精舍荅趙氏外生伉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4441ab65-d881-4dbd-9373-e74cabefada0', '荅趙氏生伉', '荅趙氏生伉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["暫與雲林別，忽陪鴛鷺翔。","看山不得去，知爾獨相望。"]', '["暫與云林別，忽陪鴛鷺翔。","看山不得去，知爾独相望。"]', '诗', 'shi', '', NULL, '荅趙氏生伉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8658fafb-4052-4470-a0bf-fd33ecfa5b19', '荅端', '荅端', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["郊園夏雨歇，閑院綠陰生。","職事方無効，幽賞獨違情。","物色坐如見，離抱悵多盈。","況感夕涼氣，聞此亂蟬鳴。"]', '["郊园夏雨歇，闲院綠陰生。","職事方無効，幽賞独違情。","物色坐如见，離抱悵多盈。","況感夕涼氣，闻此亂蟬鳴。"]', '诗', 'shi', '', NULL, '荅端 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f857d1f6-f37c-4a5f-8ef6-a0ad7c18bb40', '答史館張學士段柳庶子學士集賢院看花見寄兼呈柳學士', '答史館張学士段柳庶子学士集賢院看花见寄兼呈柳学士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["班楊秉文史，對院自爲鄰。","餘香掩閣去，遲日看花頻。","似雪飄閶闔，從風點近臣。","南宮有芳樹，不竝禁垣春。"]', '["班楊秉文史，对院自爲鄰。","餘香掩閣去，遲日看花頻。","似雪飄閶闔，從风点近臣。","南宮有芳樹，不竝禁垣春。"]', '诗', 'shi', '', NULL, '答史館張學士段柳庶子學士集賢院看花見寄兼呈柳學士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6be3940-625e-46ff-a41f-85b4a1224c59', '荅王郎中', '荅王郎中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["臥閣枉芳藻，覽旨悵秋晨。","守郡猶羈寓，無以慰嘉賓。","野曠歸雲盡，天清曉露新。","池荷涼已至，牕梧落漸頻。","風物殊京國，邑里但荒榛。","賦繁屬軍興，政拙媿斯人。","髦士久臺閣，中路一漂淪。","歸當列盛朝，豈念臥淮濱。"]', '["臥閣枉芳藻，覽旨悵秋晨。","守郡猶羈寓，無以慰嘉賓。","野曠归云尽，天清晓露新。","池荷涼已至，牕梧落漸頻。","风物殊京国，邑里但荒榛。","賦繁屬軍兴，政拙媿斯人。","髦士久台閣，中路一漂淪。","归當列盛朝，豈念臥淮濱。"]', '诗', 'shi', '', NULL, '荅王郎中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf024e4-019c-4f23-a353-f66b09ee9a71', '荅崔都水', '荅崔都水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["亭亭心中人，迢迢居秦關。","常緘素札去，適枉華章還。","憶在灃郊時，攜手望秋山。","久嫌官府勞，初喜罷秩閑。","終年不事業，寢食長慵頑。","不知爲時來，名籍挂郎間。","攝衣辭田里，華簪耀頹顏。","卜居又依仁，日夕正追攀。","牧人本無術，命至苟復遷。","離念積歲序，歸途眇山川。","郡齋有佳月，園林含清泉。","同心不在宴，罇酒徒盈前。","覽君陳迹遊，詞意俱悽妍。","忽忽已終日，將詶不能宣。","甿稅況重疊，公門極熬煎。","責逋甘首免，歲晏當歸田。","勿厭守窮轍，慎爲名所牽。"]', '["亭亭心中人，迢迢居秦关。","常緘素札去，適枉华章還。","憶在灃郊时，携手望秋山。","久嫌官府勞，初喜罷秩闲。","終年不事業，寢食长慵頑。","不知爲时来，名籍挂郎间。","攝衣辞田里，华簪耀頹顏。","卜居又依仁，日夕正追攀。","牧人本無術，命至苟复遷。","離念積歲序，归途眇山川。","郡斋有佳月，园林含清泉。","同心不在宴，罇酒徒盈前。","覽君陳迹游，词意俱悽妍。","忽忽已終日，將詶不能宣。","甿稅況重叠，公门極熬煎。","責逋甘首免，歲晏當归田。","勿厭守窮轍，慎爲名所牽。"]', '诗', 'shi', '', NULL, '荅崔都水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd77939c-160a-4e39-b1b8-9eda59edac02', '荅王卿送別', '荅王卿送別', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["去馬嘶春草，歸人立夕陽。","元知數日別，要使兩情傷。"]', '["去马嘶春草，归人立夕陽。","元知數日別，要使兩情傷。"]', '诗', 'shi', '', NULL, '荅王卿送別 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bb8d209-bc18-45e3-a830-de8f2bb280a9', '荅裴丞說歸京所獻', '荅裴丞说归京所獻', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["執事頗勤久，行去亦傷乖。","家貧無僮僕，吏卒升寢齋。","衣服藏內篋，藥草曝前階。","誰復知次第，濩落且安排。","還期在歲晏，何以慰吾懷。"]', '["執事頗勤久，行去亦傷乖。","家貧無僮僕，吏卒升寢斋。","衣服藏內篋，藥草曝前階。","誰复知次第，濩落且安排。","還期在歲晏，何以慰吾懷。"]', '诗', 'shi', '', NULL, '荅裴丞說歸京所獻 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe7871be-193b-403d-aad0-28f45382a706', '答裴處士', '答裴处士', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遺民愛精舍，乘犢入青山。","來署高陽里，不遇白衣還。","禮賢方化俗，聞風自款關。","況子逸羣士，栖息蓬蒿間。"]', '["遺民愛精舍，乘犢入青山。","来署高陽里，不遇白衣還。","禮賢方化俗，闻风自款关。","況子逸羣士，栖息蓬蒿间。"]', '诗', 'shi', '', NULL, '答裴處士 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a71baa5-b301-49a9-bde3-e2f8d58d4f7f', '荅楊奉禮', '荅楊奉禮', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["多病守山郡，自得接嘉賓。","不見三四日，曠若十餘旬。","臨觴獨無味，對榻已生塵。","一詠舟中作，灑雪忽驚新。","煙波見棲旅，景物具昭陳。","秋塘唯落葉，野寺不逢人。","白事廷吏簡，閑居文墨親。","高天池閣靜，寒菊霜露頻。","應當整孤棹，歸來展殷勤。"]', '["多病守山郡，自得接嘉賓。","不见三四日，曠若十餘旬。","臨觴独無味，对榻已生塵。","一詠舟中作，灑雪忽驚新。","煙波见棲旅，景物具昭陳。","秋塘唯落葉，野寺不逢人。","白事廷吏簡，闲居文墨親。","高天池閣静，寒菊霜露頻。","應當整孤棹，归来展殷勤。"]', '诗', 'shi', '', NULL, '荅楊奉禮 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c02f23-7c33-4add-a393-76973740b247', '答端', '答端', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["坐憶故園人已老，寧知遠郡雁還來。","長瞻西北是歸路，獨上城樓日幾廻。"]', '["坐憶故园人已老，寧知远郡雁還来。","长瞻西北是归路，独上城楼日幾廻。"]', '诗', 'shi', '', NULL, '答端 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc9a12e5-1eac-43fb-b7d0-1c63bbe73ab5', '答僴奴重陽二甥', '答僴奴重陽二甥', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["棄職曾守拙，翫幽遂忘喧。","山澗依磽𥕂，竹樹蔭清源。","貧居煙火濕，歲熟梨棗繁。","風雨飄茅屋，蒿草沒瓜園。","羣屬相歡悅，不覺過朝昏。","有時看禾黍，落日上秋原。","飲酒任真性，揮筆肆狂言。","一朝忝蘭省，三載居遠藩。","復與諸弟子，篇翰每相敦。","西園休習射，南池對芳樽。","山藥經雨碧，海榴凌霜飜。","念爾不同此，悵然復一論。","重陽守故家，僴子旅湘沅。","俱有緘中藻，惻惻動離魂。","不知何日見，衣上淚空存。"]', '["棄職曾守拙，翫幽遂忘喧。","山澗依磽𥕂，竹樹蔭清源。","貧居煙火濕，歲熟梨棗繁。","风雨飄茅屋，蒿草沒瓜园。","羣屬相歡悅，不覺過朝昏。","有时看禾黍，落日上秋原。","饮酒任真性，揮笔肆狂言。","一朝忝蘭省，三載居远藩。","复與諸弟子，篇翰每相敦。","西园休習射，南池对芳樽。","山藥經雨碧，海榴凌霜飜。","念爾不同此，悵然复一論。","重陽守故家，僴子旅湘沅。","俱有緘中藻，惻惻动離魂。","不知何日见，衣上泪空存。"]', '诗', 'shi', '', NULL, '答僴奴重陽二甥 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78c70a9-0564-4e80-ad88-b90367a3a3a7', '荅重陽', '荅重陽', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["省札陳往事，愴憶數年中。","一身朝北闕，家累守田農。","望山亦臨水，暇日每來同。","性情一疎散，園林多清風。","忽復隔淮海，夢想在灃東。","病來經時節，起見秋塘空。","城郭連榛嶺，鳥雀噪溝叢。","坐使驚霜鬢，撩亂已如蓬。"]', '["省札陳往事，愴憶數年中。","一身朝北闕，家累守田農。","望山亦臨水，暇日每来同。","性情一疎散，园林多清风。","忽复隔淮海，梦想在灃东。","病来經时節，起见秋塘空。","城郭連榛嶺，鸟雀噪溝叢。","坐使驚霜鬢，撩亂已如蓬。"]', '诗', 'shi', '', NULL, '荅重陽 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c58ce66-5ac2-43c0-9fc7-0aaeb70233f4', '酬劉侍郎使君', '酬劉侍郎使君', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["瓊樹凌霜雪，葱蒨如芳春。","英賢雖出守，本自玉階人。","宿昔陪郎署，出入仰清塵。","孰云俱列郡，比德豈爲鄰。","風雨飄海氣，清涼悅心神。","重門深夏晝，賦詩延衆賓。","方以歲月舊，每蒙君子親。","繼作郡齋什，遠贈荆山珍。","高閑庶務理，遊眺景物新。","朋友亦遠集，燕酌在佳辰。","始唱已慙拙，將酬益難伸。","濡毫意僶俛，一用寫悁勤。"]', '["瓊樹凌霜雪，葱蒨如芳春。","英賢雖出守，本自玉階人。","宿昔陪郎署，出入仰清塵。","孰云俱列郡，比德豈爲鄰。","风雨飄海氣，清涼悅心神。","重门深夏晝，賦诗延衆賓。","方以歲月旧，每蒙君子親。","繼作郡斋什，远贈荆山珍。","高闲庶務理，游眺景物新。","朋友亦远集，燕酌在佳辰。","始唱已慙拙，將酬益难伸。","濡毫意僶俛，一用寫悁勤。"]', '诗', 'shi', '', NULL, '酬劉侍郎使君 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c7f892-832a-48cc-a422-d92193ee965c', '答令狐侍郎', '答令狐侍郎', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一凶廼一吉，一是復一非。","孰能逃斯理，亮在識其微。","三黜故無慍，高賢當庶幾。","但以親交戀，音容邈難希。","況昔別離久，俱忻藩守歸。","朝宴方陪廁，山川又乖違。","吳門冒海霧，峽路凌連磯。","同會在京國，相望涕沾衣。","明時重英才，當復列彤闈。","白玉雖塵垢，拂拭還光輝。"]', '["一凶廼一吉，一是复一非。","孰能逃斯理，亮在識其微。","三黜故無慍，高賢當庶幾。","但以親交戀，音容邈难希。","況昔別離久，俱忻藩守归。","朝宴方陪廁，山川又乖違。","吳门冒海霧，峽路凌連磯。","同會在京国，相望涕沾衣。","明时重英才，當复列彤闈。","白玉雖塵垢，拂拭還光輝。"]', '诗', 'shi', '', NULL, '答令狐侍郎 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbbb6458-ed8f-487b-b1e4-7004ceb16664', '酬張協律', '酬張協律', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["昔人鬻舂地，今人復一賢。","屬余藩守日，方君臥病年。","麗思阻文宴，芳蹤闕賓筵。","經時豈不懷，欲往事屢牽。","公府適煩倦，開緘瑩新篇。","非將握中寶，何以比其妍。","感茲棲寓詞，想復痾瘵纏。","空宇風霜交，幽居情思綿。","當以貧非病，孰云白未玄。","邑中有其人，憔倅即我愆。","由來牧守重，英俊得薦延。","匪人等鴻毛，斯道何由宣。","遭時無早晚，蘊器俟良緣。","觀文心未衰，勿藥疾當痊。","晨期簡牘罷，馳慰子忡然。"]', '["昔人鬻舂地，今人复一賢。","屬余藩守日，方君臥病年。","丽思阻文宴，芳蹤闕賓筵。","經时豈不懷，欲往事屢牽。","公府適煩倦，开緘瑩新篇。","非將握中寶，何以比其妍。","感茲棲寓词，想复痾瘵纏。","空宇风霜交，幽居情思綿。","當以貧非病，孰云白未玄。","邑中有其人，憔倅即我愆。","由来牧守重，英俊得薦延。","匪人等鴻毛，斯道何由宣。","遭时無早晚，蘊器俟良緣。","观文心未衰，勿藥疾當痊。","晨期簡牘罷，驰慰子忡然。"]', '诗', 'shi', '', NULL, '酬張協律 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a4cedc-8d1a-4e65-a56d-d2c860170b47', '荅秦十四校書', '荅秦十四校书', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["知掩山扉三十秋，魚須翠碧棄牀頭。","莫道謝公方在郡，五言今日爲君休。"]', '["知掩山扉三十秋，鱼須翠碧棄牀头。","莫道謝公方在郡，五言今日爲君休。"]', '诗', 'shi', '', NULL, '荅秦十四校書 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56fd4e5-6626-4929-a750-c5effd4ee24f', '答賓', '答賓', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["斜月纔鑒帷，凝霜偏冷枕。","持情須耿耿，故作單牀寢。"]', '["斜月纔鑒帷，凝霜偏冷枕。","持情須耿耿，故作單牀寢。"]', '诗', 'shi', '', NULL, '答賓 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bf0ded8-eead-4432-a0f4-02e8a016a916', '答鄭騎曹青橘絕句', '答鄭騎曹青橘絕句', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["憐君臥病思新橘，試摘猶酸亦未黃。","書後欲題三百顆，洞庭須待滿林霜。"]', '["怜君臥病思新橘，試摘猶酸亦未黄。","书後欲題三百顆，洞庭須待满林霜。"]', '诗', 'shi', '', NULL, '答鄭騎曹青橘絕句 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff790ee-593a-4159-94ea-4cb9b1268053', '奉和聖製重陽日賜宴', '奉和聖製重陽日賜宴', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["聖心憂萬國，端居在穆清。","玄功致海[晏]，錫讌表文明。","恩屬重陽節，雨應此時晴。","寒菊生池苑，高樹出宮城。","捧藻千官處，垂戒百王程。","復覩開元日，臣愚獻頌聲。"]', '["聖心憂万国，端居在穆清。","玄功致海[晏]，錫讌表文明。","恩屬重陽節，雨應此时晴。","寒菊生池苑，高樹出宮城。","捧藻千官处，垂戒百王程。","复覩开元日，臣愚獻頌声。"]', '诗', 'shi', '', NULL, '奉和聖製重陽日賜宴 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd1c24e-24ab-4e22-aeae-c57006fb686d', '和吳舍人早春歸沐西亭言志', '和吳舍人早春归沐西亭言志', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["曉漏戒中禁，清香肅朝衣。","一門雙掌誥，伯侍仲言歸。","亭高性情曠，職密交遊稀。","賦詩樂無事，解帶偃南扉。","陽春美時澤，旭霽望山暉。","幽禽響未轉，東原綠猶微。","名雖列僊爵，心已遣塵機。","即事同巖隱，聖渥良難違。"]', '["晓漏戒中禁，清香肅朝衣。","一门雙掌誥，伯侍仲言归。","亭高性情曠，職密交游稀。","賦诗乐無事，解带偃南扉。","陽春美时澤，旭霽望山暉。","幽禽响未轉，东原綠猶微。","名雖列僊爵，心已遣塵機。","即事同巖隐，聖渥良难違。"]', '诗', 'shi', '', NULL, '和吳舍人早春歸沐西亭言志 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be19f42-dc52-4568-a481-71b06b3698d8', '奉和張大夫戲示青山郎', '奉和張大夫戲示青山郎', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["天生逸世姿，竹馬不曾騎。","覽卷冰將釋，援毫露欲垂。","金貂傳幾葉，玉樹長新枝。","榮祿何妨早，甘羅亦小兒。"]', '["天生逸世姿，竹马不曾騎。","覽卷冰將釋，援毫露欲垂。","金貂傳幾葉，玉樹长新枝。","榮祿何妨早，甘羅亦小兒。"]', '诗', 'shi', '', NULL, '奉和張大夫戲示青山郎 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f054775c-a53a-41cf-a84d-7bc8512e86a5', '答河南李士巽題香山寺', '答河南李士巽題香山寺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["洛都遊宦日，少年攜手行。","投杯起芳席，總轡振華纓。","關塞有佳氣，巖開伊水清。","攀林憩佛寺，登高望都城。","蹉跎二十載，世務各所營。","茲賞長在夢，故人安得幷。","前歲守九江，恩詔赴咸京。","因塗再登歷，山河屬晴明。","寂寞僧侶少，蒼茫林木成。","牆宇或崩剝，不見舊題名。","舊遊況存歿，獨此淚交橫。","交橫誰與同，書壁貽友生。","今茲守吳郡，綿思方未平。","子復經陳迹，一感我深情。","遠蒙惻愴篇，中有金玉聲。","反覆終難答，金玉尚爲輕。"]', '["洛都游宦日，少年携手行。","投杯起芳席，總轡振华纓。","关塞有佳氣，巖开伊水清。","攀林憩佛寺，登高望都城。","蹉跎二十載，世務各所營。","茲賞长在梦，故人安得幷。","前歲守九江，恩詔赴咸京。","因塗再登歷，山河屬晴明。","寂寞僧侶少，蒼茫林木成。","牆宇或崩剝，不见旧題名。","旧游況存歿，独此泪交橫。","交橫誰與同，书壁貽友生。","今茲守吳郡，綿思方未平。","子复經陳迹，一感我深情。","远蒙惻愴篇，中有金玉声。","反覆終难答，金玉尚爲轻。"]', '诗', 'shi', '', NULL, '答河南李士巽題香山寺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5881aabb-0474-441a-9e3d-4a02066332b5', '答故人見諭', '答故人见諭', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["素寡名利心，自非周圓器。","徒以歲月資，屢蒙藩條寄。","時風重書札，物情敦貨遺。","機杼十縑單，慵疎百函愧。","常負交親責，且爲一官累。","況本濩落人，歸無置錐地。","省己已知非，枉書見深致。","雖欲效區區，何由枉其志。"]', '["素寡名利心，自非周圓器。","徒以歲月資，屢蒙藩條寄。","时风重书札，物情敦貨遺。","機杼十縑單，慵疎百函愧。","常負交親責，且爲一官累。","況本濩落人，归無置錐地。","省己已知非，枉书见深致。","雖欲效區區，何由枉其志。"]', '诗', 'shi', '', NULL, '答故人見諭 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9523181c-d141-4550-845a-09ed9616ef26', '酬閻員外陟', '酬閻員外陟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["寒夜阻良覿，叢竹想幽居。","虎符[予]已誤，金丹子何如。","讌集觀農暇，笙歌聽訟餘。","雖蒙一言教，自愧道情疎。"]', '["寒夜阻良覿，叢竹想幽居。","虎符[予]已誤，金丹子何如。","讌集观農暇，笙歌听訟餘。","雖蒙一言教，自愧道情疎。"]', '诗', 'shi', '', NULL, '酬閻員外陟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed16a128-a7dc-4797-bc73-271e30e1d8d0', '酬秦徵君徐少府春日見寄', '酬秦徵君徐少府春日见寄', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["終日愧無政，與君聊散襟。","城根山半腹，亭影水中心。","朗詠竹牕靜，野情花逕深。","那能有餘興，不作剡溪尋。"]', '["終日愧無政，與君聊散襟。","城根山半腹，亭影水中心。","朗詠竹牕静，野情花逕深。","那能有餘兴，不作剡溪尋。"]', '诗', 'shi', '', NULL, '酬秦徵君徐少府春日見寄 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d170f81a-a576-430d-b179-56b1a8b8b5ec', '冬夜宿司空曙野居因寄酬贈', '冬夜宿司空曙野居因寄酬贈', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["南北與山鄰，蓬庵庇一身。","繁霜疑有雪，荒草似無人。","遂性在耕稼，所交唯賤貧。","何掾張椽傲，每重德璋親。"]', '["南北與山鄰，蓬庵庇一身。","繁霜疑有雪，荒草似無人。","遂性在耕稼，所交唯賤貧。","何掾張椽傲，每重德璋親。"]', '诗', 'shi', '', NULL, '冬夜宿司空曙野居因寄酬贈 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ae44b3-ba8d-42d3-85a7-a70aa8608379', '長安遇馮著', '长安遇馮著', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["客從東方來，衣上灞陵雨。","問客何爲來，采山因買斧。","冥冥花正開，颺颺燕新乳。","昨別今已春，鬢絲生幾縷。"]', '["客從东方来，衣上灞陵雨。","问客何爲来，采山因買斧。","冥冥花正开，颺颺燕新乳。","昨別今已春，鬢絲生幾縷。"]', '诗', 'shi', '', NULL, '長安遇馮著 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b30084e-e8b8-44a4-8a2f-82a233246c22', '將發楚州經寶應縣訪李二忽於州館相遇月夜書事因簡李寶應', '將發楚州經寶應縣訪李二忽於州館相遇月夜书事因簡李寶應', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["孤舟欲夜發，祗爲訪情人。","此地忽相遇，留連意更新。","停杯嗟別久，對月言家貧。","一問臨邛令，如何待上賓。"]', '["孤舟欲夜發，祗爲訪情人。","此地忽相遇，留連意更新。","停杯嗟別久，对月言家貧。","一问臨邛令，如何待上賓。"]', '诗', 'shi', '', NULL, '將發楚州經寶應縣訪李二忽於州館相遇月夜書事因簡李寶應 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c532ca-b3a3-4ec9-ba5e-6fed23c1b8cd', '廣陵遇孟九雲卿', '廣陵遇孟九云卿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雄藩本帝都，遊士多俊賢。","夾河樹鬱鬱，華館千里連。","新知雖滿堂，中意頗未宣。","忽逢翰林友，歡樂斗酒前。","高文激頹波，四海靡不傳。","西施且一笑，衆女安得妍。","明月滿淮海，哀鴻逝長天。","所念京國遠，我來君欲還。"]', '["雄藩本帝都，游士多俊賢。","夾河樹鬱鬱，华館千里連。","新知雖满堂，中意頗未宣。","忽逢翰林友，歡乐斗酒前。","高文激頹波，四海靡不傳。","西施且一笑，衆女安得妍。","明月满淮海，哀鴻逝长天。","所念京国远，我来君欲還。"]', '诗', 'shi', '', NULL, '廣陵遇孟九雲卿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540559c4-5be0-42ee-adfc-1e409af2728f', '淮上遇洛陽李主簿', '淮上遇洛陽李主簿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["結茅臨古渡，臥見長淮流。","窗裏人將老，門前樹已秋。","寒山獨過雁，暮雨遠來舟。","日夕逢歸客，那能忘舊遊。"]', '["結茅臨古渡，臥见长淮流。","窗裏人將老，门前樹已秋。","寒山独過雁，暮雨远来舟。","日夕逢归客，那能忘旧游。"]', '诗', 'shi', '', NULL, '淮上遇洛陽李主簿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d8f6f1-a652-4bc1-b03f-364e8442170b', '路逢崔元二侍御避馬見招以詩見贈', '路逢崔元二侍御避马见招以诗见贈', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一臺稱二妙，歸路望行塵。","俱是攀龍客，空爲避馬人。","見招翻跼蹐，相問良殷勤。","日日吟趨府，彈冠豈有因。"]', '["一台稱二妙，归路望行塵。","俱是攀龙客，空爲避马人。","见招翻跼蹐，相问良殷勤。","日日吟趨府，彈冠豈有因。"]', '诗', 'shi', '', NULL, '路逢崔元二侍御避馬見招以詩見贈 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ade3c28-5e17-4a15-b3d3-f11c3387e4e7', '逢楊開府', '逢楊开府', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["少事武皇帝，無賴恃恩私。","身作里中橫，家藏亡命兒。","朝持樗蒲局，暮竊東鄰姬。","司隸不敢捕，立在白玉墀。","驪山風雪夜，長楊羽獵時。","一字都不識，飲酒肆頑癡。","武皇升仙去，憔悴被人欺。","讀書事已晚，把筆學題詩。","兩府始收跡，南宮謬見推。","非才果不容，出守撫惸嫠。","忽逢楊開府，論舊涕俱垂。","坐客何由識，惟有故人知。"]', '["少事武皇帝，無賴恃恩私。","身作里中橫，家藏亡命兒。","朝持樗蒲局，暮竊东鄰姬。","司隸不敢捕，立在白玉墀。","驪山风雪夜，长楊羽獵时。","一字都不識，饮酒肆頑癡。","武皇升仙去，憔悴被人欺。","读书事已晚，把笔学題诗。","兩府始收跡，南宮謬见推。","非才果不容，出守撫惸嫠。","忽逢楊开府，論旧涕俱垂。","坐客何由識，惟有故人知。"]', '诗', 'shi', '', NULL, '逢楊開府 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e05ab52a-1d72-4de5-8637-2d2119952375', '休暇日訪王侍御不遇', '休暇日訪王侍御不遇', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["九日驅馳一日閑，尋君不遇又空還。","怪來詩思清人骨，門對寒流雪滿山。"]', '["九日驱驰一日闲，尋君不遇又空還。","怪来诗思清人骨，门对寒流雪满山。"]', '诗', 'shi', '', NULL, '休暇日訪王侍御不遇 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6743f5d8-d939-489f-a735-e48e2a98230b', '因省風俗訪道士姪不見題壁', '因省风俗訪道士姪不见題壁', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["去年澗水今亦流，去年杏花今又拆。","山人歸來問是誰，還是去年行春客。"]', '["去年澗水今亦流，去年杏花今又拆。","山人归来问是誰，還是去年行春客。"]', '诗', 'shi', '', NULL, '因省風俗訪道士姪不見題壁 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ff955d-ecbb-4082-8893-58b710d28809', '有所思', '有所思', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["借問堤上柳，青青爲誰春。","空遊昨日地，不見昨日人。","繚繞萬家井，往來車馬塵。","莫道無相識，要非心所親。"]', '["借问堤上柳，青青爲誰春。","空游昨日地，不见昨日人。","繚繞万家井，往来车马塵。","莫道無相識，要非心所親。"]', '诗', 'shi', '', NULL, '有所思 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a93092-6174-4ab1-9ba5-ec5b7fdbf7ec', '暮相思', '暮相思', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["朝出自不還，暮歸花盡發。","豈無終日會，惜此花間月。","空館忽相思，微鐘坐來歇。"]', '["朝出自不還，暮归花尽發。","豈無終日會，惜此花间月。","空館忽相思，微鐘坐来歇。"]', '诗', 'shi', '', NULL, '暮相思 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb4f76a6-5150-45c9-9266-b49b2f44d15b', '夏夜憶盧嵩', '夏夜憶盧嵩', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["靄靄高館暮，開軒滌煩襟。","不知湘雨來，瀟灑在幽林。","炎月得涼夜，芳樽誰與斟。","故人南北居，累月間徽音。","人生無閑日，歡會當在今。","反側候天旦，層城苦沈沈。"]', '["靄靄高館暮，开軒滌煩襟。","不知湘雨来，瀟灑在幽林。","炎月得涼夜，芳樽誰與斟。","故人南北居，累月间徽音。","人生無闲日，歡會當在今。","反側候天旦，層城苦沈沈。"]', '诗', 'shi', '', NULL, '夏夜憶盧嵩 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d931b83-a688-4c13-8179-eb7026c792ba', '春思', '春思', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["野花如雪繞江城，坐見年芳憶帝京。","閶闔曉開凝碧樹，曾陪鴛鷺聽流鶯。"]', '["野花如雪繞江城，坐见年芳憶帝京。","閶闔晓开凝碧樹，曾陪鴛鷺听流鶯。"]', '诗', 'shi', '', NULL, '春思 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55166723-0b1a-439e-a7ca-0ebf4207c401', '春中憶元二', '春中憶元二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雨歇萬井春，柔條已含緑。","徘徊洛陽陌，惆悵杜陵曲。","遊絲正高下，啼鳥還斷續。","有酒今不同，思君瑩如玉。"]', '["雨歇万井春，柔條已含緑。","徘徊洛陽陌，惆悵杜陵曲。","游絲正高下，啼鸟還斷續。","有酒今不同，思君瑩如玉。"]', '诗', 'shi', '', NULL, '春中憶元二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cc60243-6e9d-4466-ac08-c8fa58756676', '懷素友子西', '懷素友子西', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["廣陌竝遊騎，公堂接華襟。","方歡遽見別，永日獨沈吟。","階暝流暗駛，氣疎露已侵。","層城湛深夜，片月生幽林。","往款良未遂，來覿曠無音。","恆當清觴宴，思子玉山岑。","耿耿何以寫，密言空委心。"]', '["廣陌竝游騎，公堂接华襟。","方歡遽见別，永日独沈吟。","階暝流暗駛，氣疎露已侵。","層城湛深夜，片月生幽林。","往款良未遂，来覿曠無音。","恆當清觴宴，思子玉山岑。","耿耿何以寫，密言空委心。"]', '诗', 'shi', '', NULL, '懷素友子西 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d439dc72-e979-4ca3-a6b8-514b8b0b0be7', '對韓少尹所贈硯有懷', '对韓少尹所贈硯有懷', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["故人謫遐遠，留硯寵斯文。","白水浮香墨，清池滿夏雲。","念離心已永，感物思徒紛。","未有桂陽使，裁書一報君。"]', '["故人謫遐远，留硯寵斯文。","白水浮香墨，清池满夏云。","念離心已永，感物思徒紛。","未有桂陽使，裁书一報君。"]', '诗', 'shi', '', NULL, '對韓少尹所贈硯有懷 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d630fa1-1b1b-4417-8dab-ba7000623bfa', '月晦憶去年與親友曲水遊讌', '月晦憶去年與親友曲水游讌', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晦賞念前歲，京國結良儔。","騎出宣平里，飲對曲池流。","今朝隔天末，空園傷獨遊。","雨歇林光變，塘緑鳥聲幽。","凋甿積逋稅，華鬢集新秋。","誰言戀虎符，終當還舊丘。"]', '["晦賞念前歲，京国結良儔。","騎出宣平里，饮对曲池流。","今朝隔天末，空园傷独游。","雨歇林光变，塘緑鸟声幽。","凋甿積逋稅，华鬢集新秋。","誰言戀虎符，終當還旧丘。"]', '诗', 'shi', '', NULL, '月晦憶去年與親友曲水遊讌 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1bb6051-4abe-4ecb-8eee-78661873e42d', '清明日憶諸弟', '清明日憶諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["冷食方多病，開襟一忻然。","終令思故郡，煙火滿晴川。","杏粥猶堪食，榆羹已稍煎。","唯恨乖親燕，坐度此芳年。"]', '["冷食方多病，开襟一忻然。","終令思故郡，煙火满晴川。","杏粥猶堪食，榆羹已稍煎。","唯恨乖親燕，坐度此芳年。"]', '诗', 'shi', '', NULL, '清明日憶諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2470747c-cea0-4400-bf4b-a86c91c36825', '池上懷王卿', '池上懷王卿', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["幽居捐世事，佳雨散園芳。","入門靄已緑，水禽鳴春塘。","重雲始成夕，忽霽尚殘陽。","輕舟因風泛，郡閣望蒼蒼。","私燕阻外好，臨歡一停觴。","茲遊無時盡，旭日願相將。"]', '["幽居捐世事，佳雨散园芳。","入门靄已緑，水禽鳴春塘。","重云始成夕，忽霽尚殘陽。","轻舟因风泛，郡閣望蒼蒼。","私燕阻外好，臨歡一停觴。","茲游無时尽，旭日願相將。"]', '诗', 'shi', '', NULL, '池上懷王卿 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf080b73-083d-44da-9a15-8d6825f67ca4', '立夏日憶京師諸弟', '立夏日憶京師諸弟', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["改序念芳辰，煩襟倦日永。","夏木已成陰，公門晝恆靜。","長風始飄閣，疊雲纔吐嶺。","坐想離居人，還當惜徂景。"]', '["改序念芳辰，煩襟倦日永。","夏木已成陰，公门晝恆静。","长风始飄閣，叠云纔吐嶺。","坐想離居人，還當惜徂景。"]', '诗', 'shi', '', NULL, '立夏日憶京師諸弟 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('803c6b6d-d87e-4db2-8a72-43cdc11c63a3', '曉至園中憶諸弟崔都水', '晓至园中憶諸弟崔都水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山郭恆悄悄，林月亦娟娟。","景清神已澄，事簡慮絕牽。","秋塘徧衰草，曉露洗紅蓮。","不見心所愛，茲賞豈爲妍。"]', '["山郭恆悄悄，林月亦娟娟。","景清神已澄，事簡慮絕牽。","秋塘徧衰草，晓露洗紅蓮。","不见心所愛，茲賞豈爲妍。"]', '诗', 'shi', '', NULL, '曉至園中憶諸弟崔都水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d0ad700-6de7-4b62-944a-7093762ce2d3', '懷瑯琊深標二釋子', '懷瑯琊深標二釋子', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["白雲埋大壑，陰崖滴夜泉。","應居西石室，月照山蒼然。"]', '["白云埋大壑，陰崖滴夜泉。","應居西石室，月照山蒼然。"]', '诗', 'shi', '', NULL, '懷瑯琊深標二釋子 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94eb2668-bdc3-4233-9f57-024577ea25bc', '雨夜感懷', '雨夜感懷', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["微雨灑高林，塵埃自蕭散。","耿耿心未平，沈沈夜方半。","獨驚長簟冷，遽覺愁鬢換。","誰能當此夕，不有盈襟歎。"]', '["微雨灑高林，塵埃自蕭散。","耿耿心未平，沈沈夜方半。","独驚长簟冷，遽覺愁鬢換。","誰能當此夕，不有盈襟歎。"]', '诗', 'shi', '', NULL, '雨夜感懷 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27835d80-c1fd-4459-987c-4d490aa97370', '雲陽館懷谷口', '云陽館懷谷口', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["清泚階下流，云自谷口源。","念昔白衣士，結廬在石門。","道高杳無累，景靜得忘言。","山夕綠陰滿，世移清賞存。","吏役豈遑暇，幽懷復朝昏。","雲泉非所濯，蘿月不可援。","長往遂真性，暫遊恨卑喧。","出身既事世，高躅難等論。"]', '["清泚階下流，云自谷口源。","念昔白衣士，結廬在石门。","道高杳無累，景静得忘言。","山夕綠陰满，世移清賞存。","吏役豈遑暇，幽懷复朝昏。","云泉非所濯，蘿月不可援。","长往遂真性，暫游恨卑喧。","出身既事世，高躅难等論。"]', '诗', 'shi', '', NULL, '雲陽館懷谷口 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e77e1d4-d8f0-4b71-a115-52b099922a69', '憶灃上幽居', '憶灃上幽居', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一來當復去，猶此厭樊籠。","況我林栖子，朝服坐南宮。","唯獨問啼鳥，還如灃水東。"]', '["一来當复去，猶此厭樊籠。","況我林栖子，朝服坐南宮。","唯独问啼鸟，還如灃水东。"]', '诗', 'shi', '', NULL, '憶灃上幽居 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70376567-a76a-4843-bd94-918e120f4274', '重九登滁城樓憶前歲九日歸灃上赴崔都水及諸弟讌集悽然懷舊', '重九登滁城楼憶前歲九日归灃上赴崔都水及諸弟讌集悽然懷旧', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["今日重九讌，去歲在京師。","聊廻出省步，一赴郊園期。","嘉節始云邁，周辰已及茲。","秋山滿清景，當賞屬乖離。","凋散民里闊，摧翳衆木衰。","樓中一長嘯，惻愴起涼颸。"]', '["今日重九讌，去歲在京師。","聊廻出省步，一赴郊园期。","嘉節始云邁，周辰已及茲。","秋山满清景，當賞屬乖離。","凋散民里闊，摧翳衆木衰。","楼中一长嘯，惻愴起涼颸。"]', '诗', 'shi', '', NULL, '重九登滁城樓憶前歲九日歸灃上赴崔都水及諸弟讌集悽然懷舊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3e1589-dd63-42b7-9c3a-6f7021a5a6e0', '始夏南園思舊里', '始夏南园思旧里', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夏首雲物變，雨餘草木繁。","池荷初帖水，林花已掃園。","縈叢蝶尚亂，依閣鳥猶喧。","對此殘芳月，憶在漢陵原。"]', '["夏首云物变，雨餘草木繁。","池荷初帖水，林花已掃园。","縈叢蝶尚亂，依閣鸟猶喧。","对此殘芳月，憶在漢陵原。"]', '诗', 'shi', '', NULL, '始夏南園思舊里 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c458581-b581-4091-8b33-f4328cbfe77a', '登蒲塘驛沿路見泉谷邨墅忽想京師舊居追懷昔年', '登蒲塘驛沿路见泉谷邨墅忽想京師旧居追懷昔年', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["青山導騎遶，春風行斾舒。","均徭視屬城，問疾躬里閭。","煙水依泉谷，川陸散樵漁。","忽念故園日，復憶驪山居。","荏苒斑鬢及，夢寢婚宦初。","不覺平生事，咄嗟二紀餘。","存歿闊已永，悲多歡自疎。","高秩非爲美，闌干淚盈裾。"]', '["青山導騎遶，春风行斾舒。","均徭視屬城，问疾躬里閭。","煙水依泉谷，川陸散樵漁。","忽念故园日，复憶驪山居。","荏苒斑鬢及，梦寢婚宦初。","不覺平生事，咄嗟二紀餘。","存歿闊已永，悲多歡自疎。","高秩非爲美，闌干泪盈裾。"]', '诗', 'shi', '', NULL, '登蒲塘驛沿路見泉谷邨墅忽想京師舊居追懷昔年 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f5f13a5-457e-4f6f-8632-dc3f9084d444', '經函谷關', '經函谷关', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["洪河絕山根，單軌出其側。","萬古爲要樞，往來何時息。","秦皇即恃險，海內被吞食。","及嗣同覆顛，咽喉莫能塞。","炎靈詎西駕，婁子非經國。","徒欲扼諸侯，不知恢至德。","聖朝及天寶，豺虎起東北。","下沈戰死魂，上結窮冤色。","古今雖共守，成敗良可識。","藩屏無俊賢，金湯獨何力。","[馳]車一登眺，感慨中自惻。"]', '["洪河絕山根，單軌出其側。","万古爲要樞，往来何时息。","秦皇即恃險，海內被吞食。","及嗣同覆顛，咽喉莫能塞。","炎靈詎西駕，婁子非經国。","徒欲扼諸侯，不知恢至德。","聖朝及天寶，豺虎起东北。","下沈戰死魂，上結窮冤色。","古今雖共守，成敗良可識。","藩屏無俊賢，金湯独何力。","[驰]车一登眺，感慨中自惻。"]', '诗', 'shi', '', NULL, '經函谷關 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ddc157-c7e1-4db6-8105-e446db952408', '經武功舊宅', '經武功旧宅', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["茲邑昔所遊，嘉會常在目。","歷載俄二九，始往今來復。","慼慼居人少，茫茫野田綠。","風雨經舊墟，毀垣迷往躅。","門臨川流駛，樹有羇雌宿。","多累恆悲往，長年覺時速。","欲去中復留，徘徊結心曲。"]', '["茲邑昔所游，嘉會常在目。","歷載俄二九，始往今来复。","慼慼居人少，茫茫野田綠。","风雨經旧墟，毀垣迷往躅。","门臨川流駛，樹有羇雌宿。","多累恆悲往，长年覺时速。","欲去中复留，徘徊結心曲。"]', '诗', 'shi', '', NULL, '經武功舊宅 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e279de3-f4f4-4332-8d44-293a756fbf6c', '往雲門郊居塗經廻流作', '往云门郊居塗經廻流作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["茲晨乃休暇，適往田家廬。","原谷徑塗澀，春陽草木敷。","纔遵板橋曲，復此清澗紆。","崩壑方見射，廻流忽已舒。","明滅泛孤景，杳靄含夕虛。","無將爲邑志，一酌澄波餘。"]', '["茲晨乃休暇，適往田家廬。","原谷徑塗澀，春陽草木敷。","纔遵板橋曲，复此清澗紆。","崩壑方见射，廻流忽已舒。","明滅泛孤景，杳靄含夕虛。","無將爲邑志，一酌澄波餘。"]', '诗', 'shi', '', NULL, '往雲門郊居塗經廻流作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f13975d-017d-4852-b0c8-bbd3253db811', '乘月過西郊渡', '乘月過西郊渡', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["遠山含紫氛，春野靄云暮。","值此歸時月，留連西澗渡。","謬當文墨會，得與羣英遇。","賞逐亂流翻，心將清景悟。","行車儼未轉，芳草空盈步。","已舉候亭火，猶愛村原樹。","還當守故扃，悵恨秉幽素。"]', '["远山含紫氛，春野靄云暮。","值此归时月，留連西澗渡。","謬當文墨會，得與羣英遇。","賞逐亂流翻，心將清景悟。","行车儼未轉，芳草空盈步。","已舉候亭火，猶愛村原樹。","還當守故扃，悵恨秉幽素。"]', '诗', 'shi', '', NULL, '乘月過西郊渡 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489dc6c0-12d8-4fac-aaca-7d2cf80e6788', '晚歸灃川', '晚归灃川', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["凌霧朝閶闔，落日返清川。","簪組方暫解，臨水一翛然。","昆弟忻來集，童稚滿眼前。","適意在無事，攜手望秋田。","南嶺橫爽氣，高林繞遙阡。","野廬不鋤理，翳翳起荒煙。","名秩斯逾分，廉退媿不全。","已想平門路，晨騎復言旋。"]', '["凌霧朝閶闔，落日返清川。","簪組方暫解，臨水一翛然。","昆弟忻来集，童稚满眼前。","適意在無事，携手望秋田。","南嶺橫爽氣，高林繞遙阡。","野廬不鋤理，翳翳起荒煙。","名秩斯逾分，廉退媿不全。","已想平门路，晨騎复言旋。"]', '诗', 'shi', '', NULL, '晚歸灃川 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e63342d-fded-4f63-8ec3-e5d27b8d1518', '授衣還田里', '授衣還田里', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["公門懸甲令，澣濯遂其私。","晨起懷愴恨，野田寒露時。","氣收天地廣，風淒草木衰。","山明始重疊，川淺更逶迤。","煙火生閭里，禾黍積東菑。","終然可樂業，時節一來斯。"]', '["公门懸甲令，澣濯遂其私。","晨起懷愴恨，野田寒露时。","氣收天地廣，风淒草木衰。","山明始重叠，川淺更逶迤。","煙火生閭里，禾黍積东菑。","終然可乐業，时節一来斯。"]', '诗', 'shi', '', NULL, '授衣還田里 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11424603-9a22-4564-89a4-95e1766f9685', '夕次盱眙縣', '夕次盱眙縣', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["落帆逗淮鎮，停舫臨孤驛。","浩浩風起波，冥冥日沈夕。","人歸山郭暗，雁下蘆洲白。","獨夜憶秦關，聽鐘未眠客。"]', '["落帆逗淮鎮，停舫臨孤驛。","浩浩风起波，冥冥日沈夕。","人归山郭暗，雁下蘆洲白。","独夜憶秦关，听鐘未眠客。"]', '诗', 'shi', '', NULL, '夕次盱眙縣 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43df1a55-ad97-4ce0-b258-2d72bedded72', '春月觀省屬城始憩東西林精舍', '春月观省屬城始憩东西林精舍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["因時省風俗，布惠迨高年。","建隼出潯陽，整駕遊山川。","白雲斂晴壑，羣峰列遙天。","嶔㟢石門狀，杳靄香爐烟。","榛荒屢罥罣，偪側殆覆顛。","方臻釋氏廬，時物屢華妍。","曇遠昔經始，於茲閟幽玄。","東西竹林寺，灌注寒澗泉。","人事即云泯，歲月復已綿。","殿宇餘丹紺，磴閣峭欹懸。","佳士亦棲息，善身絕塵緣。","今我蒙朝寄，教化敷里鄽。","道妙茍爲得，出處理無偏。","心當同所尚，跡豈辭纏牽。"]', '["因时省风俗，布惠迨高年。","建隼出潯陽，整駕游山川。","白云斂晴壑，羣峰列遙天。","嶔㟢石门狀，杳靄香爐烟。","榛荒屢罥罣，偪側殆覆顛。","方臻釋氏廬，时物屢华妍。","曇远昔經始，於茲閟幽玄。","东西竹林寺，灌注寒澗泉。","人事即云泯，歲月复已綿。","殿宇餘丹紺，磴閣峭欹懸。","佳士亦棲息，善身絕塵緣。","今我蒙朝寄，教化敷里鄽。","道妙茍爲得，出处理無偏。","心當同所尚，跡豈辞纏牽。"]', '诗', 'shi', '', NULL, '春月觀省屬城始憩東西林精舍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('826e6955-873f-463b-81a5-0bfe87c4fe72', '自蒲塘驛廻駕經歷山水', '自蒲塘驛廻駕經歷山水', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["館宿風雨滯，始晴行蓋轉。","潯陽山水多，草木俱紛衍。","崎嶇緣碧澗，蒼翠踐苔蘚。","高樹夾潺湲，崩石橫陰巘。","野杏依寒拆，餘雲冒嵐淺。","性愜形豈勞，境殊路遺緬。","憶昔終南下，佳遊亦屢展。","時禽下流暮，紛思何由遣。"]', '["館宿风雨滯，始晴行蓋轉。","潯陽山水多，草木俱紛衍。","崎嶇緣碧澗，蒼翠踐苔蘚。","高樹夾潺湲，崩石橫陰巘。","野杏依寒拆，餘云冒嵐淺。","性愜形豈勞，境殊路遺緬。","憶昔終南下，佳游亦屢展。","时禽下流暮，紛思何由遣。"]', '诗', 'shi', '', NULL, '自蒲塘驛廻駕經歷山水 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba66664f-2966-4538-abc4-2f2f23b37fd3', '山行積雨歸途始霽', '山行積雨归途始霽', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["攬轡窮登降，陰雨遘二旬。","但見白雲合，不睹巖中春。","急澗豈易揭，峻塗良難遵。","深林猿聲冷，沮洳虎跡新。","始霽升陽景，山水閱清晨。","雜花積如霧，百卉萋已陳。","鳴騶屢驤首，歸路自忻忻。"]', '["攬轡窮登降，陰雨遘二旬。","但见白云合，不睹巖中春。","急澗豈易揭，峻塗良难遵。","深林猿声冷，沮洳虎跡新。","始霽升陽景，山水閱清晨。","杂花積如霧，百卉萋已陳。","鳴騶屢驤首，归路自忻忻。"]', '诗', 'shi', '', NULL, '山行積雨歸途始霽 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('247c2821-fa45-466c-a71f-86f2e5f49f0a', '傷逝', '傷逝', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["染白一爲黑，焚木盡成灰。","念我室中人，逝去亦不廻。","結髮二十載，賓敬如始來。","提攜屬時屯，契闊憂患災。","柔素亮爲表，禮章夙所該。","仕公不及私，百事委令才。","一旦入閨門，四屋滿塵埃。","斯人既已矣，觸物但傷摧。","單居移時節，泣涕撫嬰孩。","知妄謂當遣，臨感要難裁。","夢想忽如睹，驚起復徘徊。","此心良無已，遶屋生蒿萊。"]', '["染白一爲黑，焚木尽成灰。","念我室中人，逝去亦不廻。","結髮二十載，賓敬如始来。","提携屬时屯，契闊憂患災。","柔素亮爲表，禮章夙所該。","仕公不及私，百事委令才。","一旦入閨门，四屋满塵埃。","斯人既已矣，觸物但傷摧。","單居移时節，泣涕撫嬰孩。","知妄謂當遣，臨感要难裁。","梦想忽如睹，驚起复徘徊。","此心良無已，遶屋生蒿萊。"]', '诗', 'shi', '', NULL, '傷逝 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fcbd019-d995-4f89-b0ac-0a30177598bd', '往富平傷懷', '往富平傷懷', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晨起凌嚴霜，慟哭臨素帷。","駕言百里塗，惻愴復何爲。","昨者仕公府，屬城常載馳。","出門無所憂，返室亦熙熙。","今者掩筠扉，但聞童稚悲。","丈夫須出入，顧爾內無依。","銜恨已酸骨，何況苦寒時。","單車路蕭條，廻首長逶遲。","飄風忽截野，嘹唳雁起飛。","昔時同往路，獨往今詎知。"]', '["晨起凌嚴霜，慟哭臨素帷。","駕言百里塗，惻愴复何爲。","昨者仕公府，屬城常載驰。","出门無所憂，返室亦熙熙。","今者掩筠扉，但闻童稚悲。","丈夫須出入，顧爾內無依。","銜恨已酸骨，何況苦寒时。","單车路蕭條，廻首长逶遲。","飄风忽截野，嘹唳雁起飞。","昔时同往路，独往今詎知。"]', '诗', 'shi', '', NULL, '往富平傷懷 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2770c58-172a-4fac-a11b-621636f5378e', '出還', '出還', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["昔出喜還家，今還獨傷意。","入室掩無光，銜哀寫虛位。","悽悽動幽幔，寂寂驚寒吹。","幼女復何知，時來庭下戲。","咨嗟日復老，錯莫身如寄。","家人勸我飡，對案空垂淚。"]', '["昔出喜還家，今還独傷意。","入室掩無光，銜哀寫虛位。","悽悽动幽幔，寂寂驚寒吹。","幼女复何知，时来庭下戲。","咨嗟日复老，錯莫身如寄。","家人勸我飡，对案空垂泪。"]', '诗', 'shi', '', NULL, '出還 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8f7ff9-1b81-4b54-af1f-afa455e3cb02', '冬夜', '冬夜', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["杳杳日云夕，鬱結誰爲開。","單衾自不暖，霜霰已皚皚。","晚歲淪夙志，驚鴻感深哀。","深哀當何爲，桃李忽凋摧。","幃悵徒自設，冥寞豈復來。","平生雖恩重，遷去託窮埃。","抱此女曹恨，顧非高世才。","振衣中夜起，河漢尚裴回。"]', '["杳杳日云夕，鬱結誰爲开。","單衾自不暖，霜霰已皚皚。","晚歲淪夙志，驚鴻感深哀。","深哀當何爲，桃李忽凋摧。","幃悵徒自設，冥寞豈复来。","平生雖恩重，遷去託窮埃。","抱此女曹恨，顧非高世才。","振衣中夜起，河漢尚裴回。"]', '诗', 'shi', '', NULL, '冬夜 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9c1fb01-6bc6-4294-b4a4-24904ded5347', '送終', '送終', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["奄忽逾時節，日月獲其良。","蕭蕭車馬悲，祖載發中堂。","生平同此居，一旦異存亡。","斯須亦何益，終復委山岡。","行出國南門，南望鬱蒼蒼。","日入乃云造，慟哭宿風霜。","晨遷俯玄廬，臨訣但遑遑。","方當永潛翳，仰視白日光。","俯仰遽終畢，封樹已荒涼。","獨留不得還，欲去結中腸。","童稚知所失，啼號捉我裳。","既事猶倉卒，歲月始難忘。"]', '["奄忽逾时節，日月獲其良。","蕭蕭车马悲，祖載發中堂。","生平同此居，一旦異存亡。","斯須亦何益，終复委山岡。","行出国南门，南望鬱蒼蒼。","日入乃云造，慟哭宿风霜。","晨遷俯玄廬，臨訣但遑遑。","方當永潛翳，仰視白日光。","俯仰遽終畢，封樹已荒涼。","独留不得還，欲去結中腸。","童稚知所失，啼號捉我裳。","既事猶倉卒，歲月始难忘。"]', '诗', 'shi', '', NULL, '送終 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ba5fc0-d422-4c0b-9077-51e4c0014ffb', '除日', '除日', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["思懷耿如昨，季月已云暮。","忽驚年復新，獨恨人成故。","冰池始泮綠，梅楥還飄素。","淑景方轉延，朝朝自難度。"]', '["思懷耿如昨，季月已云暮。","忽驚年复新，独恨人成故。","冰池始泮綠，梅楥還飄素。","淑景方轉延，朝朝自难度。"]', '诗', 'shi', '', NULL, '除日 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7399c34e-d3b6-4144-a107-d0f78c7d24bb', '對芳樹', '对芳樹', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["迢迢芳園樹，列映清池曲。","對此傷人心，還如故時綠。","風條灑餘靄，露葉承新旭。","佳人不再攀，下有往來躅。"]', '["迢迢芳园樹，列映清池曲。","对此傷人心，還如故时綠。","风條灑餘靄，露葉承新旭。","佳人不再攀，下有往来躅。"]', '诗', 'shi', '', NULL, '對芳樹 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252b2da5-2293-4e34-ab81-63f40b6a0a4a', '月夜', '月夜', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["皓月流春城，華露積芳草。","坐念綺窗空，翻傷清景好。","清景終若斯，傷多人自老。"]', '["皓月流春城，华露積芳草。","坐念綺窗空，翻傷清景好。","清景終若斯，傷多人自老。"]', '诗', 'shi', '', NULL, '月夜 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('109d9834-dd55-43cd-bfe5-e217edb52998', '歎楊花', '歎楊花', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["空蒙不自定，況值暄風度。","舊賞逐流年，新愁忽盈素。","纔縈下苑曲，稍滿東城路。","人意有悲歡，時芳獨如故。"]', '["空蒙不自定，況值暄风度。","旧賞逐流年，新愁忽盈素。","纔縈下苑曲，稍满东城路。","人意有悲歡，时芳独如故。"]', '诗', 'shi', '', NULL, '歎楊花 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f77bbc-5b43-424e-8fc6-cdb7e6c947a5', '過昭國里故第', '過昭国里故第', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["不復見故人，一來過故宅。","物變知景暄，心傷覺時寂。","池荒野筠合，庭綠幽草積。","風散花意謝，鳥還山光夕。","宿昔方同賞，詎知今念昔。","緘室在東廂，遺器不忍覿。","柔翰全分意，芳巾尚染澤。","殘工委筐篋，餘素經刀尺。","收此還我家，將還復愁惕。","永絕攜手歡，空存舊行迹。","冥冥獨無語，杳杳將何適。","唯思今古同，時緩傷與戚。"]', '["不复见故人，一来過故宅。","物变知景暄，心傷覺时寂。","池荒野筠合，庭綠幽草積。","风散花意謝，鸟還山光夕。","宿昔方同賞，詎知今念昔。","緘室在东廂，遺器不忍覿。","柔翰全分意，芳巾尚染澤。","殘工委筐篋，餘素經刀尺。","收此還我家，將還复愁惕。","永絕携手歡，空存旧行迹。","冥冥独無語，杳杳將何適。","唯思今古同，时緩傷與戚。"]', '诗', 'shi', '', NULL, '過昭國里故第 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a4c119-f237-47de-a859-e1f451aa6186', '夏日', '夏日', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["已謂心苦傷，如何日方永。","無人不晝寢，獨坐山中靜。","悟澹將遣慮，學空庶遺境。","積俗易爲侵，愁來復難整。"]', '["已謂心苦傷，如何日方永。","無人不晝寢，独坐山中静。","悟澹將遣慮，学空庶遺境。","積俗易爲侵，愁来复难整。"]', '诗', 'shi', '', NULL, '夏日 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73ec24aa-b952-41d5-8420-9b0ac8d95b7e', '端居感懷', '端居感懷', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["沈沈積素抱，婉婉屬之子。","永日獨無言，忽驚振衣起。","方如在幃室，復悟永終已。","稚子傷恩絕，盛時若流水。","暄涼同寡趣，朗晦俱無理。","寂性常喻人，滯情今在己。","空房欲云暮，巢燕亦來止。","夏木遽成陰，綠苔誰復履。","感至竟何方，幽獨長如此。"]', '["沈沈積素抱，婉婉屬之子。","永日独無言，忽驚振衣起。","方如在幃室，复悟永終已。","稚子傷恩絕，盛时若流水。","暄涼同寡趣，朗晦俱無理。","寂性常喻人，滯情今在己。","空房欲云暮，巢燕亦来止。","夏木遽成陰，綠苔誰复履。","感至竟何方，幽独长如此。"]', '诗', 'shi', '', NULL, '端居感懷 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6ae415-b03d-45a0-bd06-0ad1cc66eca2', '悲紈扇', '悲紈扇', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["非關秋節至，詎是恩情改。","掩嚬人已無，委篋涼空在。","何言永不發，暗使銷光彩。"]', '["非关秋節至，詎是恩情改。","掩嚬人已無，委篋涼空在。","何言永不發，暗使銷光彩。"]', '诗', 'shi', '', NULL, '悲紈扇 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12da597b-33fa-461f-b87b-9b70d55bce1d', '閑齋對雨', '闲斋对雨', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["幽獨自盈抱，陰淡亦連朝。","空齋對高樹，疎雨共蕭條。","巢燕翻泥濕，蕙花依砌消。","端居念往事，倏忽苦驚飆。"]', '["幽独自盈抱，陰淡亦連朝。","空斋对高樹，疎雨共蕭條。","巢燕翻泥濕，蕙花依砌消。","端居念往事，倏忽苦驚飆。"]', '诗', 'shi', '', NULL, '閑齋對雨 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d0f9ac-7869-4c65-89e1-86c4a0dabdee', '林園晚霽', '林园晚霽', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["雨歇見青山，落日照林園。","山多煙鳥亂，林清風景翻。","提攜唯子弟，蕭散在琴言。","同遊不同意，耿耿獨傷魂。","寂寞鐘已盡，如何還入門。"]', '["雨歇见青山，落日照林园。","山多煙鸟亂，林清风景翻。","提携唯子弟，蕭散在琴言。","同游不同意，耿耿独傷魂。","寂寞鐘已尽，如何還入门。"]', '诗', 'shi', '', NULL, '林園晚霽 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d969486-7e76-47dc-8b5e-5ab10e6f5004', '秋夜二首 一', '秋夜二首 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["庭樹轉蕭蕭，陰蟲還戚戚。","獨向高齋眠，夜聞寒雨滴。","微風時動牖，殘燈尚留壁。","惆悵平生懷，偏來委今夕。"]', '["庭樹轉蕭蕭，陰蟲還戚戚。","独向高斋眠，夜闻寒雨滴。","微风时动牖，殘灯尚留壁。","惆悵平生懷，偏来委今夕。"]', '诗', 'shi', '', NULL, '秋夜二首 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd43a36-3214-4bcc-aaf5-f21ccaa3ba96', '秋夜二首 二', '秋夜二首 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["霜露已淒淒，星漢復昭回。","朔風中夜起，驚鴻千里來。","蕭條涼葉下，寂寞清砧哀。","歲晏仰空宇，心事若寒灰。"]', '["霜露已淒淒，星漢复昭回。","朔风中夜起，驚鴻千里来。","蕭條涼葉下，寂寞清砧哀。","歲晏仰空宇，心事若寒灰。"]', '诗', 'shi', '', NULL, '秋夜二首 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1864282-6380-457e-8032-dc54346bcc7f', '感夢', '感梦', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["歲月轉蕪漫，形影長寂寥。","髣髴覯微夢，感嘆起中宵。","綿思靄流月，驚魂颯廻飆。","誰念茲夕永，坐令顏鬢凋。"]', '["歲月轉蕪漫，形影长寂寥。","髣髴覯微梦，感嘆起中宵。","綿思靄流月，驚魂颯廻飆。","誰念茲夕永，坐令顏鬢凋。"]', '诗', 'shi', '', NULL, '感夢 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7914d8f2-bae0-4a50-b0fe-9e9e44b4294e', '同德精舍舊居傷懷', '同德精舍旧居傷懷', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["洛京十載別，東林訪舊扉。","山河不可望，存沒意多違。","時遷跡尚在，同去獨來歸。","還見窗中鴿，日暮遶庭飛。"]', '["洛京十載別，东林訪旧扉。","山河不可望，存沒意多違。","时遷跡尚在，同去独来归。","還见窗中鴿，日暮遶庭飞。"]', '诗', 'shi', '', NULL, '同德精舍舊居傷懷 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c7d8111-fbc8-4d65-8819-217e6054d537', '悲故交', '悲故交', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["白璧衆求瑕，素絲易成汙。","萬里顛沛還，高堂已長暮。","積憤方盈抱，纏哀忽逾度。","念子從此終，黃泉竟誰訴。","一爲時事感，豈獨平生故。","唯見荒丘原，野草塗朝露。"]', '["白璧衆求瑕，素絲易成汙。","万里顛沛還，高堂已长暮。","積憤方盈抱，纏哀忽逾度。","念子從此終，黄泉竟誰訴。","一爲时事感，豈独平生故。","唯见荒丘原，野草塗朝露。"]', '诗', 'shi', '', NULL, '悲故交 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f71d29d-cb3b-4334-99d5-827ae9e07044', '張彭州前與緱氏馮少府各惠寄一篇多故未答張已云沒因追哀敘事兼遠簡馮生', '張彭州前與緱氏馮少府各惠寄一篇多故未答張已云沒因追哀敘事兼远簡馮生', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["君昔掌文翰，西垣復石渠。","朱衣乘白馬，輝光照里閭。","余時忝南省，接讌媿空虛。","一別守茲郡，蹉跎歲再除。","長懷關河表，永日簡牘餘。","郡中有方塘，涼閣對紅蕖。","金玉蒙遠貺，篇詠見吹噓。","未答平生意，已沒九原居。","秋風吹寢門，長慟涕漣如。","覆視緘中字，奄爲昔人書。","髮鬢已云白，交友日彫疎。","馮生遠同恨，憔悴在田廬。"]', '["君昔掌文翰，西垣复石渠。","朱衣乘白马，輝光照里閭。","余时忝南省，接讌媿空虛。","一別守茲郡，蹉跎歲再除。","长懷关河表，永日簡牘餘。","郡中有方塘，涼閣对紅蕖。","金玉蒙远貺，篇詠见吹噓。","未答平生意，已沒九原居。","秋风吹寢门，长慟涕漣如。","覆視緘中字，奄爲昔人书。","髮鬢已云白，交友日彫疎。","馮生远同恨，憔悴在田廬。"]', '诗', 'shi', '', NULL, '張彭州前與緱氏馮少府各惠寄一篇多故未答張已云沒因追哀敘事兼遠簡馮生 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4813a27-9cc6-491d-a5a0-70acfca1b278', '東林精舍見故殿中鄭侍御題詩追舊書情涕泗橫集因寄呈閻澧州馮少府', '东林精舍见故殿中鄭侍御題诗追旧书情涕泗橫集因寄呈閻澧州馮少府', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["仲月景氣佳，東林一登歷。","中有故人詩，淒涼在高壁。","精思長懸世，音容已歸寂。","墨澤傳灑餘，磨滅親翰跡。","平生忽如夢，百事皆成昔。","結騎京華年，揮文篋笥積。","朝廷重英彥，時輩分珪璧。","永謝柏梁陪，獨闕金門籍。","方嬰存歿感，豈暇林泉適。","雨餘山景寒，風散花光夕。","新知雖滿堂，故情誰能覿。","唯當同時友，緘寄空悽慼。"]', '["仲月景氣佳，东林一登歷。","中有故人诗，淒涼在高壁。","精思长懸世，音容已归寂。","墨澤傳灑餘，磨滅親翰跡。","平生忽如梦，百事皆成昔。","結騎京华年，揮文篋笥積。","朝廷重英彥，时輩分珪璧。","永謝柏梁陪，独闕金门籍。","方嬰存歿感，豈暇林泉適。","雨餘山景寒，风散花光夕。","新知雖满堂，故情誰能覿。","唯當同时友，緘寄空悽慼。"]', '诗', 'shi', '', NULL, '東林精舍見故殿中鄭侍御題詩追舊書情涕泗橫集因寄呈閻澧州馮少府 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3daa8e6-47ec-44c8-b7cf-af3a659292a1', '同李二過亡友鄭子故第', '同李二過亡友鄭子故第', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["客車名未滅，沒世恨應長。","斜月知何照，幽林判自芳。","故人驚逝水，寒雀噪空牆。","不是平生舊，遺蹤要可傷。"]', '["客车名未滅，沒世恨應长。","斜月知何照，幽林判自芳。","故人驚逝水，寒雀噪空牆。","不是平生旧，遺蹤要可傷。"]', '诗', 'shi', '', NULL, '同李二過亡友鄭子故第 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64616ec2-5d11-4c67-908a-d2c582ced6e8', '話舊', '話旧', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["存亡三十載，事過悉成空。","不惜霑衣淚，併話一宵中。"]', '["存亡三十載，事過悉成空。","不惜霑衣泪，併話一宵中。"]', '诗', 'shi', '', NULL, '話舊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e983caa-b744-4629-b53e-fd5100a6c8c7', '至開化里壽春公故宅', '至开化里壽春公故宅', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["寧知府中吏，故宅一徘徊。","歷階存往敬，瞻位泣餘哀。","廢井沒荒草，陰牖生緑笞。","門前車馬散，非復昔時來。"]', '["寧知府中吏，故宅一徘徊。","歷階存往敬，瞻位泣餘哀。","廢井沒荒草，陰牖生緑笞。","门前车马散，非复昔时来。"]', '诗', 'shi', '', NULL, '至開化里壽春公故宅 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac97f9d6-469c-4f3c-a56e-8de7bf65bfad', '睢陽感懷', '睢陽感懷', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["豺虎犯天綱，昇平無內備。","長驅陰山卒，略踐三河地。","張侯本忠烈，濟世有深智。","堅壁梁宋間，遠籌吳楚利。","窮年方絕輸，鄰援皆攜貳。","使者哭其庭，救兵終不至。","重圍雖可越，藩翰諒難棄。","飢喉待危巢，懸命中路墜。","甘從鋒刃斃，莫奪堅貞志。","宿將降賊庭，儒生獨全義。","空城唯白骨，同往無賤貴。","哀哉豈獨今，千載當歔欷。"]', '["豺虎犯天綱，昇平無內備。","长驱陰山卒，略踐三河地。","張侯本忠烈，濟世有深智。","堅壁梁宋间，远籌吳楚利。","窮年方絕輸，鄰援皆携貳。","使者哭其庭，救兵終不至。","重圍雖可越，藩翰諒难棄。","飢喉待危巢，懸命中路墜。","甘從鋒刃斃，莫奪堅貞志。","宿將降賊庭，儒生独全義。","空城唯白骨，同往無賤貴。","哀哉豈独今，千載當歔欷。"]', '诗', 'shi', '', NULL, '睢陽感懷 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6492e4a6-90ae-4eab-a798-4f131e6d6cc2', '廣德中洛陽作', '廣德中洛陽作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["生長太平日，不知太平歡。","今還洛陽中，感此方苦酸。","飲藥本攻病，毒腸翻自殘。","王師涉河洛，玉石俱不完。","時節屢遷斥，山河長鬱盤。","蕭條孤煙絕，日入空城寒。","蹇劣乏高步，緝遺守微官。","西懷咸陽道，躑躅心不安。"]', '["生长太平日，不知太平歡。","今還洛陽中，感此方苦酸。","饮藥本攻病，毒腸翻自殘。","王師涉河洛，玉石俱不完。","时節屢遷斥，山河长鬱盤。","蕭條孤煙絕，日入空城寒。","蹇劣乏高步，緝遺守微官。","西懷咸陽道，躑躅心不安。"]', '诗', 'shi', '', NULL, '廣德中洛陽作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bede934-9155-45bb-94b2-a38ce07ef9a9', '閶門懷古', '閶门懷古', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["獨鳥下高樹，遙知吳苑園。","淒涼千古事，日暮倚閶門。"]', '["独鸟下高樹，遙知吳苑园。","淒涼千古事，日暮倚閶门。"]', '诗', 'shi', '', NULL, '閶門懷古 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbaa0e54-ffcb-4b49-b9a6-80382bd8ba39', '感事', '感事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["霜雪皎素絲，何意墜墨池。","青蒼猶可濯，黑色不可移。","女工再三嘆，委棄當此時。","歲寒雖無褐，機杼誰肯施。"]', '["霜雪皎素絲，何意墜墨池。","青蒼猶可濯，黑色不可移。","女工再三嘆，委棄當此时。","歲寒雖無褐，機杼誰肯施。"]', '诗', 'shi', '', NULL, '感事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a58685ef-7d57-4757-a9a2-b554f05f7dd4', '感鏡', '感镜', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鑄鏡廣陵市，菱花匣中發。","夙昔嘗許人，鏡成人已沒。","如冰結圓器，類璧無絲髮。","形影終不臨，清光殊不歇。","一感平生言，松枝樹秋月。"]', '["鑄镜廣陵市，菱花匣中發。","夙昔嘗許人，镜成人已沒。","如冰結圓器，類璧無絲髮。","形影終不臨，清光殊不歇。","一感平生言，松枝樹秋月。"]', '诗', 'shi', '', NULL, '感鏡 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('229e2652-f547-4d3f-8186-23c80c23601c', '歎白髮', '歎白髮', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["還同一葉落，對此孤鏡曉。","絲縷乍難分，楊花復相遶。","時役人易衰，吾年白猶少。"]', '["還同一葉落，对此孤镜晓。","絲縷乍难分，楊花复相遶。","时役人易衰，吾年白猶少。"]', '诗', 'shi', '', NULL, '歎白髮 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b149500-5d1e-4293-b983-02c90f8c28a9', '登高望洛城作', '登高望洛城作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高臺造雲端，遐瞰周四垠。","雄都定鼎地，勢據萬國尊。","河岳出雲雨，土圭酌乾坤。","舟通南越貢，城背北邙原。","帝宅夾清洛，丹霞捧朝暾。","葱蘢瑤臺榭，𥦖窱雙闕門。","十載構屯難，兵戈若雲屯。","膏腴滿榛蕪，比屋空毀垣。","聖主乃東眷，俾賢拯元元。","熙熙居守化，泛泛太府恩。","至損當受益，苦寒必生溫。","平明四城開，稍見市井喧。","坐感理亂迹，永懷經濟言。","吾生自不達，空鳥何翩翻。","天高水流遠，日晏城郭昏。","裴回訖旦夕，聊用寫憂煩。"]', '["高台造云端，遐瞰周四垠。","雄都定鼎地，勢據万国尊。","河岳出云雨，土圭酌乾坤。","舟通南越貢，城背北邙原。","帝宅夾清洛，丹霞捧朝暾。","葱蘢瑤台榭，𥦖窱雙闕门。","十載構屯难，兵戈若云屯。","膏腴满榛蕪，比屋空毀垣。","聖主乃东眷，俾賢拯元元。","熙熙居守化，泛泛太府恩。","至損當受益，苦寒必生溫。","平明四城开，稍见市井喧。","坐感理亂迹，永懷經濟言。","吾生自不達，空鸟何翩翻。","天高水流远，日晏城郭昏。","裴回訖旦夕，聊用寫憂煩。"]', '诗', 'shi', '', NULL, '登高望洛城作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa97a948-1c29-45d1-83a8-64da43bb091b', '同德寺閣集眺', '同德寺閣集眺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["芳節欲云晏，遊遨樂相從。","高閣照丹霞，飀飀含遠風。","寂寥氛氳廓，超忽神慮空。","旭日霽皇州，岧嶢見兩宮。","嵩少多秀色，羣山莫與崇。","三川浩東注，瀍澗亦來同。","陰陽降大和，宇宙得其中。","舟車滿川陸，四國靡不通。","舊堵今即葺，庶甿亦已豐。","周覽思自奮，行當遇時邕。"]', '["芳節欲云晏，游遨乐相從。","高閣照丹霞，飀飀含远风。","寂寥氛氳廓，超忽神慮空。","旭日霽皇州，岧嶢见兩宮。","嵩少多秀色，羣山莫與崇。","三川浩东注，瀍澗亦来同。","陰陽降大和，宇宙得其中。","舟车满川陸，四国靡不通。","旧堵今即葺，庶甿亦已豐。","周覽思自奮，行當遇时邕。"]', '诗', 'shi', '', NULL, '同德寺閣集眺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d509c4a0-7006-4196-b7a5-48039cc8815c', '登寶意寺上方舊遊', '登寶意寺上方旧游', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["翠嶺香臺出半天，萬家煙樹滿晴川。","諸僧近住不相識，坐聽微鐘記往年。"]', '["翠嶺香台出半天，万家煙樹满晴川。","諸僧近住不相識，坐听微鐘記往年。"]', '诗', 'shi', '', NULL, '登寶意寺上方舊遊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3d996c-77cd-4643-9916-433373a3442d', '登樂遊廟作', '登乐游廟作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高原出東城，鬱鬱見咸陽。","上有千載事，乃自漢宣皇。","頹壖久凌遲，陳迹翳丘荒。","春草雖復綠，驚風但飄揚。","周覽京城內，雙闕起中央。","微鐘何處來，暮色忽蒼蒼。","歌吹喧萬井，車馬塞康莊。","昔人豈不爾，百世同一傷。","歸當守沖漠，跡寓心自忘。"]', '["高原出东城，鬱鬱见咸陽。","上有千載事，乃自漢宣皇。","頹壖久凌遲，陳迹翳丘荒。","春草雖复綠，驚风但飄揚。","周覽京城內，雙闕起中央。","微鐘何处来，暮色忽蒼蒼。","歌吹喧万井，车马塞康莊。","昔人豈不爾，百世同一傷。","归當守沖漠，跡寓心自忘。"]', '诗', 'shi', '', NULL, '登樂遊廟作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5430a72-f4b3-4125-af34-0d17fbf18205', '登西南岡卜居遇雨尋竹浪至灃壖縈帶數里清流茂樹雲物可賞', '登西南岡卜居遇雨尋竹浪至灃壖縈带數里清流茂樹云物可賞', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["登高創危構，林表見川流。","微雨颯已至，蕭條川氣秋。","下尋密竹盡，忽曠沙際遊。","紆曲水分野，綿延稼盈疇。","寒花明廢墟，樵牧笑榛丘。","雲水成陰澹，竹樹更清幽。","適自戀佳賞，復茲永日留。"]', '["登高創危構，林表见川流。","微雨颯已至，蕭條川氣秋。","下尋密竹尽，忽曠沙際游。","紆曲水分野，綿延稼盈疇。","寒花明廢墟，樵牧笑榛丘。","云水成陰澹，竹樹更清幽。","適自戀佳賞，复茲永日留。"]', '诗', 'shi', '', NULL, '登西南岡卜居遇雨尋竹浪至灃壖縈帶數里清流茂樹雲物可賞 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b78d7c8-d837-4dad-9ee3-fec6df093258', '灃上與幼遐月夜登西岡翫花', '灃上與幼遐月夜登西岡翫花', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["置酒臨高隅，佳人自城闕。","已翫滿川花，還看滿川月。","花月方浩然，賞心何由歇。"]', '["置酒臨高隅，佳人自城闕。","已翫满川花，還看满川月。","花月方浩然，賞心何由歇。"]', '诗', 'shi', '', NULL, '灃上與幼遐月夜登西岡翫花 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81fffa4c-c387-4b4f-86c0-e7f3cbcf7034', '臺上遲客', '台上遲客', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高臺一悄望，遠樹間朝暉。","但見東西騎，坐令心賞違。","始霽郊原綠，暮春啼鳥稀。","徒然對芳物，何能獨醉歸。"]', '["高台一悄望，远樹间朝暉。","但见东西騎，坐令心賞違。","始霽郊原綠，暮春啼鸟稀。","徒然对芳物，何能独醉归。"]', '诗', 'shi', '', NULL, '臺上遲客 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2640c9b3-65aa-4dc8-9d84-da78d0221f6a', '登樓', '登楼', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["茲樓日登眺，流歲暗蹉跎。","坐厭淮南守，秋山紅樹多。"]', '["茲楼日登眺，流歲暗蹉跎。","坐厭淮南守，秋山紅樹多。"]', '诗', 'shi', '', NULL, '登樓 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c74aa20f-950b-49f9-8bf6-20ec2d133667', '善福寺閣', '善福寺閣', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["殘霞照高閣，青山出遠林。","晴明一登望，瀟灑此幽襟。"]', '["殘霞照高閣，青山出远林。","晴明一登望，瀟灑此幽襟。"]', '诗', 'shi', '', NULL, '善福寺閣 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5702e4da-f721-4fff-a5c6-b1e7c9826b5a', '樓中月夜', '楼中月夜', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["端令倚懸檻，長望抱沈憂。","寧知故園月，今夕在茲樓。","衰蓮送餘馥，華露湛新秋。","坐見蒼林變，清輝愴已休。"]', '["端令倚懸檻，长望抱沈憂。","寧知故园月，今夕在茲楼。","衰蓮送餘馥，华露湛新秋。","坐见蒼林变，清輝愴已休。"]', '诗', 'shi', '', NULL, '樓中月夜 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e05ef0-2aa7-40fa-a13b-39de50c10cff', '寒食後北樓作', '寒食後北楼作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["園林過新節，風花亂高閣。","遙聞擊鼓聲，蹴鞠軍中樂。"]', '["园林過新節，风花亂高閣。","遙闻擊鼓声，蹴鞠軍中乐。"]', '诗', 'shi', '', NULL, '寒食後北樓作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402994cd-8330-4f36-a896-75a5a6bedf89', '西樓', '西楼', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高閣一長望，故園何日歸？煙塵擁函谷，秋雁過來稀。"]', '["高閣一长望，故园何日归？煙塵擁函谷，秋雁過来稀。"]', '诗', 'shi', '', NULL, '西樓 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee656cfd-badc-47b4-85fd-d84919bd7284', '夜望', '夜望', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["南樓夜已寂，暗鳥動林間。","不見城郭事，沈沈唯四山。"]', '["南楼夜已寂，暗鸟动林间。","不见城郭事，沈沈唯四山。"]', '诗', 'shi', '', NULL, '夜望 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce76ed51-7f1c-44cf-9188-d497b0dde5c8', '晚登郡閣', '晚登郡閣', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["悵然高閣望，已掩東城關。","春風偏送柳，夜景欲沈山。"]', '["悵然高閣望，已掩东城关。","春风偏送柳，夜景欲沈山。"]', '诗', 'shi', '', NULL, '晚登郡閣 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43734036-7c61-4b39-ac7b-e95bb3729fc7', '登重玄寺閣', '登重玄寺閣', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["時暇陟雲構，晨霽澄景光。","始見吳都大，十里鬱蒼蒼。","山川表明麗，湖海吞大荒。","合沓臻水陸，駢闐會四方。","俗繁節又暄，雨順物亦康。","禽魚各翔泳，草木遍芬芳。","於茲省甿俗，一用勸農桑。","誠知虎符忝，但恨歸路長。"]', '["时暇陟云構，晨霽澄景光。","始见吳都大，十里鬱蒼蒼。","山川表明丽，湖海吞大荒。","合沓臻水陸，駢闐會四方。","俗繁節又暄，雨順物亦康。","禽鱼各翔泳，草木遍芬芳。","於茲省甿俗，一用勸農桑。","誠知虎符忝，但恨归路长。"]', '诗', 'shi', '', NULL, '登重玄寺閣 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34165368-96b3-4f84-be05-f910951ea0a8', '觀早朝', '观早朝', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["伐鼓通嚴城，車馬溢廣躔。","煌煌列明燭，朝服照華鮮。","金門杳深沈，尚聽清漏傳。","河漢忽已沒，司閽啓晨關。","丹殿據龍首，崔嵬對南山。","寒生千門裏，日照雙闕間。","禁旅下成列，爐香起中天。","輝輝覩明聖，濟濟行俊賢。","媿無鴛鷺姿，短翮空飛還。","誰當假毛羽，雲路相追攀。"]', '["伐鼓通嚴城，车马溢廣躔。","煌煌列明燭，朝服照华鲜。","金门杳深沈，尚听清漏傳。","河漢忽已沒，司閽啓晨关。","丹殿據龙首，崔嵬对南山。","寒生千门裏，日照雙闕间。","禁旅下成列，爐香起中天。","輝輝覩明聖，濟濟行俊賢。","媿無鴛鷺姿，短翮空飞還。","誰當假毛羽，云路相追攀。"]', '诗', 'shi', '', NULL, '觀早朝 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a583296-983c-467a-93e4-65baf25eabb5', '陪元侍御春遊', '陪元侍御春游', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["何處醉春風，長安西復東。","不因俱罷職，豈得此時同。","貰酒宣平里，尋芳下苑中。","往來楊柳陌，猶避昔年驄。"]', '["何处醉春风，长安西复东。","不因俱罷職，豈得此时同。","貰酒宣平里，尋芳下苑中。","往来楊柳陌，猶避昔年驄。"]', '诗', 'shi', '', NULL, '陪元侍御春遊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1124e7cb-2599-4515-9e0a-094809f749f8', '遊龍門香山泉', '游龙门香山泉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山水本自佳，遊人已忘慮。","碧泉更幽絕，賞愛未能去。","潺湲寫幽磴，繚繞帶嘉樹。","激轉忽殊流，歸泓又同注。","羽觴自成翫，永日亦延趣。","靈草有時香，仙源不知處。","還當候圓月，攜手重遊寓。"]', '["山水本自佳，游人已忘慮。","碧泉更幽絕，賞愛未能去。","潺湲寫幽磴，繚繞带嘉樹。","激轉忽殊流，归泓又同注。","羽觴自成翫，永日亦延趣。","靈草有时香，仙源不知处。","還當候圓月，携手重游寓。"]', '诗', 'shi', '', NULL, '遊龍門香山泉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29b560ec-71fe-43e8-887a-891037f3900c', '龍門遊眺', '龙门游眺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鑿山導伊流，中斷若天闢。","都門遙相望，佳氣生朝夕。","素懷出塵意，適有攜手客。","精舍遶層阿，千龕鄰峭壁。","緣雲路猶緬，憩澗鐘已寂。","花樹發煙華，淙流散石脈。","長嘯招遠風，臨潭漱金碧。","日落望都城，人間何役役。"]', '["鑿山導伊流，中斷若天闢。","都门遙相望，佳氣生朝夕。","素懷出塵意，適有携手客。","精舍遶層阿，千龕鄰峭壁。","緣云路猶緬，憩澗鐘已寂。","花樹發煙华，淙流散石脈。","长嘯招远风，臨潭漱金碧。","日落望都城，人间何役役。"]', '诗', 'shi', '', NULL, '龍門遊眺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f6bec03-68a6-4d27-bb32-e0cb3781d7a8', '洛都遊寓', '洛都游寓', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["東風日已和，元化亮無私。","草木同時植，生條有高卑。","罷官守園廬，豈不懷渴飢。","窮通非所干，跼促當何爲。","佳辰幸可遊，親友亦相追。","朝從華林宴，暮返東城期。","掇英出蘭臯，翫月步川坻。","軒冕誠可慕，所憂在縶維。"]', '["东风日已和，元化亮無私。","草木同时植，生條有高卑。","罷官守园廬，豈不懷渴飢。","窮通非所干，跼促當何爲。","佳辰幸可游，親友亦相追。","朝從华林宴，暮返东城期。","掇英出蘭臯，翫月步川坻。","軒冕誠可慕，所憂在縶維。"]', '诗', 'shi', '', NULL, '洛都遊寓 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a786ee09-19c4-400f-94cd-8c94e4b4033d', '再遊龍門懷舊侶', '再游龙门懷旧侶', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["兩山鬱相對，晨策方上干。","靄靄眺都城，悠悠俯清瀾。","邈矣二三子，茲焉屢遊盤。","良時忽已周，獨往念前歡。","好鳥始云至，衆芳亦未闌。","遇物豈殊昔，慨傷自有端。"]', '["兩山鬱相对，晨策方上干。","靄靄眺都城，悠悠俯清瀾。","邈矣二三子，茲焉屢游盤。","良时忽已周，独往念前歡。","好鸟始云至，衆芳亦未闌。","遇物豈殊昔，慨傷自有端。"]', '诗', 'shi', '', NULL, '再遊龍門懷舊侶 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb044022-3be0-4f46-bd69-fb2843c29177', '莊嚴精舍遊集', '莊嚴精舍游集', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["良遊因時暇，乃在西南隅。","綠煙凝層城，豐草滿通衢。","精舍何崇曠，煩跼一弘舒。","架虹施廣蔭，構雲眺八區。","既此塵境遠，忽聞幽鳥殊。","新林泛景光，叢綠含露濡。","永日亮難遂，平生少歡娛。","誰能遽還歸，幸與高士俱。"]', '["良游因时暇，乃在西南隅。","綠煙凝層城，豐草满通衢。","精舍何崇曠，煩跼一弘舒。","架虹施廣蔭，構云眺八區。","既此塵境远，忽闻幽鸟殊。","新林泛景光，叢綠含露濡。","永日亮难遂，平生少歡娛。","誰能遽還归，幸與高士俱。"]', '诗', 'shi', '', NULL, '莊嚴精舍遊集 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a590925-4d9a-4908-8d97-a772dec87f2c', '府舍月遊', '府舍月游', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["官舍耿深夜，佳月喜同遊。","橫河俱半落，泛露忽驚秋。","散彩疎羣樹，分規澄素流。","心期與浩景，蒼蒼殊未收。"]', '["官舍耿深夜，佳月喜同游。","橫河俱半落，泛露忽驚秋。","散彩疎羣樹，分規澄素流。","心期與浩景，蒼蒼殊未收。"]', '诗', 'shi', '', NULL, '府舍月遊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8158bd33-908f-495f-916f-b67989e941b1', '任鄠令渼陂遊眺', '任鄠令渼陂游眺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["野水灩長塘，煙花亂晴日。","氤氳綠樹多，蒼翠千山出。","遊魚時可見，新荷尚未密。","屢往心獨閑，恨無理人術。"]', '["野水灩长塘，煙花亂晴日。","氤氳綠樹多，蒼翠千山出。","游鱼时可见，新荷尚未密。","屢往心独闲，恨無理人術。"]', '诗', 'shi', '', NULL, '任鄠令渼陂遊眺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ed84a6-08c4-4ae2-b737-90ef9f5ad1ea', '西郊遊矚', '西郊游矚', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["東風散餘沍，陂水淡已綠。","煙芳何處尋，杳藹春山曲。","新禽哢暄節，晴光泛嘉木。","一與諸君遊，華觴忻見屬。"]', '["东风散餘沍，陂水淡已綠。","煙芳何处尋，杳藹春山曲。","新禽哢暄節，晴光泛嘉木。","一與諸君游，华觴忻见屬。"]', '诗', 'shi', '', NULL, '西郊遊矚 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c63d844-6e67-4732-a686-cd05f7c31f3f', '再遊西郊渡', '再游西郊渡', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["水曲一追遊，遊人重懷戀。","嬋娟昨夜月，還向波中見。","驚禽棲不定，流芳寒未徧。","攜手更何時，佇看花似霰。"]', '["水曲一追游，游人重懷戀。","嬋娟昨夜月，還向波中见。","驚禽棲不定，流芳寒未徧。","携手更何时，佇看花似霰。"]', '诗', 'shi', '', NULL, '再遊西郊渡 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af7dbdeb-86c3-4e10-84ec-717a2c02698a', '月溪與幼遐君貺同遊', '月溪與幼遐君貺同游', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["岸篠覆廻溪，廻溪曲如月。","沈沈水容綠，寂寂流鶯歇。","淺石方凌亂，遊禽時出沒。","半雨夕陽霏，緣源雜花發。","明晨重來此，同心應已闕。"]', '["岸篠覆廻溪，廻溪曲如月。","沈沈水容綠，寂寂流鶯歇。","淺石方凌亂，游禽时出沒。","半雨夕陽霏，緣源杂花發。","明晨重来此，同心應已闕。"]', '诗', 'shi', '', NULL, '月溪與幼遐君貺同遊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6c4f3e-fbd4-463c-99d7-9a4d046426d4', '與幼遐君貺兄弟同遊白家竹潭', '與幼遐君貺兄弟同游白家竹潭', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["清賞非素期，偶遊方自得。","前登絕嶺險，下視深潭黑。","密竹已成暮，歸雲殊未極。","春鳥依谷暄，紫蘭含幽色。","已將芳景遇，復款平生憶。","終念一歡別，臨風還默默。"]', '["清賞非素期，偶游方自得。","前登絕嶺險，下視深潭黑。","密竹已成暮，归云殊未極。","春鸟依谷暄，紫蘭含幽色。","已將芳景遇，复款平生憶。","終念一歡別，臨风還默默。"]', '诗', 'shi', '', NULL, '與幼遐君貺兄弟同遊白家竹潭 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086523dd-928a-45d2-a46c-5ca57d3a73d7', '秋夕西齋與僧神靜遊', '秋夕西斋與僧神静游', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晨登西齋望，不覺至夕曛。","正當秋夏交，原野起煙氛。","坐聽涼飆舉，華月稍披雲。","漠漠山猶隱，灩灩川始分。","物幽夜更殊，境靜興彌臻。","息機非傲世，于時乏嘉聞。","究空自爲理，況與釋子羣。"]', '["晨登西斋望，不覺至夕曛。","正當秋夏交，原野起煙氛。","坐听涼飆舉，华月稍披云。","漠漠山猶隐，灩灩川始分。","物幽夜更殊，境静兴彌臻。","息機非傲世，于时乏嘉闻。","究空自爲理，況與釋子羣。"]', '诗', 'shi', '', NULL, '秋夕西齋與僧神靜遊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f13be7dc-460e-46a2-b0a3-cd7a81586439', '觀田家', '观田家', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["微雨衆卉新，一雷驚蟄始。","田家幾日閑，耕種從此起。","丁壯俱在野，場圃亦就理。","歸來景常晏，飲犢西澗水。","飢劬不自苦，膏澤且爲喜。","倉廩無宿儲，徭役猶未已。","方慙不耕者，祿食出閭里。"]', '["微雨衆卉新，一雷驚蟄始。","田家幾日闲，耕種從此起。","丁壯俱在野，場圃亦就理。","归来景常晏，饮犢西澗水。","飢劬不自苦，膏澤且爲喜。","倉廩無宿儲，徭役猶未已。","方慙不耕者，祿食出閭里。"]', '诗', 'shi', '', NULL, '觀田家 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('007f3468-83fc-4af8-b110-d2c4c1b90e10', '園亭覽物', '园亭覽物', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["積雨時物變，夏綠滿園新。","殘花已落實，高笋半成筠。","守此幽棲地，自是忘機人。"]', '["積雨时物变，夏綠满园新。","殘花已落實，高笋半成筠。","守此幽棲地，自是忘機人。"]', '诗', 'shi', '', NULL, '園亭覽物 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a49dfa1a-df22-4eec-908e-0af156ecc93c', '觀灃水漲', '观灃水漲', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夏雨萬壑湊，灃漲暮渾渾。","草木盈川谷，澶漫一平吞。","槎梗方瀰泛，濤沫亦洪翻。","北來注涇渭，所過無安源。","雲嶺同昏黑，觀望悸心魂。","舟人空斂棹，風波正自奔。"]', '["夏雨万壑湊，灃漲暮渾渾。","草木盈川谷，澶漫一平吞。","槎梗方瀰泛，濤沫亦洪翻。","北来注涇渭，所過無安源。","云嶺同昏黑，观望悸心魂。","舟人空斂棹，风波正自奔。"]', '诗', 'shi', '', NULL, '觀灃水漲 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c813c27c-1464-4161-8f83-f53a7f6620df', '陪王卿郎中遊南池', '陪王卿郎中游南池', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["鵷鴻俱失侶，同爲此地遊。","露浥荷花氣，風散柳園秋。","煙草凝衰嶼，星漢泛歸流。","林高初上月，塘深未轉舟。","清言屢往復，華樽始獻酬。","終憶秦川賞，端坐起離憂。"]', '["鵷鴻俱失侶，同爲此地游。","露浥荷花氣，风散柳园秋。","煙草凝衰嶼，星漢泛归流。","林高初上月，塘深未轉舟。","清言屢往复，华樽始獻酬。","終憶秦川賞，端坐起離憂。"]', '诗', 'shi', '', NULL, '陪王卿郎中遊南池 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('248cc277-fcbe-42b9-92f1-70dbe1176dd9', '南園陪王卿遊矚', '南园陪王卿游矚', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["形跡雖拘檢，世事澹無心。","郡中多山水，日夕聽幽禽。","几閣文墨暇，園林春景深。","雜花芳意散，綠池暮色沈。","君子有高躅，相攜在幽尋。","一酌何爲貴，可以寫沖襟。"]', '["形跡雖拘檢，世事澹無心。","郡中多山水，日夕听幽禽。","几閣文墨暇，园林春景深。","杂花芳意散，綠池暮色沈。","君子有高躅，相携在幽尋。","一酌何爲貴，可以寫沖襟。"]', '诗', 'shi', '', NULL, '南園陪王卿遊矚 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ba16aca-23f9-4c2d-bb57-0fd331e2cc43', '遊西山', '游西山', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["時事方擾擾，幽賞獨悠悠。","弄泉朝涉澗，采石夜歸州。","揮翰題蒼峭，下馬歷嵌丘。","所愛唯山水，到此即淹留。"]', '["时事方擾擾，幽賞独悠悠。","弄泉朝涉澗，采石夜归州。","揮翰題蒼峭，下马歷嵌丘。","所愛唯山水，到此即淹留。"]', '诗', 'shi', '', NULL, '遊西山 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f6ae131-6af9-47b3-b28f-bb8b90b971c4', '春遊南亭', '春游南亭', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["川明氣已變，巖寒雲尚擁。","南亭草心綠，春塘泉脈動。","景煦聽禽響，雨餘看柳重。","逍遙池館華，益媿專城寵。"]', '["川明氣已变，巖寒云尚擁。","南亭草心綠，春塘泉脈动。","景煦听禽响，雨餘看柳重。","逍遙池館华，益媿專城寵。"]', '诗', 'shi', '', NULL, '春遊南亭 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b83b39-8af2-408f-b8a8-26094f83f8f3', '再遊西山', '再游西山', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["南譙古山郡，信是高人居。","自歎乏弘量，終朝親簿書。","於時忽命駕，秋野正蕭疎。","積逋誠待責，尋山亦有餘。","測測石泉冷，曖曖煙谷虛。","中有釋門子，種果結茅廬。","出身厭名利，遇境即躊躇。","守直雖多忤，視險方晏如。","況將塵埃外，襟抱從此舒。"]', '["南譙古山郡，信是高人居。","自歎乏弘量，終朝親簿书。","於时忽命駕，秋野正蕭疎。","積逋誠待責，尋山亦有餘。","測測石泉冷，曖曖煙谷虛。","中有釋门子，種果結茅廬。","出身厭名利，遇境即躊躇。","守直雖多忤，視險方晏如。","況將塵埃外，襟抱從此舒。"]', '诗', 'shi', '', NULL, '再遊西山 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7f4d4c-df44-4218-9223-79b4a3ab8ccf', '遊靈巖寺', '游靈巖寺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["始入松路永，獨忻山寺幽。","不知臨絕檻，乃見西江流。","吳岫分煙景，楚甸散林丘。","方悟關塞眇，重軫故園愁。","聞鐘戒歸騎，憩澗惜良遊。","地疎泉谷狹，春深草木稠。","茲焉賞未極，清景期杪秋。"]', '["始入松路永，独忻山寺幽。","不知臨絕檻，乃见西江流。","吳岫分煙景，楚甸散林丘。","方悟关塞眇，重軫故园愁。","闻鐘戒归騎，憩澗惜良游。","地疎泉谷狹，春深草木稠。","茲焉賞未極，清景期杪秋。"]', '诗', 'shi', '', NULL, '遊靈巖寺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('863ed1f7-902b-495a-85ef-4689dd9e6f8d', '與盧陟同遊永定寺北池僧齋', '與盧陟同游永定寺北池僧斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["密竹行已遠，子歸啼更深。","綠池芳草氣，閑齋春樹陰。","晴蝶飄蘭逕，遊蜂遶花心。","不遇君攜手，誰復此幽尋。"]', '["密竹行已远，子归啼更深。","綠池芳草氣，闲斋春樹陰。","晴蝶飄蘭逕，游蜂遶花心。","不遇君携手，誰复此幽尋。"]', '诗', 'shi', '', NULL, '與盧陟同遊永定寺北池僧齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b92e84d3-e5c6-4585-bceb-a98938cd65cd', '遊溪', '游溪', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["野水煙鶴唳，楚天雲雨空。","翫舟清景晚，垂釣綠蒲中。","落花飄旅衣，歸流澹清風。","緣源不可極，遠樹但青葱。"]', '["野水煙鹤唳，楚天云雨空。","翫舟清景晚，垂釣綠蒲中。","落花飄旅衣，归流澹清风。","緣源不可極，远樹但青葱。"]', '诗', 'shi', '', NULL, '遊溪 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ef4353-90d7-4664-8c2d-5862c783dabb', '遊開元精舍', '游开元精舍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["夏衣始輕體，遊步愛僧居。","果園新雨後，香臺照日初。","綠陰生晝靜，孤花表春餘。","符竹方爲累，形跡一來疎。"]', '["夏衣始轻體，游步愛僧居。","果园新雨後，香台照日初。","綠陰生晝静，孤花表春餘。","符竹方爲累，形跡一来疎。"]', '诗', 'shi', '', NULL, '遊開元精舍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d273c9-0b05-4d91-8c24-e523cf331a38', '襄武館遊眺', '襄武館游眺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["州民知禮讓，訟簡得遨遊。","高亭憑古地，山川當暮秋。","是時秔稻熟，西望盡田疇。","仰恩慙政拙，念勞喜歲收。","澹泊風景晏，繚繞雲樹幽。","節往情惻惻，天高思悠悠。","嘉賓幸雲集，芳罇始淹留。","還希習池賞，聊以駐鳴騶。"]', '["州民知禮讓，訟簡得遨游。","高亭憑古地，山川當暮秋。","是时秔稻熟，西望尽田疇。","仰恩慙政拙，念勞喜歲收。","澹泊风景晏，繚繞云樹幽。","節往情惻惻，天高思悠悠。","嘉賓幸云集，芳罇始淹留。","還希習池賞，聊以駐鳴騶。"]', '诗', 'shi', '', NULL, '襄武館遊眺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d31218-4617-4343-8057-201b421dd53f', '秋景詣瑯瑘精舍', '秋景詣瑯瑘精舍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["屢訪塵外跡，未窮幽賞情。","高秋天景遠，始見山水清。","上陟巖殿憩，暮看雲壑平。","蒼茫寒色起，迢遞晚鐘鳴。","意有清夜戀，身爲符守嬰。","悟言緇衣子，蕭灑中林行。"]', '["屢訪塵外跡，未窮幽賞情。","高秋天景远，始见山水清。","上陟巖殿憩，暮看云壑平。","蒼茫寒色起，迢遞晚鐘鳴。","意有清夜戀，身爲符守嬰。","悟言緇衣子，蕭灑中林行。"]', '诗', 'shi', '', NULL, '秋景詣瑯瑘精舍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51f05a4-83e7-4f94-afa5-656c1cbd39ae', '同韓郎中閑庭南望秋景', '同韓郎中闲庭南望秋景', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["朝下抱餘素，地高心本閑。","如何趨府客，罷秩見秋山。","疎樹共寒意，遊禽同暮還。","因君悟清景，西望一開顏。"]', '["朝下抱餘素，地高心本闲。","如何趨府客，罷秩见秋山。","疎樹共寒意，游禽同暮還。","因君悟清景，西望一开顏。"]', '诗', 'shi', '', NULL, '同韓郎中閑庭南望秋景 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6accabcd-5b81-4828-b8b3-20b9e41424ea', '慈恩精舍南池作', '慈恩精舍南池作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["清境豈云遠，炎氛忽如遺。","重門布綠陰，菡萏滿廣池。","石髮散清淺，林光動漣漪。","緣崖摘紫房，扣檻集靈龜。","浥浥餘露氣，馥馥幽襟披。","積喧忻物曠，耽玩覺景馳。","明晨復趨府，幽賞當反思。"]', '["清境豈云远，炎氛忽如遺。","重门布綠陰，菡萏满廣池。","石髮散清淺，林光动漣漪。","緣崖摘紫房，扣檻集靈龟。","浥浥餘露氣，馥馥幽襟披。","積喧忻物曠，耽玩覺景驰。","明晨复趨府，幽賞當反思。"]', '诗', 'shi', '', NULL, '慈恩精舍南池作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c642fc85-d3cf-4f39-a9ad-854e6da968f6', '雨夜宿清都觀', '雨夜宿清都观', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["靈飆動閶闔，微雨灑瑤林。","復此新秋夜，高閣正沈沈。","曠歲恨殊跡，茲夕一披襟。","洞戶含涼氣，網軒構層陰。","況自展良友，芳罇遂盈斟。","適悟委前妄，清言怡道心。","豈戀腰間綬，如彼籠中禽。"]', '["靈飆动閶闔，微雨灑瑤林。","复此新秋夜，高閣正沈沈。","曠歲恨殊跡，茲夕一披襟。","洞戶含涼氣，網軒構層陰。","況自展良友，芳罇遂盈斟。","適悟委前妄，清言怡道心。","豈戀腰间綬，如彼籠中禽。"]', '诗', 'shi', '', NULL, '雨夜宿清都觀 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41e1521-e39e-4cfb-8367-c6450c8e765a', '善福精舍秋夜遲諸君', '善福精舍秋夜遲諸君', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["廣庭獨閑步，夜色方湛然。","丹閣已排雲，皓月更高懸。","繁露降秋節，蒼林鬱芊芊。","仰觀天氣涼，高詠古人篇。","撫己亮無庸，結交賴羣賢。","屬予翹思時，方子中夜眠。","相去隔城闕，佳期屢徂遷。","如何日夕待，見月三四圓。"]', '["廣庭独闲步，夜色方湛然。","丹閣已排云，皓月更高懸。","繁露降秋節，蒼林鬱芊芊。","仰观天氣涼，高詠古人篇。","撫己亮無庸，結交賴羣賢。","屬予翹思时，方子中夜眠。","相去隔城闕，佳期屢徂遷。","如何日夕待，见月三四圓。"]', '诗', 'shi', '', NULL, '善福精舍秋夜遲諸君 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0e1d96-c249-47c4-b16d-4d91dd6e7cce', '東郊', '东郊', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["吏舍跼終年，出郊曠清曙。","楊柳散和風，青山澹吾慮。","依叢適自憩，緣澗還復去。","微雨靄芳原，春鳩鳴何處？","樂幽心屢止，遵事跡猶遽。","終罷斯結廬，慕陶真可庶。"]', '["吏舍跼終年，出郊曠清曙。","楊柳散和风，青山澹吾慮。","依叢適自憩，緣澗還复去。","微雨靄芳原，春鳩鳴何处？","乐幽心屢止，遵事跡猶遽。","終罷斯結廬，慕陶真可庶。"]', '诗', 'shi', '', NULL, '東郊 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b1d232d-0a36-4825-bb31-60de152516df', '秋郊作', '秋郊作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["清露澄境遠，旭日照林初。","一望秋山淨，蕭條形迹疎。","登原忻時稼，采菊行故墟。","方願沮溺耦，淡泊守田廬。"]', '["清露澄境远，旭日照林初。","一望秋山淨，蕭條形迹疎。","登原忻时稼，采菊行故墟。","方願沮溺耦，淡泊守田廬。"]', '诗', 'shi', '', NULL, '秋郊作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd40c02c-fb97-4ef0-86a5-6139361f4e10', '行寬禪師院', '行寬禪師院', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["北望極長廊，斜扉映藂竹。","亭午一來尋，院幽僧亦獨。","唯聞山鳥啼，愛此林下宿。"]', '["北望極长廊，斜扉映藂竹。","亭午一来尋，院幽僧亦独。","唯闻山鸟啼，愛此林下宿。"]', '诗', 'shi', '', NULL, '行寬禪師院 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2358b8a-e1d3-43a6-bc2d-539361208678', '神靜師院', '神静師院', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["青苔幽巷徧，新林露氣微。","經聲在深竹，高齋獨掩扉。","憩樹愛嵐嶺，聽禽悅朝暉。","方耽靜中趣，自與塵事違。"]', '["青苔幽巷徧，新林露氣微。","經声在深竹，高斋独掩扉。","憩樹愛嵐嶺，听禽悅朝暉。","方耽静中趣，自與塵事違。"]', '诗', 'shi', '', NULL, '神靜師院 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3fe373c-e5d3-4e7e-a9ba-4afa919be279', '精舍納涼', '精舍納涼', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["山景寂已晦，野寺變蒼蒼。","夕風吹高殿，露葉散林光。","清鐘始戒夜，幽禽尚歸翔。","誰復掩扉臥，不詠南軒涼。"]', '["山景寂已晦，野寺变蒼蒼。","夕风吹高殿，露葉散林光。","清鐘始戒夜，幽禽尚归翔。","誰复掩扉臥，不詠南軒涼。"]', '诗', 'shi', '', NULL, '精舍納涼 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a75f78-8df0-4416-be59-ac16227d7366', '藍嶺精舍', '藍嶺精舍', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["石壁精舍高，排雲聊直上。","佳遊愜始願，忘險得前賞。","崖傾景方晦，谷轉川如掌。","綠林含蕭條，飛閣起弘敞。","道人上方至，清夜還獨往。","日落羣山陰，天秋百泉響。","所嗟累已成，安得長偃仰。"]', '["石壁精舍高，排云聊直上。","佳游愜始願，忘險得前賞。","崖傾景方晦，谷轉川如掌。","綠林含蕭條，飞閣起弘敞。","道人上方至，清夜還独往。","日落羣山陰，天秋百泉响。","所嗟累已成，安得长偃仰。"]', '诗', 'shi', '', NULL, '藍嶺精舍 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e9a5fb6-7b01-42a0-a191-f1238e52ae76', '道晏寺主院', '道晏寺主院', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["北鄰有幽竹，潛筠穿我廬。","往來地已密，心樂道者居。","殘花廻往節，輕條蔭夏初。","聞鐘北牕起，嘯傲永日餘。"]', '["北鄰有幽竹，潛筠穿我廬。","往来地已密，心乐道者居。","殘花廻往節，轻條蔭夏初。","闻鐘北牕起，嘯傲永日餘。"]', '诗', 'shi', '', NULL, '道晏寺主院 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b19f0d-9cb0-48ba-b19b-0f0772251744', '義演法師西齋', '義演法師西斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["結茅臨絕岸，隔水聞清磬。","山水曠蕭條，登臨散情性。","稍指緣原騎，還尋汲澗逕。","長嘯倚亭樹，悵然川光暝。"]', '["結茅臨絕岸，隔水闻清磬。","山水曠蕭條，登臨散情性。","稍指緣原騎，還尋汲澗逕。","长嘯倚亭樹，悵然川光暝。"]', '诗', 'shi', '', NULL, '義演法師西齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d03dbb9-f762-4b92-b8af-a8f0edfdeb54', '澄秀上座院', '澄秀上座院', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["繚繞西南隅，鳥聲轉幽靜。","秀公今不在，獨禮高僧影。","林下器未收，何人適煮茗。"]', '["繚繞西南隅，鸟声轉幽静。","秀公今不在，独禮高僧影。","林下器未收，何人適煮茗。"]', '诗', 'shi', '', NULL, '澄秀上座院 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e75b6194-8ba8-4435-9699-50bfce30ee44', '至西峰蘭若受田婦饋', '至西峰蘭若受田婦饋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["攀崖復緣澗，遂造幽人居。","鳥鳴泉谷暖，土起萌甲舒。","聊登石樓憩，下翫潭中魚。","田婦有嘉獻，潑撒新歲餘。","常怪投錢飲，事與賢達疎。","今我何爲答，鰥寡欲焉如。"]', '["攀崖复緣澗，遂造幽人居。","鸟鳴泉谷暖，土起萌甲舒。","聊登石楼憩，下翫潭中鱼。","田婦有嘉獻，潑撒新歲餘。","常怪投錢饮，事與賢達疎。","今我何爲答，鰥寡欲焉如。"]', '诗', 'shi', '', NULL, '至西峰蘭若受田婦饋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d289c3-96db-4323-8456-b25f5899746d', '曇智禪師院', '曇智禪師院', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["高年不復出，門徑衆草生。","時夏方新雨，果藥發餘榮。","疎澹下林景，流暮幽禽情。","身名兩俱遣，獨此野寺行。"]', '["高年不复出，门徑衆草生。","时夏方新雨，果藥發餘榮。","疎澹下林景，流暮幽禽情。","身名兩俱遣，独此野寺行。"]', '诗', 'shi', '', NULL, '曇智禪師院 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1904b716-cabb-4e23-b9a0-0d2e792364e6', '起度律師同居東齋院', '起度律師同居东斋院', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["釋子喜相偶，幽林俱避喧。","安居同僧夏，清夜諷道言。","對閣景恆晏，步庭陰始繁。","逍遙無一事，松風入南軒。"]', '["釋子喜相偶，幽林俱避喧。","安居同僧夏，清夜諷道言。","对閣景恆晏，步庭陰始繁。","逍遙無一事，松风入南軒。"]', '诗', 'shi', '', NULL, '起度律師同居東齋院 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe72db9a-b75f-423a-a43f-fa94b600b921', '遊瑯瑘山寺', '游瑯瑘山寺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["受命恤人隱，茲遊久未遑。","鳴騶響幽澗，前旌耀崇岡。","青冥臺砌寒，綠褥草木香。","填壑躋花界，疊石構雲房。","經製隨巖轉，繚繞豈定方。","新泉泄陰壁，高蘿蔭綠塘。","攀林一栖止，飲水得清涼。","物累誠可遣，疲甿終未忘。","還歸坐郡閣，但見山蒼蒼。"]', '["受命恤人隐，茲游久未遑。","鳴騶响幽澗，前旌耀崇岡。","青冥台砌寒，綠褥草木香。","填壑躋花界，叠石構云房。","經製隨巖轉，繚繞豈定方。","新泉泄陰壁，高蘿蔭綠塘。","攀林一栖止，饮水得清涼。","物累誠可遣，疲甿終未忘。","還归坐郡閣，但见山蒼蒼。"]', '诗', 'shi', '', NULL, '遊瑯瑘山寺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25972724-9ff7-431e-8f18-b3441b737eaa', '同越瑯瑘山', '同越瑯瑘山', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["石門有雪無形跡，松壑凝烟滿衆香。","餘食施庭寒鳥下，破衣挂樹老僧亡。"]', '["石门有雪無形跡，松壑凝烟满衆香。","餘食施庭寒鸟下，破衣挂樹老僧亡。"]', '诗', 'shi', '', NULL, '同越瑯瑘山 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d13ec4e-3205-490d-b8a6-26ef3624ff45', '詣西山深師', '詣西山深師', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["曹溪舊弟子，何緣住此山。","世有征戰事，心將流水閑。","埽林驅虎出，宴坐一林間。","藩守寧爲重，擁騎造雲關。"]', '["曹溪旧弟子，何緣住此山。","世有征戰事，心將流水闲。","埽林驱虎出，宴坐一林间。","藩守寧爲重，擁騎造云关。"]', '诗', 'shi', '', NULL, '詣西山深師 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f821abbf-1288-4fa9-923e-8a6a8a4b31aa', '尋簡寂觀瀑布', '尋簡寂观瀑布', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["躡石欹危過急澗，攀崖迢遞弄懸泉。","猶將虎竹爲身累，欲付歸人絕世緣。"]', '["躡石欹危過急澗，攀崖迢遞弄懸泉。","猶將虎竹爲身累，欲付归人絕世緣。"]', '诗', 'shi', '', NULL, '尋簡寂觀瀑布 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0297a3-575e-44a5-8c2a-01c3753092de', '簡寂觀西澗瀑布下作', '簡寂观西澗瀑布下作', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["淙流絕壁散，虛煙翠澗深。","叢際松風起，飄來灑塵襟。","窺蘿翫猿鳥，解組傲雲林。","茶果邀真侶，觴酌洽同心。","曠歲懷茲賞，行春始重尋。","聊將橫吹笛，一寫山水音。"]', '["淙流絕壁散，虛煙翠澗深。","叢際松风起，飄来灑塵襟。","窺蘿翫猿鸟，解組傲云林。","茶果邀真侶，觴酌洽同心。","曠歲懷茲賞，行春始重尋。","聊將橫吹笛，一寫山水音。"]', '诗', 'shi', '', NULL, '簡寂觀西澗瀑布下作 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1239635e-cd7a-4632-9904-3ea28507fce1', '遊南齋', '游南斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["池上鳴佳禽，僧齋日幽寂。","高林晚露清，紅藥無人摘。","春水不生煙，荒岡筠翳石。","不應朝夕遊，良爲蹉跎客。"]', '["池上鳴佳禽，僧斋日幽寂。","高林晚露清，紅藥無人摘。","春水不生煙，荒岡筠翳石。","不應朝夕游，良爲蹉跎客。"]', '诗', 'shi', '', NULL, '遊南齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bca204e-f51f-41b6-8684-6d715a5ddbab', '南園', '南园', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["清露夏天曉，荒園野氣通。","水禽遙泛雪，池蓮迥披紅。","幽林詎知暑，環舟似不窮。","頓灑塵喧意，長嘯滿襟風。"]', '["清露夏天晓，荒园野氣通。","水禽遙泛雪，池蓮迥披紅。","幽林詎知暑，环舟似不窮。","頓灑塵喧意，长嘯满襟风。"]', '诗', 'shi', '', NULL, '南園 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe489c9-2e12-4a1f-b78d-ea48f44a958d', '西亭', '西亭', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["亭宇麗朝景，簾牖散暄風。","小山初構石，珍樹正然紅。","弱藤已扶樹，幽蘭欲成叢。","芳心幸如此，佳人時不同。"]', '["亭宇丽朝景，簾牖散暄风。","小山初構石，珍樹正然紅。","弱藤已扶樹，幽蘭欲成叢。","芳心幸如此，佳人时不同。"]', '诗', 'shi', '', NULL, '西亭 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0298a038-c7e0-45b0-8cad-1689bb3355fe', '夏景園廬', '夏景园廬', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["羣木晝陰靜，北牕涼氣多。","閑居逾時節，夏雲已嵯峨。","搴葉愛繁綠，緣澗弄驚波。","豈爲論夙志，對此青山阿。"]', '["羣木晝陰静，北牕涼氣多。","闲居逾时節，夏云已嵯峨。","搴葉愛繁綠，緣澗弄驚波。","豈爲論夙志，对此青山阿。"]', '诗', 'shi', '', NULL, '夏景園廬 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c44cf36d-2166-4118-b8cc-c9c7b15dedd4', '夏至避暑北池', '夏至避暑北池', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["晝晷已云極，宵漏自此長。","未及施政教，所憂變炎涼。","公門日多暇，是月農稍忙。","高居念田里，苦熱安可當。","亭午息羣物，獨遊愛方塘。","門閉陰寂寂，城高樹蒼蒼。","綠筠尚含粉，圓荷始散芳。","於焉灑煩抱，可以對華觴。"]', '["晝晷已云極，宵漏自此长。","未及施政教，所憂变炎涼。","公门日多暇，是月農稍忙。","高居念田里，苦熱安可當。","亭午息羣物，独游愛方塘。","门閉陰寂寂，城高樹蒼蒼。","綠筠尚含粉，圓荷始散芳。","於焉灑煩抱，可以对华觴。"]', '诗', 'shi', '', NULL, '夏至避暑北池 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f4b3d1f-d4e5-4d55-bef4-ea5694503cae', '題從姪成緒西林精舍書齋', '題從姪成緒西林精舍书斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["棲身齒多暮，息心君獨少。","慕謝始精文，依僧欲觀妙。","冽泉前堦注，清池北窗照。","果藥雜芬敷，松筠疎蒨峭。","屢躋幽人境，每肆芳辰眺。","採栗玄猿窟，擷芝丹林嶠。","紵衣豈寒禦，蔬食非飢療。","雖甘巷北單，豈塞青紫耀。","郡有優賢榻，朝編貢士詔。","欲同朱輪載，勿憚移文誚。"]', '["棲身齒多暮，息心君独少。","慕謝始精文，依僧欲观妙。","冽泉前堦注，清池北窗照。","果藥杂芬敷，松筠疎蒨峭。","屢躋幽人境，每肆芳辰眺。","採栗玄猿窟，擷芝丹林嶠。","紵衣豈寒禦，蔬食非飢療。","雖甘巷北單，豈塞青紫耀。","郡有優賢榻，朝編貢士詔。","欲同朱輪載，勿憚移文誚。"]', '诗', 'shi', '', NULL, '題從姪成緒西林精舍書齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb529fe1-c20a-4fd8-b1f8-b6bbc0fec755', '題鄭弘憲侍御遺愛草堂', '題鄭弘憲侍御遺愛草堂', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["居士近依僧，青山結茅屋。","疎松映嵐晚，春池含苔綠。","繁華冒陽嶺，新禽響幽谷。","長嘯攀喬林，慕茲高世躅。"]', '["居士近依僧，青山結茅屋。","疎松映嵐晚，春池含苔綠。","繁华冒陽嶺，新禽响幽谷。","长嘯攀喬林，慕茲高世躅。"]', '诗', 'shi', '', NULL, '題鄭弘憲侍御遺愛草堂 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a0d747-9e56-46cb-90b1-06573d212f2d', '同元錫題瑯瑘寺', '同元錫題瑯瑘寺', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["適從郡邑喧，又茲三伏熱。","山中清景多，石罅寒泉潔。","花香天界事，松竹人間別。","殿分嵐嶺明，磴臨懸壑絕。","昏旭窮陟降，幽顯盡披閱。","嶔駭風雨區，寒知龍蛇穴。","情虛澹泊生，境寂塵妄滅。","經世豈非道，無爲厭車轍。"]', '["適從郡邑喧，又茲三伏熱。","山中清景多，石罅寒泉潔。","花香天界事，松竹人间別。","殿分嵐嶺明，磴臨懸壑絕。","昏旭窮陟降，幽显尽披閱。","嶔駭风雨區，寒知龙蛇穴。","情虛澹泊生，境寂塵妄滅。","經世豈非道，無爲厭车轍。"]', '诗', 'shi', '', NULL, '同元錫題瑯瑘寺 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb57be5-3ccc-4c2e-98f8-29706f8e8890', '題鄭拾遺草堂', '題鄭拾遺草堂', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["借地結茅棟，橫竹掛朝衣。","秋園雨中綠，幽居塵事違。","陰井夕蟲亂，高林霜果稀。","子有白雲意，構此想巖扉。"]', '["借地結茅棟，橫竹掛朝衣。","秋园雨中綠，幽居塵事違。","陰井夕蟲亂，高林霜果稀。","子有白云意，構此想巖扉。"]', '诗', 'shi', '', NULL, '題鄭拾遺草堂 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32837f33-ad10-4bcb-b647-891ed0870c8a', '詠玉', '詠玉', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["乾坤有精物，至寶無文章。","雕琢爲世器，真性一朝傷。"]', '["乾坤有精物，至寶無文章。","雕琢爲世器，真性一朝傷。"]', '诗', 'shi', '', NULL, '詠玉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c28cdd9-7ee2-49c1-bbc9-6ada013ae310', '詠露珠', '詠露珠', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["秋荷一滴露，清夜墜玄天。","將來玉盤上，不定始知圓。"]', '["秋荷一滴露，清夜墜玄天。","將来玉盤上，不定始知圓。"]', '诗', 'shi', '', NULL, '詠露珠 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3280eb8f-c126-4b93-bab0-8cec8ecb76cb', '詠水精', '詠水精', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["映物隨顏色，含空無表裏。","持來向明月，的皪愁成水。"]', '["映物隨顏色，含空無表裏。","持来向明月，的皪愁成水。"]', '诗', 'shi', '', NULL, '詠水精 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67197b8-91d0-49bc-b9f6-d23f6100a6cc', '詠珊瑚', '詠珊瑚', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["絳樹無花葉，非石亦非瓊。","世人何處得，蓬萊石上生。"]', '["絳樹無花葉，非石亦非瓊。","世人何处得，蓬萊石上生。"]', '诗', 'shi', '', NULL, '詠珊瑚 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac0d8793-4a20-431c-a7bb-739e17489286', '詠瑠璃', '詠瑠璃', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["有色同寒冰，無物隔纖塵。","象筵看不見，堪將對玉人。"]', '["有色同寒冰，無物隔纖塵。","象筵看不见，堪將对玉人。"]', '诗', 'shi', '', NULL, '詠瑠璃 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('026b233d-4b5a-44ba-adfd-b1fe7709f78f', '詠琥珀', '詠琥珀', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["曾爲老茯神，本是寒松液。","蚊蚋落其中，千年猶可覿。"]', '["曾爲老茯神，本是寒松液。","蚊蚋落其中，千年猶可覿。"]', '诗', 'shi', '', NULL, '詠琥珀 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d29beed-bbb0-445a-9158-dfbef0ff65f6', '詠曉', '詠晓', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["軍中始吹角，城上河初落。","深沈猶隱帷，晃朗先分閣。"]', '["軍中始吹角，城上河初落。","深沈猶隐帷，晃朗先分閣。"]', '诗', 'shi', '', NULL, '詠曉 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19ddf4a4-2fc0-45a6-baea-49c76fdbf21f', '詠夜', '詠夜', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["明從何處去，暗從何處來。","但覺年年老，半是此中催。"]', '["明從何处去，暗從何处来。","但覺年年老，半是此中催。"]', '诗', 'shi', '', NULL, '詠夜 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a38ea35-f915-4eaf-ab3e-67c933b1b486', '詠聲', '詠声', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["萬物自生聽，太空恆寂寥。","還從靜中起，却向靜中消。"]', '["万物自生听，太空恆寂寥。","還從静中起，却向静中消。"]', '诗', 'shi', '', NULL, '詠聲 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f888bd99-3f5e-4554-8fbf-23e41e4ae7d8', '任洛陽丞請告一首', '任洛陽丞請告一首', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["方鑿不受圓，直木不爲輪。","揆材各有用，反性生苦辛。","折腰非吾事，飲水非吾貧。","休告臥空館，養病絕囂塵。","遊魚自成族，野鳥亦有羣。","家園杜陵下，千歲心氛氳。","天晴嵩山高，雪後河洛春。","喬木猶未芳，百草日已新。","著書復何爲，當去東臯耘。"]', '["方鑿不受圓，直木不爲輪。","揆材各有用，反性生苦辛。","折腰非吾事，饮水非吾貧。","休告臥空館，養病絕囂塵。","游鱼自成族，野鸟亦有羣。","家园杜陵下，千歲心氛氳。","天晴嵩山高，雪後河洛春。","喬木猶未芳，百草日已新。","著书复何爲，當去东臯耘。"]', '诗', 'shi', '', NULL, '任洛陽丞請告一首 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16bddda4-c09b-4054-8980-e38436d46645', '縣齋', '縣斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["仲春時景好，草木漸舒榮。","公門且無事，微雨園林清。","決決水泉動，忻忻衆鳥鳴。","閑齋始延矚，東作興庶甿。","既事翫文墨，抱沖披道經。","於焉日淡泊，徒使芳尊盈。"]', '["仲春时景好，草木漸舒榮。","公门且無事，微雨园林清。","決決水泉动，忻忻衆鸟鳴。","闲斋始延矚，东作兴庶甿。","既事翫文墨，抱沖披道經。","於焉日淡泊，徒使芳尊盈。"]', '诗', 'shi', '', NULL, '縣齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82bad0de-9226-492b-9280-c7cd9c2e8b14', '晚出府舍與獨孤兵曹令狐士曹南尋朱雀街歸里第', '晚出府舍與独孤兵曹令狐士曹南尋朱雀街归里第', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["分曹幸同簡，聯騎方愜素。","還從廣陌歸，不覺青山暮。","翻翻鳥未沒，杳杳鐘猶度。","尋草遠無人，望山多枉路。","聊參世士跡，嘗得靜者顧。","出入雖見牽，忘身緣所晤。"]', '["分曹幸同簡，聯騎方愜素。","還從廣陌归，不覺青山暮。","翻翻鸟未沒，杳杳鐘猶度。","尋草远無人，望山多枉路。","聊參世士跡，嘗得静者顧。","出入雖见牽，忘身緣所晤。"]', '诗', 'shi', '', NULL, '晚出府舍與獨孤兵曹令狐士曹南尋朱雀街歸里第 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c887f524-fb07-44ef-a726-451575abd917', '休暇東齋', '休暇东斋', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["由來束帶士，請謁無朝暮。","公暇及私身，何能獨閑步。","摘葉愛芳在，捫竹憐粉汚。","岸幘偃東齋，夏天清曉露。","懷仙閱真誥，貽友題幽素。","榮達頗知疎，恬然自成度。","綠苔日已滿，幽寂誰來顧。"]', '["由来束带士，請謁無朝暮。","公暇及私身，何能独闲步。","摘葉愛芳在，捫竹怜粉汚。","岸幘偃东斋，夏天清晓露。","懷仙閱真誥，貽友題幽素。","榮達頗知疎，恬然自成度。","綠苔日已满，幽寂誰来顧。"]', '诗', 'shi', '', NULL, '休暇東齋 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f98be4f-fd25-4757-ba84-9e7f5f30d0fc', '夜直省中', '夜直省中', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["河漢有秋意，南宮生早涼。","玉漏殊杳杳，雲闕更蒼蒼。","華燈發新燄，輕煙浮夕香。","顧跡知爲忝，束帶愧周行。"]', '["河漢有秋意，南宮生早涼。","玉漏殊杳杳，云闕更蒼蒼。","华灯發新燄，轻煙浮夕香。","顧跡知爲忝，束带愧周行。"]', '诗', 'shi', '', NULL, '夜直省中 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c635d5a-3cb8-49d4-9ab1-1f839cad2b05', '郡內閑居', '郡內闲居', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["棲息絕塵侶，孱鈍得自怡。","腰懸竹使符，心與廬山緇。","永日一酣寢，起坐兀無思。","長廊獨看雨，衆藥發幽姿。","今夕已云罷，明晨復如斯。","何事能爲累，寵辱豈要辭。"]', '["棲息絕塵侶，孱鈍得自怡。","腰懸竹使符，心與廬山緇。","永日一酣寢，起坐兀無思。","长廊独看雨，衆藥發幽姿。","今夕已云罷，明晨复如斯。","何事能爲累，寵辱豈要辞。"]', '诗', 'shi', '', NULL, '郡內閑居 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecc776cd-93a9-4bd4-9b81-4335f7702f6f', '燕居即事', '燕居即事', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["蕭條竹林院，風雨叢蘭折。","幽鳥林上啼，青苔人跡絕。","燕居日已永，夏木紛成結。","几閣積羣書，時來北窗閱。"]', '["蕭條竹林院，风雨叢蘭折。","幽鸟林上啼，青苔人跡絕。","燕居日已永，夏木紛成結。","几閣積羣书，时来北窗閱。"]', '诗', 'shi', '', NULL, '燕居即事 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca3440c9-892b-4df3-8fad-6aaf987d1f94', '幽居', '幽居', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["貴賤雖異等，出門皆有營。","獨無外物牽，遂此幽居情。","微雨夜來過，不知春草生。","青山忽已曙，鳥雀繞舍鳴。","時與道人偶，或隨樵者行。","自當安蹇劣，誰謂薄世榮。"]', '["貴賤雖異等，出门皆有營。","独無外物牽，遂此幽居情。","微雨夜来過，不知春草生。","青山忽已曙，鸟雀繞舍鳴。","时與道人偶，或隨樵者行。","自當安蹇劣，誰謂薄世榮。"]', '诗', 'shi', '', NULL, '幽居 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8991e2c7-d6b0-473c-9ccf-3394d16a4a6e', '野居書情', '野居书情', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["世事日可見，身名良蹉跎。","尚瞻白雲嶺，聊作負薪歌。"]', '["世事日可见，身名良蹉跎。","尚瞻白云嶺，聊作負薪歌。"]', '诗', 'shi', '', NULL, '野居書情 韋應物 shi');
